window.LOOT={"items":{"core_item":[{"id":"ci1","src":"core","kind":"item","roll":1,"en":"Premium Bedroll","ende":"During downtime, you automatically clear a Stress.","ru":"Первоклассный Спальный Мешок","rud":"Во время отдыха вы автоматически очищаете Стресс.","img":"ci1.webp"},{"id":"ci2","src":"core","kind":"item","roll":2,"en":"Piper Whistle","ende":"This handcrafted whistle has a distinctive sound. When you blow this whistle, its piercing tone can be heard within a 1-mile radius.","ru":"Пронзительная Свирель","rud":"Эта свирель ручной работы имеет характерный звук. Когда вы дуете в этот свисток, его пронзительный звук слышен в радиусе 1 километра.","img":"ci2.webp"},{"id":"ci3","src":"core","kind":"item","roll":3,"en":"Charging Quiver","ende":"When you succeed on an attack with an arrow stored in this quiver, gain a bonus to the damage roll equal to your current tier.","ru":"Заряжающий Колчан","rud":"Когда вы успешно наносите удар стрелой из этого колчана, получите бонус к Броску Урона, равный вашему текущему Рангу.","img":"ci3.webp"},{"id":"ci4","src":"core","kind":"item","roll":4,"en":"Alistair's Torch","ende":"You can light this magic torch at will. The flame's light fills a much larger space than it should, enough to illuminate a cave bright as day.","ru":"Факел Алистера","rud":"Вы можете зажигать этот магический факел по желанию. Его пламя освещает гораздо большую область, чем должно, - достаточно, чтобы осветить пещеру, как при дневном свете.","img":"ci4.webp"},{"id":"ci5","src":"core","kind":"item","roll":5,"en":"Speaking Orbs","ende":"This pair of orbs allows any creatures holding them to communicate with each other across any distance.","ru":"Разговаривающие Сферы","rud":"Эта пара сфер позволяет существам, которые держат их, общаться друг с другом на любом расстоянии.","img":"ci5.webp"},{"id":"ci6","src":"core","kind":"item","roll":6,"en":"Manacles","ende":"This pair of locking cuffs comes with a key.","ru":"Наручники","rud":"Эта пара наручников с замком поставляется с ключом.","img":"ci6.webp"},{"id":"ci7","src":"core","kind":"item","roll":7,"en":"Arcane Cloak","ende":"A creature with a Spellcast trait wearing this cloak can adjust its color, texture, and size at will.","ru":"Мистический Плащ","rud":"Существо с Характеристикой Заклинателя, носящее этот плащ, может изменять его цвет, текстуру и размер по своему желанию.","img":"ci7.webp"},{"id":"ci8","src":"core","kind":"item","roll":8,"en":"Woven Net","ende":"You can make a Finesse Roll using this net to trap a small creature. A trapped target can break free with a successful Attack Roll (16)","ru":"Плетёная Сеть","rud":"Вы можете совершить Бросок Искусности, используя эту сеть, чтобы поймать небольшое существо. Пойманная цель может освободиться, успешно совершив Бросок Атаки (16)","img":"ci8.webp"},{"id":"ci9","src":"core","kind":"item","roll":9,"en":"Fire Jar","ende":"You can pour out the strange liquid contents of this jar to instantly produce fire. The contents regenerate when you take a long rest.","ru":"Банка с Огнём","rud":"Вы можете вылить странную жидкость из этой банки, чтобы мгновенно разжечь огонь. Содержимое восстанавливается после продолжительного отдыха.","img":"ci9.webp"},{"id":"ci10","src":"core","kind":"item","roll":10,"en":"Suspended Rod","ende":"This flat rod is inscribed with runes. When you activate the rod, it is immediately suspended in place. Until the rod is deactivated, it can't move, doesn't abide by the rules of gravity, and remains in place.","ru":"Подвешенный Жезл","rud":"Этот плоский жезл исписан рунами. Когда вы активируете жезл, он сразу же зависает на месте. До тех пор пока жезл не будет деактивирован, он не подчиняется законам гравитации и остаётся на месте.","img":"ci10.webp"},{"id":"ci11","src":"core","kind":"item","roll":11,"en":"Glamour Stone","ende":"Activate this pebble-sized stone to memorize the appearance of someone you can see. Spend a Hope to magically recreate this guise on yourself as an illusion.","ru":"Камень Облика","rud":"Активируйте этот камень размером с гальку, чтобы запомнить внешность кого-то, кого вы видите. Потратьте Надежду, чтобы магическим образом воссоздать этот облик на себе в виде иллюзии.","img":"ci11.webp"},{"id":"ci12","src":"core","kind":"item","roll":12,"en":"Empty Chest","ende":"This magical chest appears empty. When you speak a specific trigger word or action and open the chest, you can see the items stored within it.","ru":"Пустой Сундук","rud":"Этот магический сундук кажется пустым. Скажите ключевое слово или сделайте условное действие - и вы увидите хранимые внутри вещи.","img":"ci12.webp"},{"id":"ci13","src":"core","kind":"item","roll":13,"en":"Companion Case","ende":"This case can fit a small animal companion. While the companion is inside, the animal and case are immune to all damage and harmful effects.","ru":"Футляр для Компаньона","rud":"В этот футляр можно поместить маленького животного-компаньона. Пока он внутри, оба неуязвимы ко всем видам урона и эффектам.","img":"ci13.webp"},{"id":"ci14","src":"core","kind":"item","roll":14,"en":"Piercing Arrows","ende":"Three times per rest when you succeed on an attack with one of these arrows, you can add your Proficiency to the damage roll.","ru":"Пронзающие Стрелы","rud":"Три раза за отдых, когда вы успешно наносите удар одной из этих стрел, вы можете добавить ваше Мастерство к Броску Урона.","img":"ci14.webp"},{"id":"ci15","src":"core","kind":"item","roll":15,"en":"Valorstone","ende":"You can attach this stone to armor that doesn't already have a feature. The armor gains the following feature. Resilient: Before you mark your last Armor Slot, roll a d6. On a result of 6, reduce the severity by one threshold without marking an Armor Slot.","ru":"Камень Доблести","rud":"Вы можете прикрепить этот камень к доспеху, который ещё не имеет свойств. Доспех получает следующее свойство. Устойчивое: перед тем как отметить последнюю Ячейку Брони, бросьте 1d6. При результате 6 уменьшите тяжесть урона на один порог, не отмечая Ячейку Брони.","img":"ci15.webp"},{"id":"ci16","src":"core","kind":"item","roll":16,"en":"Skeleton Key","ende":"When you use this key to open a locked door, you gain advantage on the Finesse Roll.","ru":"Скелетный Ключ","rud":"Когда вы используете этот ключ, чтобы открыть запертую дверь, вы получаете преимущество на Бросок Искусности.","img":"ci16.webp"},{"id":"ci17","src":"core","kind":"item","roll":17,"en":"Arcane Prism","ende":"Position this prism in a location of your choosing and activate it. All allies within Close range of it gain a +1 bonus to their Spellcast Rolls. While activated, the prism can't be moved. Once the prism is deactivated, it can't be activated again until your next long rest.","ru":"Магическая Призма","rud":"Поместите эту призму в выбранное вами место и активируйте её. Все союзники в пределах Средней дистанции от неё получают бонус +1 к своим Броскам Заклинаний. Пока призма активирована, её нельзя перемещать. После деактивации призму нельзя активировать снова до вашего следующего продолжительного отдыха.","img":"ci17.webp"},{"id":"ci18","src":"core","kind":"item","roll":18,"en":"Minor Stamina Potion Recipe","ende":"As a downtime move, you can use the bone of a creature to craft a Minor Stamina Potion.","ru":"Рецепт Малого Зелья Выносливости","rud":"В качестве Хода Отдыха вы можете использовать кость существа для создания Малого Зелья Выносливости.","img":"ci18.webp"},{"id":"ci19","src":"core","kind":"item","roll":19,"en":"Minor Health Potion Recipe","ende":"As a downtime move, you can use a vial of blood to craft a Minor Health Potion.","ru":"Рецепт Малого Зелья Лечения","rud":"В качестве Хода Отдыха вы можете использовать флакон с кровью для создания Малого Зелья Лечения.","img":"ci19.webp"},{"id":"ci20","src":"core","kind":"item","roll":20,"en":"Homing Compasses","ende":"These two compasses point toward each other no matter how far apart they are.","ru":"Компасы Связи","rud":"Эти два компаса указывают друг на друга, независимо от того, как далеко они находятся друг от друга.","img":"ci20.webp"},{"id":"ci21","src":"core","kind":"item","roll":21,"en":"Corrector Sprite","ende":"This tiny sprite sits in the curve of your ear canal and whispers helpful advice during combat. Once per short rest, you can gain advantage on an attack roll.","ru":"Исправляющий Дух","rud":"Этот крошечный дух сидит в изгибе вашего ушного канала и шепчет полезные советы во время боя. Один раз за короткий отдых вы можете получить преимущество на бросок атаки.","img":"ci21.webp"},{"id":"ci22","src":"core","kind":"item","roll":22,"en":"Gecko Gloves","ende":"You can climb up vertical surfaces and across ceilings.","ru":"Перчатки Геккона","rud":"Вы можете лазать по вертикальным поверхностям и потолкам.","img":"ci22.webp"},{"id":"ci23","src":"core","kind":"item","roll":23,"en":"Lorekeeper","ende":"You can store the name and details of up to three hostile creatures inside this book. You gain a +1 bonus to action rolls against those creatures.","ru":"Хранитель Знаний","rud":"Вы можете сохранить в этой книге имена и подробные сведения о трёх враждебных существах. Вы получаете бонус +1 к броскам действия против этих существ.","img":"ci23.webp"},{"id":"ci24","src":"core","kind":"item","roll":24,"en":"Vial of Darksmoke Recipe","ende":"As a downtime move, you can mark a Stress to craft a Vial of Darksmoke.","ru":"Рецепт Флакона с Чёрным Дымом","rud":"В качестве Хода Отдыха вы можете отметить Стресс, чтобы изготовить Флакон с Чёрным Дымом.","img":"ci24.webp"},{"id":"ci25","src":"core","kind":"item","roll":25,"en":"Bloodstone","ende":"You can attach this stone to a weapon that doesn't already have a feature. The weapon gains the following feature. Brutal: When you roll the maximum value on a damage die, roll an additional damage die.","ru":"Кровавый Камень","rud":"Вы можете прикрепить этот камень к оружию, которое ещё не имеет свойства. Оружие получает следующее свойство. Жестокое: когда вы выбрасываете максимальное значение на кости урона, бросьте дополнительную кость урона.","img":"ci25.webp"},{"id":"ci26","src":"core","kind":"item","roll":26,"en":"Greatstone","ende":"You can attach this stone to a weapon that doesn't already have a feature. The weapon gains the following feature. Powerful: On a successful attack, roll an additional damage die and discard the lowest result.","ru":"Самоцвет Великана","rud":"Вы можете прикрепить этот камень к оружию, которое ещё не имеет свойства. Оружие получает следующее свойство. Мощное: при успешной атаке бросьте дополнительную кость урона и отбросьте наименьший результат.","img":"ci26.webp"},{"id":"ci27","src":"core","kind":"item","roll":27,"en":"Glider","ende":"While falling, you can mark a Stress to deploy this small parachute and glide safely to the ground.","ru":"Парашют","rud":"Во время падения вы можете отметить Стресс, чтобы развернуть этот маленький парашют и безопасно спланировать на землю.","img":"ci27.webp"},{"id":"ci28","src":"core","kind":"item","roll":28,"en":"Ring of Silence","ende":"Spend a Hope to activate this ring. Your footsteps are silent until your next rest.","ru":"Кольцо Тишины","rud":"Потратьте Надежду, чтобы активировать это кольцо. Ваши шаги будут бесшумными до следующего отдыха.","img":"ci28.webp"},{"id":"ci29","src":"core","kind":"item","roll":29,"en":"Calming Pendant","ende":"When you would mark your last Stress, roll a d6. On a result of 5 or higher, don't mark it.","ru":"Успокаивающий Кулон","rud":"Когда вы должны отметить последний Стресс, бросьте 1d6. При результате 5 или выше не отмечайте его.","img":"ci29.webp"},{"id":"ci30","src":"core","kind":"item","roll":30,"en":"Dual Flask","ende":"This flask can hold two different liquids. You can swap between them by flipping a small switch on the flask's side.","ru":"Двойная Фляга","rud":"В эту флягу можно налить две разные жидкости. Переключаться между ними можно с помощью небольшого переключателя на боковой стороне фляги.","img":"ci30.webp"},{"id":"ci31","src":"core","kind":"item","roll":31,"en":"Bag of Ficklesand","ende":"You can convince this small bag of sand to be much heavier or lighter with a successful Presence Roll (10). Additionally, on a successful Finesse Roll (10), you can blow a bit of sand into a target's face to make them temporarily Vulnerable.","ru":"Мешочек Своенравного Песка","rud":"Вы можете убедить этот маленький мешок с песком стать намного тяжелее или легче, успешно выполнив бросок Влияния (10). Кроме того, при успешном броске Искусности (10) вы можете выдуть немного песка в лицо цели, чтобы временно сделать её Уязвимой.","img":"ci31.webp"},{"id":"ci32","src":"core","kind":"item","roll":32,"en":"Ring of Resistance","ende":"Once per long rest, you can activate this ring after a successful attack against you to halve the damage.","ru":"Кольцо Сопротивления","rud":"Один раз за продолжительный отдых вы можете активировать это кольцо после успешной атаки по вам, чтобы уменьшить полученный урон вдвое.","img":"ci32.webp"},{"id":"ci33","src":"core","kind":"item","roll":33,"en":"Phoenix Feather","ende":"If you have at least one Phoenix Feather on you when you fall unconscious, you gain a +1 bonus to the roll you make to determine whether you gain a scar.","ru":"Перо Феникса","rud":"Если у вас есть хотя бы одно Перо Феникса, когда вы теряете сознание, вы получаете бонус +1 к броску, который вы совершаете, чтобы определить, получите ли вы шрам.","img":"ci33.webp"},{"id":"ci34","src":"core","kind":"item","roll":34,"en":"Box of Many Goods","ende":"Once per long rest, you can open this small box and roll a d12. On a result of 1-6, it's empty. On a result of 7-10, it contains one random common consumable. On a result of 11-12, it contains two random common consumables.","ru":"Коробка Многих Вещей","rud":"Один раз за продолжительный отдых вы можете открыть эту маленькую коробку и бросить 1d12. При результате 1-6 она пуста. При результате 7-10 она содержит один случайный обычный расходник. При результате 11-12 она содержит два случайных обычных расходника.","img":"ci34.webp"},{"id":"ci35","src":"core","kind":"item","roll":35,"en":"Airblade Charm","ende":"You can attach this charm to a weapon with a Melee range. Three times per rest, you can activate the charm and attack a target within Close range.","ru":"Амулет Воздушного Клинка","rud":"Вы можете прикрепить этот амулет к оружию с дистанцией Вплотную. Три раза за отдых вы можете активировать амулет и атаковать цель в пределах Средней дистанции.","img":"ci35.webp"},{"id":"ci36","src":"core","kind":"item","roll":36,"en":"Portal Seed","ende":"You can plant this seed in the ground to grow a portal in that spot. The portal is ready to use in 24 hours. You can use this portal to travel to any other location where you planted a portal seed. A portal can be destroyed by dealing any amount of magic damage to it.","ru":"Семя Портала","rud":"Вы можете посадить это семя в землю, чтобы вырастить портал в этом месте. Портал будет готов к использованию через 24 часа. Вы можете использовать этот портал для перемещения в любое другое место, где вы посадили другое семя портала. Портал можно уничтожить, нанеся ему любое количество магического урона.","img":"ci36.webp"},{"id":"ci37","src":"core","kind":"item","roll":37,"en":"Paragon's Chain","ende":"As a downtime move, you can meditate on an ideal or principle you hold dear and focus your will into this chain. Once per long rest, you can spend a Hope to roll a d20 as your Hope Die for rolls that directly align with that principle.","ru":"Цепь Парагона","rud":"В качестве Хода Отдыха вы можете помедитировать над идеалом или принципом, который вам дорог, и сосредоточить свою волю на этой цепи. Один раз за продолжительный отдых вы можете потратить Надежду, чтобы бросить d20 в качестве Кости Надежды для бросков, которые напрямую связаны с этим принципом.","img":"ci37.webp"},{"id":"ci38","src":"core","kind":"item","roll":38,"en":"Elusive Amulet","ende":"Once per long rest, you can activate this amulet to become Hidden until you move. While Hidden in this way, you remain unseen even if an adversary moves to where they would normally see you.","ru":"Амулет Скрытности","rud":"Один раз за продолжительный отдых вы можете активировать этот амулет, чтобы стать Скрытым до тех пор, пока не сдвинетесь с места. Пока вы Скрыты таким образом, вы остаётесь невидимым, даже если противник переместится туда, где обычно мог бы вас увидеть.","img":"ci38.webp"},{"id":"ci39","src":"core","kind":"item","roll":39,"en":"Hopekeeper Locket","ende":"During a long rest, if you have 6 Hope, you can spend a Hope to imbue this locket with your bountiful resolve. When you have 0 Hope, you can use the locket to immediately gain a Hope. The locket must be re-imbued before it can be used this way again.","ru":"Медальон Хранения Надежд","rud":"Во время продолжительного отдыха, если у вас есть 6 Надежды, вы можете потратить одну Надежду, чтобы наполнить этот медальон вашей решимостью. Когда у вас нет Надежды, вы можете использовать медальон, чтобы немедленно получить одну Надежду. Медальон необходимо снова наполнить, прежде чем его снова можно будет использовать таким образом.","img":"ci39.webp"},{"id":"ci40","src":"core","kind":"item","roll":40,"en":"Infinite Bag","ende":"When you store items in this bag, they are kept in a pocket dimension that never runs out of space. You can retrieve an item at any time.","ru":"Бездонная Сумка","rud":"Когда вы храните предметы в этом мешке, они находятся в карманном измерении, где никогда не заканчивается место. Вы можете достать предмет в любое время.","img":"ci40.webp"},{"id":"ci41","src":"core","kind":"item","roll":41,"en":"Stride Relic","ende":"You gain a +1 bonus to your Agility. You can only carry one relic.","ru":"Реликвия Быстрого Шага","rud":"Вы получаете бонус +1 к Проворности. Вы можете носить только одну реликвию.","img":"ci41.webp"},{"id":"ci42","src":"core","kind":"item","roll":42,"en":"Bolster Relic","ende":"You gain a +1 bonus to your Strength. You can only carry one relic.","ru":"Реликвия Усиления","rud":"Вы получаете бонус +1 к Силе. Вы можете носить только одну реликвию.","img":"ci42.webp"},{"id":"ci43","src":"core","kind":"item","roll":43,"en":"Control Relic","ende":"You gain a +1 bonus to your Finesse. You can only carry one relic.","ru":"Реликвия Баланса","rud":"Вы получаете бонус +1 к Искусности. Вы можете носить только одну реликвию.","img":"ci43.webp"},{"id":"ci44","src":"core","kind":"item","roll":44,"en":"Attune Relic","ende":"You gain a +1 bonus to your Instinct. You can only carry one relic.","ru":"Реликвия Гармонии","rud":"Вы получаете бонус +1 к Инстинкту. Вы можете носить только одну реликвию.","img":"ci44.webp"},{"id":"ci45","src":"core","kind":"item","roll":45,"en":"Charm Relic","ende":"You gain a +1 bonus to your Presence. You can only carry one relic.","ru":"Реликвия Очарования","rud":"Вы получаете бонус +1 к Влиянию. Вы можете носить только одну реликвию.","img":"ci45.webp"},{"id":"ci46","src":"core","kind":"item","roll":46,"en":"Enlighten Relic","ende":"You gain a +1 bonus to your Knowledge. You can only carry one relic.","ru":"Реликвия Прозрения","rud":"Вы получаете бонус +1 к Знаниям. Вы можете носить только одну реликвию.","img":"ci46.webp"},{"id":"ci47","src":"core","kind":"item","roll":47,"en":"Honing Relic","ende":"You gain a +1 bonus to an Experience of your choice. You can only carry one relic.","ru":"Реликвия Наставления","rud":"Вы получаете бонус +1 к Опыту по вашему выбору. Вы можете носить только одну реликвию.","img":"ci47.webp"},{"id":"ci48","src":"core","kind":"item","roll":48,"en":"Flickerfly Pendant","ende":"While you carry this pendant, your weapons with a Melee range that deal physical damage have a gossamer sheen and can attack targets within Very Close range.","ru":"Кулон Светлячка","rud":"Пока вы носите этот кулон, ваше оружие с дистанцией атаки Вплотную, наносящее физический урон, имеет тонкий блеск и может атаковать цели в пределах Близкой дистанции.","img":"ci48.webp"},{"id":"ci49","src":"core","kind":"item","roll":49,"en":"Lakestrider Boots","ende":"You can walk on the surface of water as if it were soft ground.","ru":"Ботинки Хождения по Воде","rud":"Вы можете ходить по поверхности воды, как по мягкой земле.","img":"ci49.webp"},{"id":"ci50","src":"core","kind":"item","roll":50,"en":"Clay Companion","ende":"When you sculpt this ball of clay into a clay animal companion, it behaves as that animal. For example, a clay spider can spin clay webs, while a clay bird can fly. The clay companion retains memory and identity across different shapes, but they can adopt new mannerisms with each form.","ru":"Глиняный Спутник","rud":"Когда вы лепите из этого шарика глины глиняного животного-компаньона, он ведёт себя как это животное. Например, глиняный паук может плести глиняные паутины, а глиняная птица может летать. Глиняные компаньоны сохраняют память и индивидуальность при изменении формы, но могут приобретать новые манеры поведения.","img":"ci50.webp"},{"id":"ci51","src":"core","kind":"item","roll":51,"en":"Mythic Dust Recipe","ende":"As a downtime move, you can use a handful of fine gold dust to craft Mythic Dust.","ru":"Рецепт Мифической Пыли","rud":"В качестве Хода Отдыха вы можете использовать горсть мелкой золотой пыли для создания Мифической Пыли.","img":"ci51.webp"},{"id":"ci52","src":"core","kind":"item","roll":52,"en":"Shard of Memory","ende":"Once per long rest, you can spend 2 Hope to recall a domain card from your vault instead of paying its Recall Cost.","ru":"Осколок Памяти","rud":"Один раз за продолжительный отдых вы можете потратить 2 Надежды, чтобы призвать карту домена из вашего хранилища вместо того, чтобы платить её Стоимость Призыва.","img":"ci52.webp"},{"id":"ci53","src":"core","kind":"item","roll":53,"en":"Gem of Alacrity","ende":"You can attach this gem to a weapon, allowing you to use your Agility when making an attack with that weapon.","ru":"Самоцвет Проворства","rud":"Вы можете прикрепить этот самоцвет к оружию, что позволит вам использовать Проворность при совершении атаки этим оружием.","img":"ci53.webp"},{"id":"ci54","src":"core","kind":"item","roll":54,"en":"Gem of Might","ende":"You can attach this gem to a weapon, allowing you to use your Strength when making an attack with that weapon.","ru":"Самоцвет Мощи","rud":"Вы можете прикрепить этот самоцвет к оружию, что позволит вам использовать Силу при совершении атаки этим оружием.","img":"ci54.webp"},{"id":"ci55","src":"core","kind":"item","roll":55,"en":"Gem of Precision","ende":"You can attach this gem to a weapon, allowing you to use your Finesse when making an attack with that weapon.","ru":"Самоцвет Точности","rud":"Вы можете прикрепить этот самоцвет к оружию, что позволит вам использовать Искусность при совершении атаки этим оружием.","img":"ci55.webp"},{"id":"ci56","src":"core","kind":"item","roll":56,"en":"Gem of Insight","ende":"You can attach this gem to a weapon, allowing you to use your Instinct when making an attack with that weapon.","ru":"Самоцвет Чутья","rud":"Вы можете прикрепить этот самоцвет к оружию, что позволит вам использовать Инстинкт при совершении атаки этим оружием.","img":"ci56.webp"},{"id":"ci57","src":"core","kind":"item","roll":57,"en":"Gem of Audacity","ende":"You can attach this gem to a weapon, allowing you to use your Presence when making an attack with that weapon.","ru":"Самоцвет Дерзости","rud":"Вы можете прикрепить этот самоцвет к оружию, что позволит вам использовать Влияние при совершении атаки этим оружием.","img":"ci57.webp"},{"id":"ci58","src":"core","kind":"item","roll":58,"en":"Gem of Sagacity","ende":"You can attach this gem to a weapon, allowing you to use your Knowledge when making an attack with that weapon.","ru":"Самоцвет Рассудительности","rud":"Вы можете прикрепить этот самоцвет к оружию, что позволит вам использовать Знание при совершении атаки этим оружием.","img":"ci58.webp"},{"id":"ci59","src":"core","kind":"item","roll":59,"en":"Ring of Unbreakable Resolve","ende":"Once per session, when the GM spends a Fear, you can spend 4 Hope to cancel the effects of that spent Fear.","ru":"Кольцо Несокрушимой Решимости","rud":"Один раз за сессию, когда Мастер тратит Страх, вы можете потратить 4 Надежды, чтобы отменить эффект потраченного Страха.","img":"ci59.webp"},{"id":"ci60","src":"core","kind":"item","roll":60,"en":"Belt of Unity","ende":"Once per session, you can spend 5 Hope to lead a Tag Team Roll with three PCs instead of two.","ru":"Пояс Единства","rud":"Один раз за сессию вы можете потратить 5 Надежды, чтобы провести Командный Бросок с тремя персонажами вместо двух.","img":"ci60.webp"}],"core_consumable":[{"id":"cc1","src":"core","kind":"consumable","roll":1,"en":"Stride Potion","ende":"You gain a +1 bonus to your next Agility Roll.","ru":"Зелье Быстрого Шага","rud":"Вы получаете бонус +1 к следующему броску Проворности.","img":"cc1.webp"},{"id":"cc2","src":"core","kind":"consumable","roll":2,"en":"Bolster Potion","ende":"You gain a +1 bonus to your next Strength Roll.","ru":"Зелье Усиления","rud":"Вы получаете бонус +1 к следующему броску Силы.","img":"cc2.webp"},{"id":"cc3","src":"core","kind":"consumable","roll":3,"en":"Control Potion","ende":"You gain a +1 bonus to your next Finesse Roll.","ru":"Зелье Сосредоточенности","rud":"Вы получаете бонус +1 к следующему броску Искусности.","img":"cc3.webp"},{"id":"cc4","src":"core","kind":"consumable","roll":4,"en":"Attune Potion","ende":"You gain a +1 bonus to your next Instinct Roll.","ru":"Зелье Гармонии","rud":"Вы получаете бонус +1 к следующему броску Инстинкта.","img":"cc4.webp"},{"id":"cc5","src":"core","kind":"consumable","roll":5,"en":"Charm Potion","ende":"You gain a +1 bonus to your next Presence Roll.","ru":"Зелье Очарования","rud":"Вы получаете бонус +1 к следующему броску Влияния.","img":"cc5.webp"},{"id":"cc6","src":"core","kind":"consumable","roll":6,"en":"Enlighten Potion","ende":"You gain a +1 bonus to your next Knowledge Roll.","ru":"Зелье Просветления","rud":"Вы получаете бонус +1 к следующему броску Знаний.","img":"cc6.webp"},{"id":"cc7","src":"core","kind":"consumable","roll":7,"en":"Minor Health Potion","ende":"Clear 1d4 HP.","ru":"Малое Зелье Лечения","rud":"Излечите 1d4 Ран.","img":"cc7.webp"},{"id":"cc8","src":"core","kind":"consumable","roll":8,"en":"Minor Stamina Potion","ende":"Clear 1d4 Stress.","ru":"Малое Зелье Выносливости","rud":"Очистите 1d4 Стресса.","img":"cc8.webp"},{"id":"cc9","src":"core","kind":"consumable","roll":9,"en":"Grindletooth Venom","ende":"You can apply this venom to a weapon that deals physical damage to add a d6 to your next damage roll with that weapon.","ru":"Яд Скрежетозуба","rud":"Вы можете нанести этот яд на оружие, наносящее физический урон, чтобы добавить 1d6 к вашему следующему броску урона этим оружием.","img":"cc9.webp"},{"id":"cc10","src":"core","kind":"consumable","roll":10,"en":"Varik Leaves","ende":"You can eat these paired leaves to immediately gain 2 Hope.","ru":"Листья Варика","rud":"Вы можете съесть эти спаренные листья, чтобы сразу получить 2 Надежды.","img":"cc10.webp"},{"id":"cc11","src":"core","kind":"consumable","roll":11,"en":"Vial of Moondrip","ende":"When you drink the contents of this vial, you can see in total darkness until your next rest.","ru":"Флакон с Лунной Каплей","rud":"Выпив содержимое этого флакона, вы сможете видеть в полной темноте до следующего отдыха.","img":"cc11.webp"},{"id":"cc12","src":"core","kind":"consumable","roll":12,"en":"Unstable Arcane Shard","ende":"You can make a Finesse Roll to throw this shard at a group of adversaries within Far range. Targets you succeed against take 1d20 magic damage.","ru":"Нестабильный Мистический Осколок","rud":"Вы можете совершить бросок Искусности, чтобы бросить этот осколок в группу противников в пределах Далекой дистанции. Цели, против которых вы преуспели, получают 1d20 магического урона.","img":"cc12.webp"},{"id":"cc13","src":"core","kind":"consumable","roll":13,"en":"Potion of Stability","ende":"You can drink this potion to choose one additional downtime move.","ru":"Зелье Стойкости","rud":"Вы можете выпить это зелье, чтобы выбрать одно дополнительное действие привала.","img":"cc13.webp"},{"id":"cc14","src":"core","kind":"consumable","roll":14,"en":"Improved Grindletooth Venom","ende":"You can apply this venom to a weapon that deals physical damage to add a d8 to your next damage roll with that weapon.","ru":"Улучшенный Яд Скрежетозуба","rud":"Вы можете нанести этот яд на оружие, наносящее физический урон, чтобы добавить 1d8 к вашему следующему броску урона этим оружием.","img":"cc14.webp"},{"id":"cc15","src":"core","kind":"consumable","roll":15,"en":"Morphing Clay","ende":"You can spend a Hope to use this clay, altering your face enough to make you unrecognizable until your next rest.","ru":"Глина Перевоплощения","rud":"Вы можете потратить Надежду, чтобы использовать эту глину, изменив свое лицо настолько, что вас не узнают до следующего отдыха.","img":"cc15.webp"},{"id":"cc16","src":"core","kind":"consumable","roll":16,"en":"Vial of Darksmoke","ende":"When an adversary attacks you, use this vial and roll a number of d6s equal to your Agility. Add the highest result to your Evasion against the attack.","ru":"Флакон с Чёрным Дымом","rud":"Когда противник атакует вас, используйте этот флакон и бросьте количество d6, равное вашей Проворности. Добавьте самый высокий результат к вашему Уклонению от этой атаки.","img":"cc16.webp"},{"id":"cc17","src":"core","kind":"consumable","roll":17,"en":"Jumping Root","ende":"Eat this root to leap up to Far range once without needing to roll.","ru":"Прыгающий Корень","rud":"Съешьте этот корень, чтобы один раз прыгнуть на Далекую дистанцию без необходимости бросать кость.","img":"cc17.webp"},{"id":"cc18","src":"core","kind":"consumable","roll":18,"en":"Snap Powder","ende":"Mark a Stress and clear a HP.","ru":"Порошок Встряски","rud":"Отметьте Стресс, чтобы очистить Рану.","img":"cc18.webp"},{"id":"cc19","src":"core","kind":"consumable","roll":19,"en":"Health Potion","ende":"Clear 1d4+1 HP.","ru":"Зелье Лечения","rud":"Излечите 1d4+1 Ран.","img":"cc19.webp"},{"id":"cc20","src":"core","kind":"consumable","roll":20,"en":"Stamina Potion","ende":"Clear 1d4+1 Stress.","ru":"Зелье Выносливости","rud":"Очистите 1d4+1 Стресса.","img":"cc20.webp"},{"id":"cc21","src":"core","kind":"consumable","roll":21,"en":"Armor Stitcher","ende":"You can use this stitcher to spend any number of Hope and clear that many Armor Slots.","ru":"Доспешный Сшиватель","rud":"Вы можете использовать этот швейный аппарат, чтобы потратить любое количество Надежды и очистить столько же Ячеек Брони.","img":"cc21.webp"},{"id":"cc22","src":"core","kind":"consumable","roll":22,"en":"Gill Salve","ende":"You can apply this salve to your neck to breathe underwater for a number of minutes equal to your level.","ru":"Жаберная Мазь","rud":"Вы можете нанести эту мазь на шею, чтобы дышать под водой в течение минут, равных вашему уровню.","img":"cc22.webp"},{"id":"cc23","src":"core","kind":"consumable","roll":23,"en":"Replication Parchment","ende":"By touching this piece of parchment to another, you can perfectly copy the second parchment's contents. Once used, this parchment becomes mundane paper.","ru":"Пергамент Копирования","rud":"Прикоснувшись этим пергаментом к другому, вы можете идеально скопировать содержимое второго пергамента. После использования этот пергамент становится обычной бумагой.","img":"cc23.webp"},{"id":"cc24","src":"core","kind":"consumable","roll":24,"en":"Improved Arcane Shard","ende":"You can make a Finesse Roll to throw this shard at a group of adversaries within Far range. Targets you succeed against take 2d20 magic damage.","ru":"Улучшенный Мистический Осколок","rud":"Вы можете совершить бросок Искусности, чтобы бросить этот осколок в группу противников в пределах Далекой дистанции. Цели, против которых вы преуспели, получают 2d20 урона от магии.","img":"cc24.webp"},{"id":"cc25","src":"core","kind":"consumable","roll":25,"en":"Major Stride Potion","ende":"You gain a +1 bonus to your Agility until your next rest.","ru":"Большое Зелье Быстрого Шага","rud":"Вы получаете бонус +1 к Проворности до следующего отдыха.","img":"cc25.webp"},{"id":"cc26","src":"core","kind":"consumable","roll":26,"en":"Major Bolster Potion","ende":"You gain a +1 bonus to your Strength until your next rest.","ru":"Большое Зелье Усиления","rud":"Вы получаете бонус +1 к Силе до следующего отдыха.","img":"cc26.webp"},{"id":"cc27","src":"core","kind":"consumable","roll":27,"en":"Major Control Potion","ende":"You gain a +1 bonus to your Finesse until your next rest.","ru":"Большое Зелье Сосредоточенности","rud":"Вы получаете бонус +1 к Искусности до следующего отдыха.","img":"cc27.webp"},{"id":"cc28","src":"core","kind":"consumable","roll":28,"en":"Major Attune Potion","ende":"You gain a +1 bonus to your Instinct until your next rest.","ru":"Большое Зелье Гармонии","rud":"Вы получаете бонус +1 к Инстинкту до следующего отдыха.","img":"cc28.webp"},{"id":"cc29","src":"core","kind":"consumable","roll":29,"en":"Major Charm Potion","ende":"You gain a +1 bonus to your Presence until your next rest.","ru":"Большое Зелье Обаяния","rud":"Вы получаете бонус +1 к Влиянию до следующего отдыха.","img":"cc29.webp"},{"id":"cc30","src":"core","kind":"consumable","roll":30,"en":"Major Enlighten Potion","ende":"You gain a +1 bonus to your Knowledge until your next rest.","ru":"Большое Зелье Просветления","rud":"Вы получаете бонус +1 к Знаниям до следующего отдыха.","img":"cc30.webp"},{"id":"cc31","src":"core","kind":"consumable","roll":31,"en":"Blood of the Yorgi","ende":"You can drink this blood to disappear from where you are and immediately reappear at a point you can see within Very Far range.","ru":"Кровь Йорги","rud":"Вы можете выпить эту кровь, чтобы исчезнуть с того места, где вы находитесь, и сразу же появиться в точке, которую вы можете видеть в пределах Очень Далекой дистанции.","img":"cc31.webp"},{"id":"cc32","src":"core","kind":"consumable","roll":32,"en":"Homet's Secret Potion","ende":"After drinking this potion, the next successful attack you make critically succeeds.","ru":"Секретное Зелье Хомета","rud":"После выпивания этого зелья следующий успешный бросок атаки вместо этого получает критический успех.","img":"cc32.webp"},{"id":"cc33","src":"core","kind":"consumable","roll":33,"en":"Redthorn Saliva","ende":"You can apply this saliva to a weapon that deals physical damage to add a d12 to your next damage roll with that weapon.","ru":"Слюна Красношипа","rud":"Вы можете нанести эту слюну на оружие, наносящее физический урон, чтобы добавить 1d12 к вашему следующему броску урона этим оружием.","img":"cc33.webp"},{"id":"cc34","src":"core","kind":"consumable","roll":34,"en":"Channelstone","ende":"You can use this stone to take a spell or grimoire from your vault, use it once, and return it to your vault.","ru":"Проводящий Камень","rud":"Вы можете использовать этот камень, чтобы взять заклинание или гримуар из своего хранилища, использовать его один раз и вернуть в хранилище.","img":"cc34.webp"},{"id":"cc35","src":"core","kind":"consumable","roll":35,"en":"Mythic Dust","ende":"You can apply this dust to a weapon that deals magic damage to add a d12 to your next damage roll with that weapon.","ru":"Мифическая Пыль","rud":"Вы можете нанести эту пыль на оружие, наносящее магический урон, чтобы добавить d12 к вашему следующему броску урона этим оружием.","img":"cc35.webp"},{"id":"cc36","src":"core","kind":"consumable","roll":36,"en":"Acidpaste","ende":"This paste eats away walls and other surfaces in bright flashes.","ru":"Кислотная Паста","rud":"Паста прожигает стены и другие поверхности яркими вспышками.","img":"cc36.webp"},{"id":"cc37","src":"core","kind":"consumable","roll":37,"en":"Hopehold Flare","ende":"When you use this flare, allies within Close range roll a d6 when they spend a Hope. On a result of 6, they gain the effect of that Hope without spending it. The flare lasts until the end of the scene.","ru":"Пламя Надежды","rud":"При использовании союзники в пределах Средней дистанции бросают 1d6, когда тратят Надежду. При результате 6 они получают эффект Надежды без её траты. Пламя действует до конца сцены.","img":"cc37.webp"},{"id":"cc38","src":"core","kind":"consumable","roll":38,"en":"Major Arcane Shard","ende":"You can make a Finesse Roll to throw this shard at a group of adversaries within Far range. Targets you succeed against take 4d20 magic damage.","ru":"Большой Мистический Осколок","rud":"Вы можете совершить Бросок Искусности, чтобы бросить этот осколок в группу противников в пределах Далекой дистанции. Цели, против которых вы преуспели, получают 4d20 урона от магии.","img":"cc38.webp"},{"id":"cc39","src":"core","kind":"consumable","roll":39,"en":"Featherbone","ende":"You can use this bone to control your falling speed for a number of minutes equal to your level.","ru":"Пуховая Кость","rud":"Используйте, чтобы замедлить своё падение на количество минут, равное вашему уровню.","img":"cc39.webp"},{"id":"cc40","src":"core","kind":"consumable","roll":40,"en":"Circle of the Void","ende":"Mark a Stress to create a void that extends up to Far range. No magic can be cast inside the void, and creatures within the void are immune to magic damage.","ru":"Круг Пустоты","rud":"Отметьте Стресс, чтобы создать пустоту, которая распространяется на Далекую дистанцию. Внутри пустоты нельзя использовать магию, а существа, находящиеся в ней, имеют иммунитет к магическому урону.","img":"cc40.webp"},{"id":"cc41","src":"core","kind":"consumable","roll":41,"en":"Sun Tree Sap","ende":"Consume this sap to roll a d6. On a result of 5-6, clear 2 HP. On a result of 2-4, clear 3 Stress. On a result of 1, see through the veil of death and return changed, gaining one scar.","ru":"Сок Солнечного Древа","rud":"Употребите этот сок, чтобы бросить 1d6. При результате 5-6 очистите 2 Раны. При результате 2-4 очистите 3 Стресса. При результате 1 загляните сквозь завесу смерти и вернитесь изменённым, получив один шрам.","img":"cc41.webp"},{"id":"cc42","src":"core","kind":"consumable","roll":42,"en":"Dripfang Poison","ende":"A creature who consumes this poison takes 8d10 direct magic damage.","ru":"Яд Каплезуба","rud":"Существо, которое употребляет этот яд, получает 8d10 прямого магического урона.","img":"cc42.webp"},{"id":"cc43","src":"core","kind":"consumable","roll":43,"en":"Major Health Potion","ende":"Clear 1d4+2 HP.","ru":"Большое Зелье Лечения","rud":"Излечите 1d4+2 Ран.","img":"cc43.webp"},{"id":"cc44","src":"core","kind":"consumable","roll":44,"en":"Major Stamina Potion","ende":"Clear 1d4+2 Stress.","ru":"Большое Зелье Выносливости","rud":"Очистите 1d4+2 Стресса.","img":"cc44.webp"},{"id":"cc45","src":"core","kind":"consumable","roll":45,"en":"Ogre Musk","ende":"You can use this musk to prevent anyone from tracking you by mundane or magical means until your next rest.","ru":"Мускус Огра","rud":"Вы можете использовать этот мускус, чтобы никто не смог отследить вас обычными или магическими средствами до вашего следующего отдыха.","img":"cc45.webp"},{"id":"cc46","src":"core","kind":"consumable","roll":46,"en":"Wingsprout","ende":"You gain magic wings that allow you to fly for a number of minutes equal to your level.","ru":"Крылокорень","rud":"Вы получаете волшебные крылья, которые позволяют вам летать в течение минут, равных вашему уровню.","img":"cc46.webp"},{"id":"cc47","src":"core","kind":"consumable","roll":47,"en":"Jar of Lost Voices","ende":"You can open this jar to release a deafening echo of voices for a number of minutes equal to your Instinct. Creatures within Far range unprepared for the sound take 6d8 magic damage.","ru":"Сосуд Потерянных Голосов","rud":"Вы можете открыть этот сосуд, чтобы выпустить оглушающее эхо голосов на количество минут, равное вашему Инстинкту. Существа в пределах Далекой дистанции, не подготовленные к звуку, получают 6d8 урона от магии.","img":"cc47.webp"},{"id":"cc48","src":"core","kind":"consumable","roll":48,"en":"Dragonbloom Tea","ende":"You can drink this tea to unleash a fiery breath attack. Make an Instinct Roll against all adversaries in front of you within Close range. Targets you succeed against take d20 physical damage using your Proficiency.","ru":"Чай Драконьего Цветка","rud":"Вы можете выпить этот чай, чтобы совершить атаку огненным дыханием. Сделайте Бросок Инстинкта против всех противников перед вами в пределах Средней дистанции. Цели, против которых вы преуспели, получают d20 физического урона с использованием вашего Мастерства.","img":"cc48.webp"},{"id":"cc49","src":"core","kind":"consumable","roll":49,"en":"Bridge Seed","ende":"Thick vines grow from your location to a point of your choice within Far range, allowing you to climb up or across them. The vines dissipate on your next short rest.","ru":"Семя Крепкого Моста","rud":"Толстые лианы растут от вашего местоположения до выбранной вами точки в пределах Далекой дистанции, позволяя вам подниматься по ним вверх или перебираться через них. Лианы исчезают после вашего следующего короткого отдыха.","img":"cc49.webp"},{"id":"cc50","src":"core","kind":"consumable","roll":50,"en":"Sleeping Sap","ende":"You can drink this potion to fall asleep for a full night's rest. You clear all Stress upon waking.","ru":"Усыпляющий Сок","rud":"Вы можете выпить это зелье, чтобы заснуть и хорошо отдохнуть всю ночь. Проснувшись, вы очищаете весь Стресс.","img":"cc50.webp"},{"id":"cc51","src":"core","kind":"consumable","roll":51,"en":"Feast of Xuria","ende":"You can eat this meal to clear all HP and Stress and gain 1d4 Hope.","ru":"Пир Ксурии","rud":"Вы можете съесть эту еду, чтобы исцелить все Раны и Стресс и получить 1d4 Надежды.","img":"cc51.webp"},{"id":"cc52","src":"core","kind":"consumable","roll":52,"en":"Bonding Honey","ende":"This honey can be used to glue two objects together permanently.","ru":"Склеивающий Мёд","rud":"Этот мёд можно использовать для постоянного склеивания двух предметов.","img":"cc52.webp"},{"id":"cc53","src":"core","kind":"consumable","roll":53,"en":"Shrinking Potion","ende":"You can drink this potion to halve your size until you choose to drop this form or your next rest. While in this form, you have a +2 bonus to Agility and a -1 penalty to your Proficiency.","ru":"Зелье Уменьшения","rud":"Вы можете выпить это зелье, чтобы уменьшить свой размер вдвое, пока не решите отказаться от этой формы или не сделаете следующий отдых. В этой форме вы получаете бонус +2 к Проворности и штраф -1 к Мастерству.","img":"cc53.webp"},{"id":"cc54","src":"core","kind":"consumable","roll":54,"en":"Growing Potion","ende":"You can drink this potion to double your size until you choose to drop this form or your next rest. While in this form, you have a +2 bonus to Strength and a +1 bonus to your Proficiency.","ru":"Зелье Увеличения","rud":"Вы можете выпить это зелье, чтобы удвоить свой размер, пока не решите отказаться от этой формы или не наступит следующий отдых. В этой форме вы получаете бонус +2 к Силе и +1 к Мастерству.","img":"cc54.webp"},{"id":"cc55","src":"core","kind":"consumable","roll":55,"en":"Knowledge Stone","ende":"If you die while holding this stone, an ally can take a card from your loadout to place in their loadout or vault. After they take this knowledge, the stone crumbles.","ru":"Камень Знаний","rud":"Если вы погибаете, держа при себе этот камень, союзник может забрать карту из вашей Руки и поместить её в свою Руку или Хранилище. После того, как он примет это знание, камень рассыпается.","img":"cc55.webp"},{"id":"cc56","src":"core","kind":"consumable","roll":56,"en":"Sweet Moss","ende":"You can consume this moss during a rest to clear 1d10 HP or 1d10 Stress.","ru":"Сладкий Мох","rud":"Вы можете съесть этот мох во время отдыха, чтобы очистить 1d10 Ран или 1d10 Стресса.","img":"cc56.webp"},{"id":"cc57","src":"core","kind":"consumable","roll":57,"en":"Blinding Orb","ende":"You can activate this orb to create a flash of bright light. All targets within Close range become Vulnerable until they mark HP.","ru":"Ослепляющая Сфера","rud":"Вы можете активировать эту сферу, чтобы создать вспышку яркого света. Все цели в пределах Средней дистанции становятся Уязвимыми, пока не отметят Рану.","img":"cc57.webp"},{"id":"cc58","src":"core","kind":"consumable","roll":58,"en":"Death Tea","ende":"After you drink this tea, you instantly kill your target when you critically succeed on an attack. If you don't critically succeed on an attack before your next long rest, you die.","ru":"Чай Смерти","rud":"После того как вы выпьете этот чай, вы мгновенно убиваете свою цель, когда выбрасываете критический успех на атаку. Если вы не наносите критически успешный удар до вашего следующего продолжительного отдыха, вы умираете.","img":"cc58.webp"},{"id":"cc59","src":"core","kind":"consumable","roll":59,"en":"Mirror of Marigold","ende":"When you take damage, you can spend a Hope to negate that damage, after which the mirror shatters.","ru":"Зеркало Златоцвета","rud":"Когда вы получаете урон, вы можете потратить Надежду, чтобы отменить этот урон, после чего зеркало разбивается.","img":"cc59.webp"},{"id":"cc60","src":"core","kind":"consumable","roll":60,"en":"Stardrop","ende":"You can use this stardrop to summon a hailstorm of comets that deals 8d20 physical damage to all targets within Very Far range.","ru":"Звёздная Капля","rud":"Вы можете использовать эту звездную каплю, чтобы вызвать град комет, который наносит 8d20 физического урона всем целям в пределах Очень Далекой дистанции.","img":"cc60.webp"}],"hnf_item":[{"id":"hi1","src":"hnf","kind":"item","roll":1,"en":"Caltrops","ende":"You can spread these caltrops in a Very Close area around you. A creature hastening through that area must mark a Stress.","ru":"Шипы","rud":"Вы можете рассыпать эти шипы в пределах Близкой дистанции вокруг себя. Если существо пересекает эту область в спешке, оно должно отметить Стресс.","img":"hi1.webp"},{"id":"hi2","src":"hnf","kind":"item","roll":2,"en":"Grapnel","ende":"You gain advantage on action rolls to climb sheer surfaces.","ru":"Крюк-Кошка","rud":"Вы получаете преимущество на броски действия, когда взбираетесь по отвесным поверхностям.","img":"hi2.webp"},{"id":"hi3","src":"hnf","kind":"item","roll":3,"en":"Ball Bearings","ende":"This pouch contains perfectly smooth metal spheres.","ru":"Металлические Шарики","rud":"В этом мешочке лежат идеально гладкие металлические шарики.","img":"hi3.webp"},{"id":"hi4","src":"hnf","kind":"item","roll":4,"en":"Box of Dragon Dust","ende":"This snuffbox is filled with combustible powder.","ru":"Табакерка Драконьей Пыли","rud":"Эта табакерка наполнена горючим порошком.","img":"hi4.webp"},{"id":"hi5","src":"hnf","kind":"item","roll":5,"en":"Nighthawker's Ring","ende":"Spend a Hope to activate the gemstone in this ring until the end of the scene. While active, the gemstone changes color to indicate the wearer's proximity to hidden treasure: warm colors for near, cool colors for far.","ru":"Кольцо Ночного Ловчего","rud":"Потратьте Надежду, чтобы до конца сцены активировать самоцвет в этом кольце. Пока он активен, его цвет выдаёт близость спрятанного сокровища: чем теплее оттенок, тем оно ближе, а чем холоднее, тем дальше.","img":"hi5.webp"},{"id":"hi6","src":"hnf","kind":"item","roll":6,"en":"Elven Spyglass","ende":"You can use this spyglass to magnify your vision a hundredfold.","ru":"Эльфийская Подзорная Труба","rud":"Эта подзорная труба увеличивает изображение в сто раз.","img":"hi6.webp"},{"id":"hi7","src":"hnf","kind":"item","roll":7,"en":"Gourmet Granules","ende":"This savory powder makes any food it's sprinkled on delicious and healthy, no matter how bland or rotten it is.","ru":"Поварские Гранулы","rud":"Этот пряный порошок делает вкусной и полезной любую еду, которую им посыпали, какой бы пресной или испорченной она ни была.","img":"hi7.webp"},{"id":"hi8","src":"hnf","kind":"item","roll":8,"en":"Collapsible Pole","ende":"You can break down this 18-foot pole into six interlinked 3-foot segments.","ru":"Складной Шест","rud":"Этот шест длиной шесть метров разбирается на шесть сцепленных сегментов по метру.","img":"hi8.webp"},{"id":"hi9","src":"hnf","kind":"item","roll":9,"en":"Blackwing Quill","ende":"This writing quill never runs out of ink or needs to be sharpened.","ru":"Перо Чернокрыла","rud":"В этом пере никогда не кончаются чернила, и его не нужно затачивать.","img":"hi9.webp"},{"id":"hi10","src":"hnf","kind":"item","roll":10,"en":"Silee's Folding Knife","ende":"This 3-inch blade has an edge that easily cuts through anything except the handle it's stored in.","ru":"Складной Нож Силеи","rud":"Этот клинок длиной восемь сантиметров легко разрезает что угодно, кроме рукояти, в которой хранится.","img":"hi10.webp"},{"id":"hi11","src":"hnf","kind":"item","roll":11,"en":"Windup Toy","ende":"This small mechanical device is shaped like a strixwolf pup and can be programmed to perform simple tricks.","ru":"Заводная Игрушка","rud":"Это небольшое механическое устройство в форме щенка совиного волка можно настроить на выполнение простых трюков.","img":"hi11.webp"},{"id":"hi12","src":"hnf","kind":"item","roll":12,"en":"Loaded Dice","ende":"You can choose what result this set of weighted dice rolls with a successful Finesse Roll (14). If you roll with Fear, anyone watching knows the dice are loaded.","ru":"Утяжелённые Кости","rud":"При успешном броске Искусности (14) вы выбираете, что выпадет на этих костях. Если вы бросаете со Страхом, все, кто смотрит, понимают, что кости утяжелены.","img":"hi12.webp"},{"id":"hi13","src":"hnf","kind":"item","roll":13,"en":"Hollowbark Horn","ende":"You can blow this horn to summon a small woodland creature to perform a simple task.","ru":"Рог Полодрева","rud":"Подув в этот рог, вы призываете небольшое лесное существо, чтобы оно выполнило простое поручение.","img":"hi13.webp"},{"id":"hi14","src":"hnf","kind":"item","roll":14,"en":"Self-Tying Rope","ende":"You can command this rope to tie or untie itself.","ru":"Самовяжущаяся Верёвка","rud":"Вы можете приказать этой верёвке завязаться или развязаться.","img":"hi14.webp"},{"id":"hi15","src":"hnf","kind":"item","roll":15,"en":"Thief's Compass","ende":"This compass points the way toward the nearest exit while indoors and the closest entrance while outdoors.","ru":"Воровской Компас","rud":"В помещении этот компас указывает на ближайший выход, а снаружи — на ближайший вход.","img":"hi15.webp"},{"id":"hi16","src":"hnf","kind":"item","roll":16,"en":"Traveler's Bell","ende":"Once per long rest, you can ring this bell to magically open the shortest safe path through rough terrain for 1 hour.","ru":"Колокольчик Странника","rud":"Один раз до следующего продолжительного отдыха вы можете позвонить в этот колокольчик, и на час магически откроется кратчайший безопасный путь через труднопроходимую местность.","img":"hi16.webp"},{"id":"hi17","src":"hnf","kind":"item","roll":17,"en":"Mandragorian Torch","ende":"This torch gives off light only the bearer can see.","ru":"Мандрагорский Факел","rud":"Этот факел даёт свет, видимый только тому, кто его несёт.","img":"hi17.webp"},{"id":"hi18","src":"hnf","kind":"item","roll":18,"en":"Boots of Supple Mystique","ende":"While wearing these boots, you don't leave tracks or footprints.","ru":"Сапоги Мягкой Поступи","rud":"Пока вы носите эти сапоги, вы не оставляете следов.","img":"hi18.webp"},{"id":"hi19","src":"hnf","kind":"item","roll":19,"en":"Zephyr's Jar","ende":"You can open this empty jar during inclement weather to capture the storm and leave behind clear skies. The storm remains inside until unleashed by reopening the jar.","ru":"Сосуд Западного Ветра","rud":"Открыв этот пустой сосуд в непогоду, вы ловите бурю и оставляете после себя ясное небо. Буря остаётся внутри, пока сосуд не откроют снова.","img":"hi19.webp"},{"id":"hi20","src":"hnf","kind":"item","roll":20,"en":"Returning Ring","ende":"When you throw your primary weapon while wearing this ring, the weapon appears in your hand immediately after the attack.","ru":"Кольцо Возвращения","rud":"Пока вы носите это кольцо, брошенное основное оружие возвращается вам в руку сразу после атаки.","img":"hi20.webp"},{"id":"hi21","src":"hnf","kind":"item","roll":21,"en":"Kingfisher's Net","ende":"Once per long rest, you can use this net to scoop one live fish out of any amount of water, no matter how unlikely it is for that water to have fish in it.","ru":"Сеть Зимородка","rud":"Один раз до следующего продолжительного отдыха вы можете выловить этой сетью одну живую рыбу из любого количества воды, даже если ей там взяться неоткуда.","img":"hi21.webp"},{"id":"hi22","src":"hnf","kind":"item","roll":22,"en":"Titan's Girdle","ende":"Once per scene, you can activate this girdle to gain a +1 bonus to your Proficiency for your next attack.","ru":"Пояс Титана","rud":"Один раз за сцену вы можете активировать этот пояс и получить +1 к Мастерству для следующей атаки.","img":"hi22.webp"},{"id":"hi23","src":"hnf","kind":"item","roll":23,"en":"Iron Veil","ende":"This chain-link head covering renders the wearer invisible to fey creatures.","ru":"Железная Вуаль","rud":"Этот кольчужный головной убор делает носителя невидимым для фейских существ.","img":"hi23.webp"},{"id":"hi24","src":"hnf","kind":"item","roll":24,"en":"Furball Bag","ende":"Once per rest, you can produce 2d20 harmless, cat-sized fur creatures of indeterminate origin and species from this bag.","ru":"Мешок Пушистиков","rud":"Один раз до следующего отдыха вы можете достать из этого мешка 2d20 безобидных пушистых существ неопределённого происхождения и вида, каждое размером с кошку.","img":"hi24.webp"},{"id":"hi25","src":"hnf","kind":"item","roll":25,"en":"Whisperstep Anklet","ende":"This anklet makes your steps silent as long as you don't move faster than walking speed.","ru":"Браслет Тихого Шага","rud":"Этот ножной браслет делает ваши шаги бесшумными, пока вы идёте шагом.","img":"hi25.webp"},{"id":"hi26","src":"hnf","kind":"item","roll":26,"en":"Enchanter's Loupe","ende":"You can use this loupe to see through illusions and enchantments.","ru":"Лупа Зачарователя","rud":"Через эту лупу вы видите иллюзии и чары насквозь.","img":"hi26.webp"},{"id":"hi27","src":"hnf","kind":"item","roll":27,"en":"Escher's Mirrorball","ende":"Once per long rest, you can command this fist-sized silver orb to capture an omnidirectional image of its surroundings on its surface. This image lasts until your next long rest.","ru":"Зеркальный Шар Эсхера","rud":"Один раз до следующего продолжительного отдыха вы можете приказать этому серебряному шару размером с кулак запечатлеть на своей поверхности круговое изображение окружения. Оно сохраняется до следующего продолжительного отдыха.","img":"hi27.webp"},{"id":"hi28","src":"hnf","kind":"item","roll":28,"en":"Cheater's Coin","ende":"When you flip this coin, you can spend a Hope to determine which side it lands on.","ru":"Монета Шулера","rud":"Подбрасывая эту монету, вы можете потратить Надежду и выбрать, какой стороной она упадёт.","img":"hi28.webp"},{"id":"hi29","src":"hnf","kind":"item","roll":29,"en":"Gravewarden's Bell","ende":"This bell rings when a ghost or undead creature moves within Far range of it.","ru":"Колокол Хранителя Могил","rud":"Этот колокол звонит, когда призрак или нежить оказывается от него в пределах Далекой дистанции.","img":"hi29.webp"},{"id":"hi30","src":"hnf","kind":"item","roll":30,"en":"Reliquary of the Sightless Saint","ende":"You gain a +1 bonus to your Hope Die when you make the Risk It All death move.","ru":"Реликварий Незрячего Святого","rud":"Вы получаете +1 к Кости Надежды, когда совершаете Предсмертный Ход «Рискнуть всем».","img":"hi30.webp"},{"id":"hi31","src":"hnf","kind":"item","roll":31,"en":"Map of Revelation","ende":"You can attune this map to one creature at a time. The map always shows the attuned creature's location.","ru":"Карта Откровения","rud":"Вы можете настроить эту карту на одно существо за раз и всегда видеть, где оно находится.","img":"hi31.webp"},{"id":"hi32","src":"hnf","kind":"item","roll":32,"en":"Dagginae's Obsidian Slate","ende":"This wafer-thin sheet of volcanic glass is used by archivists to keep notes. Any information etched onto its surface disappears but can be recalled via a command you set.","ru":"Обсидиановая Табличка Даггинэ","rud":"Этот тончайший лист вулканического стекла архивисты используют для заметок. Всё, что нацарапано на его поверхности, исчезает, но возвращается по слову, которое вы задали.","img":"hi32.webp"},{"id":"hi33","src":"hnf","kind":"item","roll":33,"en":"Gadiman's Backpack","ende":"Once per rest, you can spend a Hope to conjure a mundane item up to a cubic foot in size inside this satchel.","ru":"Рюкзак Гэдимана","rud":"Один раз до следующего отдыха вы можете потратить Надежду, чтобы создать внутри этой сумки обыденный предмет объёмом до 30 литров.","img":"hi33.webp"},{"id":"hi34","src":"hnf","kind":"item","roll":34,"en":"Eclipse Coin","ende":"Once per rest, flip a coin. On heads, you gain a +1 bonus to attack rolls until your next successful attack. On tails, you gain +1 to your Evasion until an attack fails against you.","ru":"Монета Затмения","rud":"Один раз до следующего отдыха подбросьте монету. При орле вы получаете +1 к броскам атаки до вашей следующей успешной атаки. При решке вы получаете +1 к Уклонению, пока атака против вас не окажется неудачной.","img":"hi34.webp"},{"id":"hi35","src":"hnf","kind":"item","roll":35,"en":"Sorcerer's Hat","ende":"This conical blue hat is covered in silver stars. Once per rest, you can cast a spell from your vault with a Recall Cost equal to or less than your tier. This doesn't work for permanently vaulted cards.","ru":"Шляпа Чародея","rud":"Эта синяя конусообразная шляпа усыпана серебряными звёздами. Один раз до следующего отдыха вы можете сотворить заклинание из Хранилища со Стоимостью Призыва не выше вашего Ранга. С картами, убранными туда навсегда, это не работает.","img":"hi35.webp"},{"id":"hi36","src":"hnf","kind":"item","roll":36,"en":"Ghoulskin Gloves","ende":"When you attack with a physical weapon while wearing these gloves, the damage is considered both physical and magic.","ru":"Перчатки из Кожи Гуля","rud":"Пока вы носите эти перчатки, ваш урон от физического оружия считается одновременно физическим и магическим.","img":"hi36.webp"},{"id":"hi37","src":"hnf","kind":"item","roll":37,"en":"Gloves of Alacrity","ende":"When you would mark a Stress to reload a weapon, you don't mark it.","ru":"Перчатки Расторопности","rud":"Когда вы должны отметить Стресс, чтобы перезарядить оружие, вы его не отмечаете.","img":"hi37.webp"},{"id":"hi38","src":"hnf","kind":"item","roll":38,"en":"Insomniac's Periapt","ende":"When you take a rest without clearing Hit Points or Stress, you gain a +2 bonus to attack and damage rolls until your next rest.","ru":"Амулет Бессонного","rud":"Если вы отдыхаете, не очищая ни Раны, ни Стресс, вы получаете +2 к броскам атаки и урона до следующего отдыха.","img":"hi38.webp"},{"id":"hi39","src":"hnf","kind":"item","roll":39,"en":"Wildrider's Saddle","ende":"This saddle grants any animal it's strapped onto the ability to understand their rider's commands.","ru":"Седло Дикого Наездника","rud":"Любое животное, на которое надето это седло, начинает понимать команды всадника.","img":"hi39.webp"},{"id":"hi40","src":"hnf","kind":"item","roll":40,"en":"Soul-Twin Circlets","ende":"Two creatures can wear this pair of circlets. You can spend a Hope to switch places with whoever is wearing the other circlet.","ru":"Венцы Душ-Близнецов","rud":"Эту пару венцов могут носить два существа. Вы можете потратить Надежду, чтобы поменяться местами с тем, у кого второй венец.","img":"hi40.webp"},{"id":"hi41","src":"hnf","kind":"item","roll":41,"en":"Namer's Oracle","ende":"Once per session, you can roll this set of runic dice to reveal the full name of the last person you touched.","ru":"Оракул Именующего","rud":"Один раз за сессию вы можете бросить этот набор рунических костей, чтобы узнать полное имя последнего человека, которого коснулись.","img":"hi41.webp"},{"id":"hi42","src":"hnf","kind":"item","roll":42,"en":"Crucible Frames","ende":"These eyeglasses reveal weak points in objects and creatures. Three times per rest, you can spend a Hope to gain advantage on an attack roll.","ru":"Оправа Горнила","rud":"Эти очки показывают слабые места предметов и существ. Три раза до следующего отдыха вы можете потратить Надежду, чтобы получить преимущество на бросок атаки.","img":"hi42.webp"},{"id":"hi43","src":"hnf","kind":"item","roll":43,"en":"Two-Faced Aegis Brooch","ende":"Once per rest, flip a coin. On heads, you become immune to the next physical damage you take. On tails, you become immune to the next magic damage you take.","ru":"Брошь Двуликой Эгиды","rud":"Один раз до следующего отдыха подбросьте монету. При орле вы получаете иммунитет к следующему физическому урону. При решке вы получаете иммунитет к следующему магическому урону.","img":"hi43.webp"},{"id":"hi44","src":"hnf","kind":"item","roll":44,"en":"Knockback Bracelets","ende":"On a successful weapon attack, you can knock your target back up to Close range from their location.","ru":"Браслеты Отбрасывания","rud":"При успешной атаке оружием вы можете отбросить цель на расстояние до Средней дистанции.","img":"hi44.webp"},{"id":"hi45","src":"hnf","kind":"item","roll":45,"en":"Force Disc","ende":"This shimmering two-dimensional disc of magical force has a 4-foot diameter and is magically tethered to a pebble. The disc always floats 3 feet north of, and at the same elevation as, the pebble. The pebble has a mass equal to one-hundredth of the total mass carried by the disc.","ru":"Силовой Диск","rud":"Этот мерцающий плоский диск магической силы диаметром в метр привязан к камешку. Диск всегда парит в метре к северу от камешка и на той же высоте. Камешек весит в сто раз меньше того, что лежит на диске.","img":"hi45.webp"},{"id":"hi46","src":"hnf","kind":"item","roll":46,"en":"Molepaw Mittens","ende":"Spend a Hope to swim through earth as if it were water for the next 10 minutes.","ru":"Кротовьи Рукавицы","rud":"Потратьте Надежду, чтобы следующие 10 минут плыть сквозь землю, как сквозь воду.","img":"hi46.webp"},{"id":"hi47","src":"hnf","kind":"item","roll":47,"en":"Timekeeper's Pendant","ende":"You can choose an additional downtime move each rest.","ru":"Кулон Хранителя Времени","rud":"На каждом отдыхе вы можете выбрать дополнительный Ход Отдыха.","img":"hi47.webp"},{"id":"hi48","src":"hnf","kind":"item","roll":48,"en":"Iron Dagger Pendant","ende":"Once per long rest, you can spend a Hope to tell the pendant a creature's name. The pendant gently pulls you toward that creature's current location until your next long rest.","ru":"Кулон Железного Кинжала","rud":"Один раз до следующего продолжительного отдыха вы можете потратить Надежду и назвать этому кулону имя существа. Кулон мягко тянет вас к этому существу, где бы оно ни было, до вашего следующего продолжительного отдыха.","img":"hi48.webp"},{"id":"hi49","src":"hnf","kind":"item","roll":49,"en":"Collar of Ascendancy","ende":"An animal who wears this collar gains the ability to speak and understand common speech.","ru":"Ошейник Возвышения","rud":"Животное в этом ошейнике получает способность говорить и понимать общую речь.","img":"hi49.webp"},{"id":"hi50","src":"hnf","kind":"item","roll":50,"en":"Temporal Sanctuary","ende":"A PC who takes a rest in the temporal sanctuary can choose an additional downtime move.","ru":"Убежище Вне Времени","rud":"Если персонаж игрока отдыхает в этом убежище, он может выбрать дополнительный Ход Отдыха.","img":"hi50.webp"},{"id":"hi51","src":"hnf","kind":"item","roll":51,"en":"Hero's Helm","ende":"When you critically succeed on an attack, all allies within Close range gain a Hope.","ru":"Шлем Героя","rud":"Когда вы выбрасываете критический успех на атаку, все союзники в пределах Средней дистанции получают Надежду.","img":"hi51.webp"},{"id":"hi52","src":"hnf","kind":"item","roll":52,"en":"Rings of Friendship","ende":"Two creatures can wear this pair of rings shaped like coiled snakes. You can spend the Hope of whoever is wearing the other ring (with their permission) as if it were your own.","ru":"Кольца Дружбы","rud":"Эту пару колец в форме свернувшихся змей могут носить два существа. Вы можете тратить Надежду того, у кого второе кольцо (с его разрешения), как свою.","img":"hi52.webp"},{"id":"hi53","src":"hnf","kind":"item","roll":53,"en":"Rings of Camaraderie","ende":"Two creatures can wear this pair of wooden rings. You can mark the Stress of whoever is wearing the other ring (with their permission) as if it were your own.","ru":"Кольца Товарищества","rud":"Эту пару деревянных колец могут носить два существа. Вы можете отмечать Стресс того, у кого второе кольцо (с его разрешения), как свой.","img":"hi53.webp"},{"id":"hi54","src":"hnf","kind":"item","roll":54,"en":"Rings of Alliance","ende":"Two creatures can wear this pair of rose gold rings. Once per session, you can initiate a Tag Team Roll with whoever is wearing the other ring without spending Hope or counting against your session limit for Tag Team Rolls.","ru":"Кольца Союза","rud":"Эту пару колец из розового золота могут носить два существа. Один раз за сессию вы можете инициировать Командный Бросок с тем, у кого второе кольцо, не тратя Надежду и не расходуя свой обычный Командный Бросок.","img":"hi54.webp"},{"id":"hi55","src":"hnf","kind":"item","roll":55,"en":"Phobophage's Circlet","ende":"When the GM spends a Fear, roll a d4. Once per scene on a result of 4, you clear a Stress.","ru":"Венец Пожирателя Страха","rud":"Когда Мастер тратит Страх, бросьте d4. Один раз за сцену, если выпадет 4, вы очищаете Стресс.","img":"hi55.webp"},{"id":"hi56","src":"hnf","kind":"item","roll":56,"en":"Quillshawl","ende":"If an adversary attacks you within Melee range, they must succeed on a Reaction Roll (12) or mark a Hit Point.","ru":"Иглошаль","rud":"Если противник атакует вас Вплотную, он должен преуспеть в Броске Реакции (12) или отметить Рану.","img":"hi56.webp"},{"id":"hi57","src":"hnf","kind":"item","roll":57,"en":"Warp Pendant","ende":"Once per rest, mark a Stress to teleport to a location you can clearly see.","ru":"Кулон Искривления","rud":"Один раз до следующего отдыха отметьте Стресс, чтобы телепортироваться в место, которое вы отчётливо видите.","img":"hi57.webp"},{"id":"hi58","src":"hnf","kind":"item","roll":58,"en":"Portal Frames","ende":"This pair of small ornate frames, one red and one blue, are connected. Anything that passes into one exits from the other.","ru":"Рамы-Порталы","rud":"Эти две небольшие богато украшенные рамы, красная и синяя, связаны между собой. Всё, что входит в одну, выходит из другой.","img":"hi58.webp"},{"id":"hi59","src":"hnf","kind":"item","roll":59,"en":"Communion Relic","ende":"Once per rest, you can spend a Hope to use an ally's Experience as if it were your own. You can carry only one relic.","ru":"Реликвия Единения","rud":"Один раз до следующего отдыха вы можете потратить Надежду, чтобы использовать Опыт союзника как свой. Вы можете носить только одну реликвию.","img":"hi59.webp"},{"id":"hi60","src":"hnf","kind":"item","roll":60,"en":"Augur's Relic","ende":"Once per long rest, you can activate your Hope feature without spending Hope. You can carry only one relic.","ru":"Реликвия Авгура","rud":"Один раз до следующего продолжительного отдыха вы можете активировать своё Свойство Надежды, не тратя Надежду. Вы можете носить только одну реликвию.","img":"hi60.webp"}],"hnf_consumable":[{"id":"hc1","src":"hnf","kind":"consumable","roll":1,"en":"Warding Candle","ende":"You can light this candle to fill an area within Close range with a halo of light. A creature outside the halo can't enter it if they have ill intent toward a creature within it. The candle burns for an hour.","ru":"Оберегающая Свеча","rud":"Зажгите эту свечу, и в пределах Средней дистанции разольётся ореол света. Существо снаружи ореола не может войти в него, если замышляет недоброе против того, кто внутри. Свеча горит час.","img":"hc1.webp"},{"id":"hc2","src":"hnf","kind":"consumable","roll":2,"en":"Iridian Dust","ende":"This multicolored powder sticks to everything and prevents creatures covered in it from becoming Hidden.","ru":"Радужная Пыль","rud":"Этот разноцветный порошок липнет ко всему, и существа, покрытые им, не могут становиться Скрытыми.","img":"hc2.webp"},{"id":"hc3","src":"hnf","kind":"consumable","roll":3,"en":"Verglasian Seed","ende":"You can use this ice shard to instantly freeze an area of water up to Close range.","ru":"Семя Вергласа","rud":"Этим осколком льда можно мгновенно заморозить участок воды в пределах Средней дистанции.","img":"hc3.webp"},{"id":"hc4","src":"hnf","kind":"consumable","roll":4,"en":"Cupbearer's Bezoar","ende":"You can swallow this bezoar to become immune to poisons until your next long rest.","ru":"Безоар Виночерпия","rud":"Проглотив этот безоар, вы получаете иммунитет к ядам до следующего продолжительного отдыха.","img":"hc4.webp"},{"id":"hc5","src":"hnf","kind":"consumable","roll":5,"en":"Mossmantle Potion","ende":"You can drink this tea to perfectly blend into natural environments until your next rest.","ru":"Зелье Мохового Покрова","rud":"Выпейте этот чай, чтобы до следующего отдыха идеально сливаться с природным окружением.","img":"hc5.webp"},{"id":"hc6","src":"hnf","kind":"consumable","roll":6,"en":"Lyrebird Lozenge","ende":"You can dissolve this lozenge in your mouth to perfectly mimic any voice you've heard until the end of the scene.","ru":"Пастилка Лирохвоста","rud":"Рассосите эту пастилку, чтобы до конца сцены безупречно подражать любому услышанному голосу.","img":"hc6.webp"},{"id":"hc7","src":"hnf","kind":"consumable","roll":7,"en":"Vial of Featherfall","ende":"You can drink this potion to ignore damage from falling for the next 10 minutes.","ru":"Флакон Мягкого Падения","rud":"Выпейте это зелье, чтобы следующие 10 минут не получать урон от падения.","img":"hc7.webp"},{"id":"hc8","src":"hnf","kind":"consumable","roll":8,"en":"Chimeric Saliva","ende":"You can apply this saliva to a weapon that deals physical damage to change its damage type to magic until your next rest.","ru":"Слюна Химеры","rud":"Смажьте этой слюной физическое оружие, и до следующего отдыха его урон станет магическим.","img":"hc8.webp"},{"id":"hc9","src":"hnf","kind":"consumable","roll":9,"en":"Packet of Space Dust","ende":"This dust causes anything it covers to become lighter than air. One packet contains enough dust to cover the contents of a picnic basket, and the effects last for an hour.","ru":"Пакетик Космической Пыли","rud":"Всё, что покрыто этой пылью, становится легче воздуха. Одного пакетика хватает на содержимое корзины для пикника, а эффект длится час.","img":"hc9.webp"},{"id":"hc10","src":"hnf","kind":"consumable","roll":10,"en":"Pipeweed","ende":"When you choose the Clear Stress downtime move during a short rest, you can smoke this non-intoxicating leaf to clear an additional Stress. Any other PCs who chose the Clear Stress downtime move also gain this benefit.","ru":"Трубочное Зелье","rud":"Когда во время короткого отдыха вы выбираете Ход Отдыха «Снять Стресс», вы можете выкурить этот неопьяняющий лист. Все, кто выбрал этот ход, включая вас, очищают дополнительный Стресс.","img":"hc10.webp"},{"id":"hc11","src":"hnf","kind":"consumable","roll":11,"en":"Deathseer's Powder","ende":"You can sprinkle this powder over a recently deceased corpse to conjure a spectral reprise of their final minute of life.","ru":"Порошок Провидца Смерти","rud":"Посыпьте этим порошком тело недавно умершего, и последняя минута его жизни разыграется перед вами призрачным видением.","img":"hc11.webp"},{"id":"hc12","src":"hnf","kind":"consumable","roll":12,"en":"Slayer's Salt","ende":"You can spread this salt in a line along windowsills or thresholds to create a magical barrier that undead creatures can't cross until the line is broken.","ru":"Соль Истребителя","rud":"Насыпьте эту соль линией по подоконникам или порогам, чтобы создать магический барьер, который нежить не может пересечь, пока линия цела.","img":"hc12.webp"},{"id":"hc13","src":"hnf","kind":"consumable","roll":13,"en":"Yakamel Milk","ende":"After consuming this milk, the next time you clear 1 or more Hit Points, you clear an additional Hit Point.","ru":"Молоко Якамеля","rud":"Выпейте это молоко. В следующий раз, когда вы очищаете одну Рану или больше, очистите дополнительную Рану.","img":"hc13.webp"},{"id":"hc14","src":"hnf","kind":"consumable","roll":14,"en":"Glowmoss Mushroom","ende":"You can break this mushroom into pieces, causing it to glow bright blue until your next long rest.","ru":"Гриб Светящегося Мха","rud":"Разломите этот гриб, и он будет ярко светиться синим до следующего продолжительного отдыха.","img":"hc14.webp"},{"id":"hc15","src":"hnf","kind":"consumable","roll":15,"en":"Red Ooze Oil","ende":"You can coat your weapon in this oil. The next successful attack you make with this weapon deals an extra 1d8 magic damage and temporarily Ignites the target. While Ignited, the target takes 1d4 magic damage when they take the spotlight.","ru":"Масло Алой Слизи","rud":"Смажьте этим маслом оружие. При следующей успешной атаке этим оружием вы наносите дополнительно 1d8 магического урона и временно Поджигаете цель. Пока цель Подожжена, она получает 1d4 магического урона, когда её активируют.","img":"hc15.webp"},{"id":"hc16","src":"hnf","kind":"consumable","roll":16,"en":"Instant Camp","ende":"You can unfold this small mechanical box into a camping tent large enough to safely house six people. The tent collapses at the end of your next long rest.","ru":"Мгновенный Лагерь","rud":"Эта небольшая механическая коробка раскладывается в палатку, где безопасно помещаются шесть человек. В конце вашего следующего продолжительного отдыха палатка оседает.","img":"hc16.webp"},{"id":"hc17","src":"hnf","kind":"consumable","roll":17,"en":"Bundle of Spiderlegs","ende":"You can eat these spiderlegs to walk on walls until your next rest.","ru":"Связка Паучьих Лапок","rud":"Съешьте эти лапки, чтобы до следующего отдыха ходить по стенам.","img":"hc17.webp"},{"id":"hc18","src":"hnf","kind":"consumable","roll":18,"en":"Ciscan Fog Bottle","ende":"You can break this jar to fill the area within Close range with magical mist. A creature who enters the mist clears a Stress and becomes Hidden.","ru":"Бутыль Цисканского Тумана","rud":"Разбейте этот сосуд, чтобы заполнить область в пределах Средней дистанции магическим туманом. Существо, вошедшее в туман, очищает Стресс и становится Скрытым.","img":"hc18.webp"},{"id":"hc19","src":"hnf","kind":"consumable","roll":19,"en":"Snapthorn Seed","ende":"You can throw this seed at a point you can see. It explodes into a tangle of binding vines that temporarily Restrains all creatures within Close range of that point.","ru":"Семя Хваткого Терна","rud":"Бросьте это семя в точку, которую вы видите. Оно взрывается клубком опутывающих лоз, которые временно Обездвиживают всех существ в пределах Средней дистанции от этой точки.","img":"hc19.webp"},{"id":"hc20","src":"hnf","kind":"consumable","roll":20,"en":"Sprite Bottle","ende":"When you mark your last Hit Point, this bottle shatters to release the Sprite inside. The Sprite clears all your Hit Points before fading from the Mortal Realm.","ru":"Бутыль с Духом","rud":"Когда вы отмечаете последнюю Рану, эта бутыль разбивается и выпускает запертого внутри духа. Дух очищает все ваши Раны, после чего исчезает из Царства смертных.","img":"hc20.webp"},{"id":"hc21","src":"hnf","kind":"consumable","roll":21,"en":"Gravity Bomb","ende":"You can throw this peach-sized mechanical orb at a point within Far range. It implodes and pulls all creatures and objects within Close range of that point into Melee range with it.","ru":"Гравитационная Бомба","rud":"Бросьте этот механический шар размером с персик в точку в пределах Далекой дистанции. Он схлопывается и притягивает Вплотную к себе всех существ и все предметы в пределах Средней дистанции от этой точки.","img":"hc21.webp"},{"id":"hc22","src":"hnf","kind":"consumable","roll":22,"en":"Gossip Flower","ende":"You can plant this seed in soil. It instantly grows into a small flower that records everything it hears for up to one week. When plucked, the flower recites what it recorded in real time, then withers.","ru":"Цветок Сплетен","rud":"Посадите это семя в землю. Оно мгновенно вырастает в цветок, который до недели запоминает всё, что слышит. Сорванный цветок пересказывает услышанное слово в слово, после чего вянет.","img":"hc22.webp"},{"id":"hc23","src":"hnf","kind":"consumable","roll":23,"en":"Displacement Token","ende":"You can swallow this token to conjure two illusions of yourself that you can control. Each illusion lasts until it takes damage or until your next rest.","ru":"Жетон Подмены","rud":"Проглотите этот жетон, чтобы создать двух своих иллюзорных двойников, которыми вы можете управлять. Каждый двойник существует, пока не получит урон или до следующего отдыха.","img":"hc23.webp"},{"id":"hc24","src":"hnf","kind":"consumable","roll":24,"en":"Night Hag's Dust","ende":"You can blow this dust in an adversary's face to prevent them from clearing Stress until your next long rest.","ru":"Пыль Ночной Карги","rud":"Сдуйте эту пыль в лицо противнику, чтобы он не мог очистить Стресс до вашего следующего продолжительного отдыха.","img":"hc24.webp"},{"id":"hc25","src":"hnf","kind":"consumable","roll":25,"en":"Self-Sewing Thread","ende":"You can use this thread to clear either a Hit Point or 2 Armor Slots.","ru":"Самошьющая Нить","rud":"Этой нитью можно очистить либо Рану, либо 2 Ячейки Брони.","img":"hc25.webp"},{"id":"hc26","src":"hnf","kind":"consumable","roll":26,"en":"Stonemason's Fortune","ende":"When you throw this gray brick on the ground, it immediately grows into a 6-foot-tall, 10-foot-wide, and 2-foot-deep wall of solid stone.","ru":"Удача Каменщика","rud":"Бросьте этот серый кирпич на землю, и он мгновенно вырастет в стену из цельного камня высотой два метра, шириной три метра и толщиной полметра.","img":"hc26.webp"},{"id":"hc27","src":"hnf","kind":"consumable","roll":27,"en":"Mnemonic Potion","ende":"You can drink this potion to Utilize an Experience without spending a Hope.","ru":"Мнемоническое Зелье","rud":"Выпейте это зелье, чтобы использовать Опыт, не тратя Надежду.","img":"hc27.webp"},{"id":"hc28","src":"hnf","kind":"consumable","roll":28,"en":"Salamander Salve","ende":"You can apply this salve to your skin to make yourself immune to heat until your next rest.","ru":"Мазь Саламандры","rud":"Нанесите эту мазь на кожу, чтобы до следующего отдыха получить иммунитет к жару.","img":"hc28.webp"},{"id":"hc29","src":"hnf","kind":"consumable","roll":29,"en":"Green Ooze Oil","ende":"You can coat your weapon in this oil. The next successful attack you make with this weapon deals an extra 1d8 magic damage and temporarily Corrodes the target. While Corroded, the target gains a -2 penalty to their damage thresholds.","ru":"Масло Зелёной Слизи","rud":"Смажьте этим маслом оружие. При следующей успешной атаке этим оружием вы наносите дополнительно 1d8 магического урона и временно Разъедаете цель. Пока цель Разъедена, она получает штраф -2 к порогам урона.","img":"hc29.webp"},{"id":"hc30","src":"hnf","kind":"consumable","roll":30,"en":"Sunlight Orb","ende":"You can shatter this orb to make the area within Very Far range appear as though it's sunlit daytime for the next 24 hours.","ru":"Сфера Солнечного Света","rud":"Разбейте эту сферу, и целые сутки область в пределах Очень Далекой дистанции будет выглядеть так, будто стоит солнечный день.","img":"hc30.webp"},{"id":"hc31","src":"hnf","kind":"consumable","roll":31,"en":"Moonlight Orb","ende":"You can shatter this orb to make the area within Very Far range appear as though it's moonlit nighttime for the next 24 hours.","ru":"Сфера Лунного Света","rud":"Разбейте эту сферу, и целые сутки область в пределах Очень Далекой дистанции будет выглядеть так, будто стоит лунная ночь.","img":"hc31.webp"},{"id":"hc32","src":"hnf","kind":"consumable","roll":32,"en":"Midas Flask","ende":"You can pour this small flask of alchemical liquid over a mundane item to instantly transmute it into a handful of gold.","ru":"Фляга Мидаса","rud":"Вылейте на обыденный предмет алхимическую жидкость из этой небольшой фляги, и он мгновенно превратится в горсть золота.","img":"hc32.webp"},{"id":"hc33","src":"hnf","kind":"consumable","roll":33,"en":"Staff of Reversal","ende":"You can break this staff against the ground to reverse one magical transformation or effect within Far range.","ru":"Посох Обращения","rud":"Сломайте этот посох о землю, чтобы обратить одно магическое превращение или эффект в пределах Далекой дистанции.","img":"hc33.webp"},{"id":"hc34","src":"hnf","kind":"consumable","roll":34,"en":"Berserker's Brew","ende":"When you drink this dram of liquid, you gain a bonus to your Strength and a penalty to your Finesse and Knowledge equal to your Instinct (minimum 1). This effect lasts until you make a death move or until your next rest.","ru":"Варево Берсерка","rud":"Выпив это варево, вы получаете бонус к Силе и штраф к Искусности и Знанию, равные вашему Инстинкту (минимум 1). Эффект длится до следующего отдыха или пока вы не совершите Предсмертный Ход.","img":"hc34.webp"},{"id":"hc35","src":"hnf","kind":"consumable","roll":35,"en":"Emberite Shard","ende":"Choose a point within Far range. All targets within Close range of that point must succeed on a Reaction Roll (16) or take 3d6 magic damage and become temporarily Ablaze. While Ablaze, a creature must roll a d4 whenever they make an action roll. On a result of 1, they mark a Hit Point. On a result of 4, they clear the Ablaze condition.","ru":"Осколок Эмберита","rud":"Выберите точку в пределах Далекой дистанции. Все цели в пределах Средней дистанции от неё должны преуспеть в Броске Реакции (16) или получить 3d6 магического урона и временно оказаться Объятыми пламенем. Пока существо Объято пламенем, оно бросает d4 при каждом броске действия. При результате 1 оно отмечает Рану, при результате 4 снимает это состояние.","img":"hc35.webp"},{"id":"hc36","src":"hnf","kind":"consumable","roll":36,"en":"Arcticite Shard","ende":"Choose a point within Far range. All targets within Close range of that point must succeed on a Reaction Roll (16) or take 3d6 magic damage and become temporarily Restrained by ice.","ru":"Осколок Арктицита","rud":"Выберите точку в пределах Далекой дистанции. Все цели в пределах Средней дистанции от неё должны преуспеть в Броске Реакции (16) или получить 3d6 магического урона и временно стать Обездвиженными льдом.","img":"hc36.webp"},{"id":"hc37","src":"hnf","kind":"consumable","roll":37,"en":"Fulgurite Shard","ende":"Choose a point within Far range. All targets within Close range of that point must succeed on a Reaction Roll (16) or take 3d6 magic damage and mark 1d4 Stress as lightning crackles through the area.","ru":"Осколок Фульгурита","rud":"Выберите точку в пределах Далекой дистанции. Все цели в пределах Средней дистанции от неё должны преуспеть в Броске Реакции (16) или получить 3d6 магического урона и отметить 1d4 Стресса, пока область прошивают молнии.","img":"hc37.webp"},{"id":"hc38","src":"hnf","kind":"consumable","roll":38,"en":"Demiurge's Draught","ende":"You can drink this draught to gain a +1 bonus to your Proficiency for your next successful attack roll.","ru":"Настой Демиурга","rud":"Выпейте этот настой, чтобы получить +1 к Мастерству для следующего успешного броска атаки.","img":"hc38.webp"},{"id":"hc39","src":"hnf","kind":"consumable","roll":39,"en":"Cockerel Claw Tea","ende":"You can drink this tea to refresh your features as if you had taken a long rest.","ru":"Чай из Петушиного Когтя","rud":"Выпейте этот чай, чтобы обновить свои свойства так, будто вы совершили продолжительный отдых.","img":"hc39.webp"},{"id":"hc40","src":"hnf","kind":"consumable","roll":40,"en":"Potion of Vigilance","ende":"You can drink this potion to gain a +1 bonus to your Evasion until you mark a Hit Point.","ru":"Зелье Бдительности","rud":"Выпейте это зелье, чтобы получить +1 к Уклонению, пока не отметите Рану.","img":"hc40.webp"},{"id":"hc41","src":"hnf","kind":"consumable","roll":41,"en":"Cacophonous Concoction","ende":"When you drink this potion, anything you say or do in the next hour becomes impossible for a witness to recount. Any attempts they make to communicate what they saw, heard, or otherwise sensed comes out garbled or nonsensical.","ru":"Какофоническая Микстура","rud":"Выпейте это зелье, и на час всё, что вы скажете или сделаете, станет невозможно пересказать. Любые попытки свидетелей передать увиденное, услышанное или иначе воспринятое выходят искажёнными или бессмысленными.","img":"hc41.webp"},{"id":"hc42","src":"hnf","kind":"consumable","roll":42,"en":"Nightmare Mead","ende":"You can drink this potion to discover the deepest fear of the next person you make eye contact with. When you do, the GM gains a Fear.","ru":"Медовуха Кошмаров","rud":"Выпейте это зелье, чтобы узнать глубочайший страх следующего человека, с которым встретитесь взглядом. Когда вы это делаете, Мастер получает Страх.","img":"hc42.webp"},{"id":"hc43","src":"hnf","kind":"consumable","roll":43,"en":"Stake of Abjuration","ende":"You can hammer this stake into the ground and make a proclamation. Until your next rest, a creature within Far range of the stake who transgresses that proclamation must mark a Stress. The stake lasts until your next rest, then it shatters.","ru":"Кол Запрета","rud":"Вбейте этот кол в землю и объявите запрет. До следующего отдыха каждое существо в пределах Далекой дистанции от кола, нарушившее запрет, должно отметить Стресс. Затем кол рассыпается.","img":"hc43.webp"},{"id":"hc44","src":"hnf","kind":"consumable","roll":44,"en":"Psychopomp's Shroud","ende":"You can place this shroud over the corpse of a recently deceased creature. The creature's spirit enters the shroud and becomes your spectral assistant until the next sunrise, when they pass through the veil of death and take the shroud with them.","ru":"Саван Проводника Душ","rud":"Накройте этим саваном тело недавно умершего существа. Дух умершего входит в саван и служит вам призрачным помощником до следующего рассвета. На рассвете он уходит за завесу смерти и забирает саван с собой.","img":"hc44.webp"},{"id":"hc45","src":"hnf","kind":"consumable","roll":45,"en":"Phial of Deep Ink","ende":"You can drink this bottle of ink to transform into a cephalopod of roughly your size for the next hour. You gain rubbery skin, soft bones, the ability to breathe underwater, and new limbs until you have eight total.","ru":"Пузырёк Глубинных Чернил","rud":"Выпейте чернила из этого пузырька, чтобы на час превратиться в головоногого моллюска примерно вашего размера. Вы получаете упругую кожу, мягкие кости и способность дышать под водой, а конечностей у вас становится восемь.","img":"hc45.webp"},{"id":"hc46","src":"hnf","kind":"consumable","roll":46,"en":"Mesmer's Tonic","ende":"When you drink this tonic, the only thing you can hear until your next rest are the surface thoughts of creatures within Very Close range.","ru":"Тоник Месмера","rud":"Выпейте этот тоник, и до следующего отдыха вы не будете слышать ничего, кроме поверхностных мыслей существ в пределах Близкой дистанции.","img":"hc46.webp"},{"id":"hc47","src":"hnf","kind":"consumable","roll":47,"en":"Invisibility Potion","ende":"You are Hidden until you deal damage to another creature or until your next rest.","ru":"Зелье Невидимости","rud":"Вы Скрыты, пока не нанесёте урон другому существу или до следующего отдыха.","img":"hc47.webp"},{"id":"hc48","src":"hnf","kind":"consumable","roll":48,"en":"Formoid Serum","ende":"You can drink this potion to become a swarm of 16 million ants until the end of the scene. You keep and have access to all equipment, loot, and features.","ru":"Формоидная Сыворотка","rud":"Выпейте это зелье, чтобы до конца сцены стать роем из 16 миллионов муравьёв. Вы сохраняете доступ ко всему снаряжению, добыче и свойствам.","img":"hc48.webp"},{"id":"hc49","src":"hnf","kind":"consumable","roll":49,"en":"Steelskin Salve","ende":"You can apply this salve to your skin to gain a bonus to your damage thresholds equal to your tier until the end of the scene.","ru":"Мазь Стальной Кожи","rud":"Нанесите эту мазь на кожу, чтобы до конца сцены получить бонус к порогам урона, равный вашему Рангу.","img":"hc49.webp"},{"id":"hc50","src":"hnf","kind":"consumable","roll":50,"en":"Godling's Pomelo","ende":"You can eat this citrus fruit to clear all Hit Points and Stress.","ru":"Помело Божка","rud":"Съешьте этот плод, чтобы очистить все Раны и Стресс.","img":"hc50.webp"},{"id":"hc51","src":"hnf","kind":"consumable","roll":51,"en":"Snakeskin Spirit","ende":"You can drink this potion to slough off your outer layer of skin and heal a scar.","ru":"Настойка Змеиной Кожи","rud":"Выпейте это зелье, чтобы сбросить внешний слой кожи и залечить шрам.","img":"hc51.webp"},{"id":"hc52","src":"hnf","kind":"consumable","roll":52,"en":"Magic-User's Malison","ende":"When you release this spellcaster's trapped soul, you can cast one spell from a card in your vault as if it were in your loadout. This doesn't work for permanently vaulted cards.","ru":"Проклятие Заклинателя","rud":"Освободив заточённую душу заклинателя, вы можете сотворить одно заклинание с карты из Хранилища, будто она у вас в Руке. С картами, убранными туда навсегда, это не работает.","img":"hc52.webp"},{"id":"hc53","src":"hnf","kind":"consumable","roll":53,"en":"Quintessential Severant","ende":"You can use this magic blade to cut one magical or metaphysical bond, such as an enchantment, contract, magical tether, or divine oath. When you do, the blade shatters.","ru":"Квинтэссенциальный Разделитель","rud":"Этим магическим клинком можно разрубить одну магическую или метафизическую связь: чары, договор, привязку или божественную клятву. После этого клинок рассыпается.","img":"hc53.webp"},{"id":"hc54","src":"hnf","kind":"consumable","roll":54,"en":"Mask of the Echoed Self","ende":"You can wear this mask during your next level up to swap the values of any of your traits. When you do, the mask becomes your permanent face.","ru":"Маска Отражённого «Я»","rud":"Наденьте эту маску во время следующего повышения уровня, чтобы поменять местами значения любых своих характеристик. После этого маска станет вашим постоянным лицом.","img":"hc54.webp"},{"id":"hc55","src":"hnf","kind":"consumable","roll":55,"en":"Necroprancer's Bell","ende":"You can break this rusted, clapperless bell against the ground to summon a skeletal steed that climbs out of the earth and serves you until the next sunrise.","ru":"Колокол Некроплясуна","rud":"Разбейте о землю этот ржавый колокол без языка, чтобы призвать костяного скакуна: он выберется из земли и будет служить вам до следующего рассвета.","img":"hc55.webp"},{"id":"hc56","src":"hnf","kind":"consumable","roll":56,"en":"Drakemantle","ende":"You can use this enchanted ancient dragon hide to gain draconic characteristics until the end of the scene, when the hide falls aways in tatters. Until then, you can fly and gain a +5 bonus to your damage thresholds and a +1 bonus to your Proficiency.","ru":"Драконья Мантия","rud":"Эта зачарованная шкура древнего дракона даёт вам драконьи черты до конца сцены, после чего спадает лохмотьями. До тех пор вы можете летать и получаете +5 к порогам урона и +1 к Мастерству.","img":"hc56.webp"},{"id":"hc57","src":"hnf","kind":"consumable","roll":57,"en":"Gambler's Fallacy","ende":"You can spend any number of handfuls of gold by placing them into this slotted ceramic jar shaped like a pig. When you throw the jar at a point within Far range, it explodes and deals 1d20 magic damage for each handful of gold spent to all creatures within Close range of that point. All gold within the jar is destroyed.","ru":"Ошибка Игрока","rud":"Опустите в эту керамическую копилку в форме свиньи любое количество горстей золота. Бросьте её в точку в пределах Далекой дистанции: копилка взрывается и наносит всем существам в пределах Средней дистанции по 1d20 магического урона за каждую опущенную горсть. Золото внутри уничтожается.","img":"hc57.webp"},{"id":"hc58","src":"hnf","kind":"consumable","roll":58,"en":"Lionheart Tonic","ende":"You can drink this tonic to gain a +1 bonus to your Proficiency until you roll with Fear.","ru":"Тоник Львиного Сердца","rud":"Выпейте этот тоник, чтобы получить +1 к Мастерству, пока не совершите бросок со Страхом.","img":"hc58.webp"},{"id":"hc59","src":"hnf","kind":"consumable","roll":59,"en":"Tears of the Undying Hero","ende":"When you drink this potion, death can't touch you until your next long rest. When you would mark your last Hit Point, instead of making a death move, you make one final action roll before falling into a dreamless slumber until an ally chooses the Tend to Wounds downtime move to clear your Hit Points.","ru":"Слёзы Бессмертного Героя","rud":"Выпив это зелье, вы недосягаемы для смерти до следующего продолжительного отдыха. Когда вы должны отметить последнюю Рану, вместо Предсмертного Хода вы совершаете один последний бросок действия и погружаетесь в сон без сновидений. Вы спите, пока союзник не выберет Ход Отдыха «Залечить рану», чтобы очистить ваши Раны.","img":"hc59.webp"},{"id":"hc60","src":"hnf","kind":"consumable","roll":60,"en":"Featherstep Potion","ende":"You can drink this potion to sprout small wings from your ankles that give you a bonus to your Evasion equal to your tier until your next rest.","ru":"Зелье Лёгкой Поступи","rud":"Выпейте это зелье, и у вас на лодыжках вырастут небольшие крылья. До следующего отдыха вы получаете бонус к Уклонению, равный вашему Рангу.","img":"hc60.webp"}],"wondrous":[{"id":"w1","src":"wondrous","kind":"consumable","roll":1,"en":"Abyssal Sap","ende":"You can throw a vial of this sap at a target within Far range to have the effect of the Vicious Entangle spell.","ru":"Смола Бездны","rud":"Вы можете бросить флакон этой смолы в цель в пределах Дальней дистанции, воспроизводя эффект заклинания «Коварное Опутывание».","img":"w1.webp"},{"id":"w2","src":"wondrous","kind":"consumable","roll":2,"en":"Aetherflower Tea","ende":"Until your next rest, you can detect the presence of magic as a faint aura around visible objects within Very Close range.","ru":"Чай Эфироцвета","rud":"До следующего отдыха вы можете обнаруживать присутствие магии как слабую ауру вокруг видимых объектов в пределах Ближней дистанции.","img":"w2.webp"},{"id":"w3","src":"wondrous","kind":"item","roll":3,"en":"Aetherflower","ende":"This flower is sensitive to magic, and will point in the direction of the strongest source of magic within Very Close range. It withers when you take your first rest after harvesting it. Craftinto: AetherflowerTea.","ru":"Эфироцвет","rud":"Этот цветок чувствителен к магии и указывает в направлении сильнейшего источника магии в пределах Ближней дистанции. Он вянет, когда вы берёте первый отдых после сбора. Переработать в: Чай Эфироцвета.","img":"w3.webp"},{"id":"w4","src":"wondrous","kind":"item","roll":4,"en":"Alconite Crystal","ende":"You can expend the energy in this crystal to gain a 1d4 bonus to a Spellcast Roll. You can recharge it as a downtime move by immersing it in salt water.","ru":"Алконитовый Кристалл","rud":"Вы можете использовать энергию этого кристалла, чтобы получить бонус 1d4 к броску заклинания. Вы можете зарядить его в качестве хода привала, погрузив в солёную воду.","img":"w4.webp"},{"id":"w5","src":"wondrous","kind":"item","roll":5,"en":"Anchoring Hook","ende":"When you make a reaction roll to avoid being moved against your will, you can deploy this anchor to gain advantage on the roll, and resistance to any damage you take from the movement.","ru":"Удерживающий Крюк","rud":"Когда вы совершаете бросок реакции, чтобы избежать перемещения против вашей воли, вы можете задействовать этот крюк, получив преимущество к броску и сопротивление к любому урону от перемещения.","img":"w5.webp"},{"id":"w6","src":"wondrous","kind":"item","roll":6,"en":"Ancient Runestone","ende":"Trace this forgotten rune with your finger and spend a Hope to roll a d6. 1: mark a Stress. 2-3: nothing happens. 4- 5: you gain advantage on your next Spellcast Roll. 6: clear all Stress.","ru":"Древний Рунный Камень","rud":"Обведите пальцем эту забытую руну и потратьте Надежду, чтобы бросить d6: 1 - получите Стресс; 2-3 - ничего не происходит; 4-5 - преимущество к следующему броску заклинания; 6 - снимите весь Стресс.","img":"w6.webp"},{"id":"w7","src":"wondrous","kind":"item","roll":7,"en":"Arcane Scalpel","ende":"SecondaryWeapon Finesse, Far, mag d6+2, One-Handed. Incorporeal: The scalpel deals its wounds magically to the target at a distance as direct damage.","ru":"Арканный Скальпель","rud":"Дополнительное оружие. Искусность, Дальняя, маг d6+2, Одноручное. Нематериальный: скальпель наносит Раны магически на расстоянии как прямой урон.","img":"w7.webp"},{"id":"w8","src":"wondrous","kind":"consumable","roll":8,"en":"Arcane Stuffing","ende":"When you stuff a dead creature with this magic-infused sawdust as a downtime move, it becomes an animate servant, as if by the Book of Exota \"Create Construct\" feature.","ru":"Арканная Набивка","rud":"Когда вы набиваете мёртвое существо этими пропитанными магией опилками в качестве хода привала, оно становится ожившим слугой, как по свойству «Создать Конструкт» книги Экзота.","img":"w8.webp"},{"id":"w9","src":"wondrous","kind":"consumable","roll":9,"en":"Archivist's Rot","ende":"For the scene, you have advantage on all Instinct rolls, but if you fail such a roll, you must mark a Stress. Craftinto:.","ru":"Архивная Гниль","rud":"На время сцены вы получаете преимущество ко всем броскам Инстинкта, но при провале такого броска вы должны получить Стресс. Переработать в: Тоник Споровой Мысли.","img":"w9.webp"},{"id":"w10","src":"wondrous","kind":"consumable","roll":10,"en":"Astral Termite Jaws","ende":"Using these jaws, you can chew into any wall to create a portal to another wall within Far range.","ru":"Челюсти Астрального Термита","rud":"С помощью этих челюстей вы можете прогрызть любую стену, создав портал к другой стене в пределах Дальней дистанции.","img":"w10.webp"},{"id":"w11","src":"wondrous","kind":"consumable","roll":11,"en":"Backsies Stone","ende":"You can swallow this stone and spend all your Hope (minimum 1) to unsay the last sentence you spoke within this scene. Reality is altered so that the words were never said, and all their consequences are undone.","ru":"Камень Возврата","rud":"Вы можете проглотить этот камень и потратить всю Надежду (минимум 1), чтобы «отозвать» последнюю фразу, произнесённую вами в этой сцене. Реальность меняется так, словно эти слова никогда не были сказаны, и все их последствия отменяются.","img":"w11.webp"},{"id":"w12","src":"wondrous","kind":"item","roll":12,"en":"Big Bug Begone","ende":"Once per rest, point this giant beetle antenna at any giant invertebrate within Close range and force it to make a Reaction Roll (15). On a failure, it is permanently transformed into a normal-sized creature of the same kind.","ru":"Отвадитель Жуков","rud":"Один раз за отдых наведите эту антенну гигантского жука на любое гигантское беспозвоночное в пределах Средней дистанции, принудив его к броску реакции (15). При провале оно навсегда превращается в существо нормального размера того же вида.","img":"w12.webp"},{"id":"w13","src":"wondrous","kind":"consumable","roll":13,"en":"Blood of the Kaiju","ende":"When you drink this ichor, your Hope Die becomes a d20 until the end of the scene. When it ends, mark all your remaining Stress slots.","ru":"Кровь Кайдзю","rud":"Когда вы выпиваете эту кровь, ваша Кость Надежды становится d20 до конца сцены. Когда эффект заканчивается, заполните все оставшиеся ячейки Стресса.","img":"w13.webp"},{"id":"w14","src":"wondrous","kind":"consumable","roll":14,"en":"Blossomveil Petal","ende":"You have advantage on your next Presence Reaction Roll until a short or long rest. The petal is destroyed in sunlight.","ru":"Лепесток Цветочной Вуали","rud":"До следующего короткого или долгого отдыха вы получаете преимущество к следующему броску реакции Влияния. Лепесток уничтожается на солнечном свету.","img":"w14.webp"},{"id":"w15","src":"wondrous","kind":"item","roll":15,"en":"Bogglass Reed","ende":"Once per rest, while holding this reed, you can take the spotlight when the GM spends a Fear. Craftinto: ChronoQuill.","ru":"Тростник Трясинного Стекла","rud":"Один раз за отдых, держа этот тростник, вы можете получить активацию, когда Мастер тратит Страх. Переработать в: Хронопера.","img":"w15.webp"},{"id":"w16","src":"wondrous","kind":"consumable","roll":16,"en":"Book of No History","ende":"When you read this book, it tells your own biography. If you then erase parts of it or tear out pages, those elements of your past are forgotten. No one other than you remembers your part in them.","ru":"Книга Беспамятства","rud":"Когда вы читаете эту книгу, она рассказывает вашу биографию. Если затем стереть части или вырвать страницы, эти события вашего прошлого будут забыты. Никто, кроме вас, не будет помнить вашего участия в них.","img":"w16.webp"},{"id":"w17","src":"wondrous","kind":"consumable","roll":17,"en":"Boomberry Jam","ende":"A jar of this jam contains 5 portions. A single portion makes a tasty meal. Alternatively, you can throw the jar at a point within Far range. All creatures within Close range of it take Xd8+4 physical damage, where X is the number of portions remaining.","ru":"Варенье из Грохотягод","rud":"Банка содержит несколько порций. Одна порция составляет сытный обед. Также вы можете бросить банку в точку в пределах Дальней дистанции. Все существа в пределах Средней дистанции получают Xd8+4 физического урона, где X - количество оставшихся порций.","img":"w17.webp"},{"id":"w18","src":"wondrous","kind":"consumable","roll":18,"en":"Boomberry","ende":"Two of these berries will suffice for a full meal, but when you eat them, on a roll of 1 on a d12 they explode, causing you to mark 2 HP and 2 Stress. Craftinto:.","ru":"Грохотягода","rud":"Двух ягод достаточно для полноценного обеда, но если при поедании выпадет 1 на d12, они взрываются, вынуждая вас получить 2 Раны и 2 Стресса. Переработать в: Варенье из Грохотягод.","img":"w18.webp"},{"id":"w19","src":"wondrous","kind":"consumable","roll":19,"en":"Boomcoin","ende":"Spend a Hope to activate the coin and start a Countdown (4). When the countdown triggers, the coin explodes, dealing 3d6 physical damage to all targets within Very Close range. Targets outside Melee range that succeed on an Agility Reaction Roll (12) take no damage.","ru":"Монета-Бум","rud":"Потратьте Надежду, чтобы активировать монету и запустить счётчик (4). Когда счётчик срабатывает, монета взрывается, нанося 3d6 физического урона всем целям в пределах Ближней дистанции. Цели за пределами зоны Вплотную, преуспевшие в броске реакции Проворности (12), урона не получают.","img":"w19.webp"},{"id":"w20","src":"wondrous","kind":"consumable","roll":20,"en":"Bottled Song","ende":"Opening the bottle releases a beautiful melody. All creatures within Very Close range clear a Stress.","ru":"Песня в Бутылке","rud":"Открытие бутылки высвобождает прекрасную мелодию. Все существа в пределах Ближней дистанции снимают один Стресс.","img":"w20.webp"},{"id":"w21","src":"wondrous","kind":"item","roll":21,"en":"Bubble Wand","ende":"Once per long rest, you can activate this wand with a successful Finesse Roll (10) to produce a stream of bubbles, giving disadvantage on the next attack against you. If the attack misses, you gain a Hope.","ru":"Пузырная Палочка","rud":"Один раз за долгий отдых вы можете активировать эту палочку при успешном броске Искусности (14), создав поток пузырей, которые дают помеху к следующей атаке против вас. Если атака промахивается, вы получаете Надежду.","img":"w21.webp"},{"id":"w22","src":"wondrous","kind":"item","roll":22,"en":"Bug Hunter's Aegis","ende":"SecondaryWeapon Strength, Melee, phy d4, One-Handed. Swatter: +1 to Armor Score; mark a Stress to knock a flying creature smaller than you within Melee range to the ground. 69 LOOT DESCRIPTION.","ru":"Щит Охотника на Жуков","rud":"Дополнительное оружие. Сила, Вплотную, физ d4, Одноручное. Прихлопыватель: +1 к Значению брони; получите Стресс, чтобы сбить летящее существо меньше вас в пределах зоны Вплотную на землю.","img":"w22.webp"},{"id":"w23","src":"wondrous","kind":"item","roll":23,"en":"Calming Censer","ende":"This contraption disperses smoke that calms insects and other bugs up to Close range of you, giving them disadvantage on attacks for the scene. Once burned, it needs refilling with fragrant herbs.","ru":"Усмиряющее Кадило","rud":"Это приспособление рассеивает дым, успокаивающий насекомых и других жуков в пределах Средней дистанции, давая им помеху к атакам на время сцены. Когда оно догорает, его нужно снова наполнить душистыми травами.","img":"w23.webp"},{"id":"w24","src":"wondrous","kind":"consumable","roll":24,"en":"Cathartoid Egg","ende":"As a death move, you can break this egg. You rise again in the form of an ancient, black-winged avian with all your memories, but your only desire is now to reside in the Sanctum Mortalis.","ru":"Яйцо Катартоида","rud":"В качестве хода смерти вы можете разбить это яйцо. Вы восстаёте в облике древней чернокрылой птицы со всеми своими воспоминаниями, но вашим единственным желанием отныне становится обитать в Санктуме Морталис.","img":"w24.webp"},{"id":"w25","src":"wondrous","kind":"item","roll":25,"en":"Claws of Yifang","ende":"MagicWeapon Presence, Far, d8+4, One-Handed. Channeling: When you take magic damage, you can mark a Stress to halve the damage and store the rest in the Claws. The stored damage is added to your next damage roll with the Claws.","ru":"Когти Ифанга","rud":"Магическое оружие. Влияние, Дальняя, d8+4, Одноручное. Накопление: когда вы получаете магический урон, вы можете получить Стресс, чтобы вдвое уменьшить урон и сохранить остаток в Когтях. Накопленный урон прибавляется к следующему броску урона Когтями.","img":"w25.webp"},{"id":"w26","src":"wondrous","kind":"item","roll":26,"en":"Croakroot Pad","ende":"As a downtime move you can meditate on this pad to ask the GM a question about your past or future. Until your next rest you take 1d6 magic damage whenever you make an Insight Roll with Fear.","ru":"Кувшинка-Пифия","rud":"В качестве хода привала вы можете медитировать на этой кувшинке, задав Мастеру вопрос о вашем прошлом или будущем. До следующего отдыха вы получаете 1d6 магического урона при каждом броске Инстинкта со Страхом.","img":"w26.webp"},{"id":"w27","src":"wondrous","kind":"consumable","roll":27,"en":"Crystals from Beyond","ende":"These azure stones contain the essence of other worlds. If broken by magic damage, they cause plants and animals within Close range to mutate into alien forms.","ru":"Кристаллы Иномирья","rud":"Эти лазурные камни содержат сущность иных миров. Если разбить их магическим уроном, растения и животные в пределах Средней дистанции мутируют в чуждые формы.","img":"w27.webp"},{"id":"w28","src":"wondrous","kind":"consumable","roll":28,"en":"Darkstone","ende":"If this onyx stone is exposed to magical light, it explodes, dealing 2d6 magic damage to any creature within Very Close range of it that fails an Agility Reaction Roll (14)","ru":"Тёмный Камень","rud":"Если этот ониксовый камень подвергается воздействию магического света, он взрывается, нанося 2d6 магического урона любому существу в пределах Ближней дистанции, которое проваливает бросок реакции Проворности (14)","img":"w28.webp"},{"id":"w29","src":"wondrous","kind":"consumable","roll":29,"en":"Demon Toad Bile","ende":"When this liquid is exposed to air, start a Countdown (4). When it triggers, the liquid explodes, dealing 2d6 physical damage to any creature within Very Close range.","ru":"Желчь Демонической Жабы","rud":"Когда эта жидкость контактирует с воздухом, запустите счётчик (4). Когда он срабатывает, жидкость взрывается, нанося 2d6 физического урона любому существу в пределах Ближней дистанции.","img":"w29.webp"},{"id":"w30","src":"wondrous","kind":"item","roll":30,"en":"Detuner","ende":"Once per long rest, you can spend a Hope to activate the detuner. Any melody produced within Far range is disrupted. A creature creating a magical tune can mark a Stress to maintain it or it is forced to stop.","ru":"Расстроитель","rud":"Один раз за долгий отдых вы можете потратить Надежду, чтобы активировать расстроитель. Любая мелодия в пределах Дальней дистанции прерывается. Существо, создающее магический мотив, может получить Стресс, чтобы поддержать его, иначе вынуждено остановиться.","img":"w30.webp"},{"id":"w31","src":"wondrous","kind":"item","roll":31,"en":"Devil's Smithing Hammer","ende":"MagicWeapon Strength, Melee, d6+3, One-Handed. Deforming: When you hit a creature wearing metal armor, you can mark a Stress to deform it. The target gains a stacking -2 penalty to damage thresholds.","ru":"Молот Инфернального Кузнеца","rud":"Магическое оружие. Сила, Вплотную, d6+3, Одноручное. Деформирующий: когда вы попадаете по существу в металлической броне, вы можете получить Стресс, чтобы деформировать её. Цель получает накапливающийся штраф -2 к порогам урона.","img":"w31.webp"},{"id":"w32","src":"wondrous","kind":"consumable","roll":32,"en":"Doomsday Potion","ende":"Roll a d12 for each of your Hope Slots in turn. If the slot is marked, roll 2d12 and choose the higher value. If you roll less than 12, cross out the slot. If you roll 12, stop rolling, clear all your HP and Stress, and become Invincible until the end of the scene. While Invincible you're immune to all damage and your Proficiency is doubled. At the end of the scene, make a death move.","ru":"Зелье Судного Дня","rud":"Бросьте d12 за каждую ячейку Надежды по очереди. Если ячейка отмечена, бросьте 2d12 и выберите большее значение. При результате ниже 12 вычеркните ячейку. При результате 12 прекратите броски, снимите все Раны и Стресс и станьте Неуязвимым до конца сцены: вы невосприимчивы ко всему урону, а ваше Мастерство удваивается. В конце сцены совершите ход смерти.","img":"w32.webp"},{"id":"w33","src":"wondrous","kind":"item","roll":33,"en":"Dread-Weave Boots","ende":"While wearing these boots, you have resistance to any magic damage triggered by contact with the ground.","ru":"Сапоги Жуткого Плетения","rud":"Пока вы носите эти сапоги, вы получаете сопротивление к любому магическому урону, вызванному контактом с землёй.","img":"w33.webp"},{"id":"w34","src":"wondrous","kind":"item","roll":34,"en":"Dreamer's Shard","ende":"During a long rest, you can use this crystal to induce a prophetic dream, giving a hint to a question that is worrying you. When you do this, you must succeed on an Instinct Reaction Roll (14) or be trapped in a nightmare, paralyzed until someone wakes you.","ru":"Осколок Сновидца","rud":"Во время долгого отдыха вы можете использовать этот кристалл, чтобы вызвать пророческий сон, намекающий на ответ на волнующий вас вопрос. При этом вы должны преуспеть в броске реакции Инстинкта (14), иначе окажетесь в ловушке кошмара и будете Парализованы до тех пор, пока кто-нибудь вас не разбудит.","img":"w34.webp"},{"id":"w35","src":"wondrous","kind":"consumable","roll":35,"en":"Dust of Echoed Silence","ende":"When you scatter this dust, the area within Close range of you is silenced for the scene or until the dust is dispersed by strong wind. Creatures within that area can't speak or cast spells.","ru":"Пыль Отражённой Тишины","rud":"Когда вы рассыпаете эту пыль, пространство в пределах Средней дистанции от вас погружается в тишину на время сцены или пока пыль не развеет сильный ветер. Существа в этой зоне не могут говорить или произносить заклинания.","img":"w35.webp"},{"id":"w36","src":"wondrous","kind":"item","roll":36,"en":"Ebony Thread","ende":"You can unspool this thread up to 500 feet as you travel, creating an ethereal trail behind you. It's visible only to you, but creatures sensitive to spectral frequencies may be able to detect and follow it.","ru":"Чёрная Нить","rud":"Вы можете разматывать эту нить до 500 футов в пути, создавая за собой эфирный след. Он виден только вам, но существа, чувствительные к призрачным частотам, могут его обнаружить и проследовать по нему.","img":"w36.webp"},{"id":"w37","src":"wondrous","kind":"consumable","roll":37,"en":"Echo Orchid Petal","ende":"Consuming a petal while looking at a creature gives you insight into that creature's intentions. You have advantage on Reaction Rolls against its actions for the scene. Craftinto:.","ru":"Лепесток Эхо-Орхидеи","rud":"Употребление лепестка при взгляде на существо открывает его намерения. Вы получаете преимущество к броскам реакции против его действий на время сцены. Переработать в: Зелье Открытых Путей.","img":"w37.webp"},{"id":"w38","src":"wondrous","kind":"item","roll":38,"en":"Etheric Anchor","ende":"While carrying this anchor you can mark 2 Stress to automatically succeed on a Reaction Roll against the effects of spatial distortions or other hostile geography.","ru":"Эфирный Якорь","rud":"Пока вы несёте этот якорь, вы можете получить 2 Стресса, чтобы автоматически преуспеть в броске реакции против эффектов пространственных искажений или иной враждебной местности.","img":"w38.webp"},{"id":"w39","src":"wondrous","kind":"consumable","roll":39,"en":"Flare Tuber","ende":"If you hold one of these roots in your mouth, it provides enough oxygen for you to breathe normally, but you can't speak or cast spells.","ru":"Дыхательный Клубень","rud":"Если держать этот корень во рту, он обеспечивает достаточно кислорода для нормального дыхания, но вы не можете говорить или произносить заклинания.","img":"w39.webp"},{"id":"w40","src":"wondrous","kind":"item","roll":40,"en":"Flickerbloom","ende":"While carrying this flower, you have advantage on Reaction Rolls to resist any temporal anomalies, but if you fail such a roll, you must mark a Stress.","ru":"Мерцацвет","rud":"Пока вы несёте этот цветок, вы получаете преимущество к броскам реакции против любых временных аномалий, но при провале такого броска вы должны получить Стресс.","img":"w40.webp"},{"id":"w41","src":"wondrous","kind":"item","roll":41,"en":"Gravitic Tether","ende":"While wearing this belt, you take half damage from falls, and no damage from the effects of gravitational anomalies, but you can't travel further than Close range on your move.","ru":"Гравитационная Привязь","rud":"Пока вы носите этот пояс, вы получаете половину урона от падений и совсем не получаете урона от эффектов гравитационных аномалий, но не можете перемещаться далее Средней дистанции за ход.","img":"w41.webp"},{"id":"w42","src":"wondrous","kind":"consumable","roll":42,"en":"Griefroot Powder","ende":"When you inhale this powder, you add a d8 to your next action roll, but for the scene if you take damage or witness death you must succeed on a Presence Reaction Roll (14) or become Stunned. While Stunned, you can't use reactions and can't take any other actions until you clear this condition. Craftinto:.","ru":"Порошок Печалекорня","rud":"Когда вы вдыхаете этот порошок, вы добавляете d8 к следующему броску действия, но на время сцены при получении урона или при виде гибели вы должны преуспеть в броске реакции Влияния (14) или стать Оглушённым. Пока вы Оглушены, вы не можете использовать реакции и совершать другие действия, пока не снимете это состояние. Переработать в: Порошок Героя.","img":"w42.webp"},{"id":"w43","src":"wondrous","kind":"consumable","roll":43,"en":"Gyre Cap","ende":"Brewed into a tea as a downtime move, these mushrooms give any drinker advantage on Instinct rolls and disadvantage on Presence rolls until their next rest. Craftinto: Potion of SpiralingVision.","ru":"Вихревая Шляпка","rud":"Заваренные в чай в качестве хода привала, эти грибы дают любому выпившему преимущество к броскам Инстинкта и помеху к броскам Влияния до следующего отдыха. Переработать в: Зелье Спирального Зрения.","img":"w43.webp"},{"id":"w44","src":"wondrous","kind":"consumable","roll":44,"en":"Henry's Sugar","ende":"For this scene, you can mark a Stress to see through an object, or see its reverse side.","ru":"Сахар Генри","rud":"На время этой сцены вы можете получить Стресс, чтобы видеть сквозь объект или видеть его обратную сторону.","img":"w44.webp"},{"id":"w45","src":"wondrous","kind":"consumable","roll":45,"en":"Hero's Powder","ende":"When you inhale this powder, you can add a d4 to one action or reaction roll of your choice in the same scene. Each time you witness death before you do so, the die size increases to d6, d8, etc., up to d20.","ru":"Порошок Героя","rud":"Когда вы вдыхаете этот порошок, вы можете добавить d4 к одному броску действия или реакции на свой выбор в этой же сцене. Каждый раз, когда вы становитесь свидетелем смерти до его использования, размер кости увеличивается: d6, d8 и т.д. вплоть до d20.","img":"w45.webp"},{"id":"w46","src":"wondrous","kind":"item","roll":46,"en":"Hitcher's Towel","ende":"As long as you know where this towel is, your Hope Die can't be reduced or your Fear Die increased from a d12. Whenever you take a long rest, you must succeed on an Instinct Reaction Roll (14) or the towel is lost.","ru":"Полотенце Путешественника","rud":"Пока вы знаете, где находится это полотенце, ваша Кость Надежды не может опуститься ниже d12, а Кость Страха не может быть увеличена. При каждом долгом отдыхе вы должны преуспеть в броске реакции Инстинкта (14), иначе полотенце пропадает.","img":"w46.webp"},{"id":"w47","src":"wondrous","kind":"item","roll":47,"en":"Ice Gloves","ende":"When you pick up snow with these gloves you can form it into a deadly snowball and throw it as a weapon (Agility, Close, mag d6+1)","ru":"Ледяные Рукавицы","rud":"Когда вы берёте снег в эти рукавицы, вы можете слепить из него смертоносный снежок и бросить его как оружие (Проворность, Средняя, маг d6+1)","img":"w47.webp"},{"id":"w48","src":"wondrous","kind":"item","roll":48,"en":"Incantor's Chalk","ende":"You can inscribe a spell in your loadout onto a surface. You can then spend a Hope at any time to cast the spell, as if you were at the position of the marks. If the marks have been erased, the spell isn't cast.","ru":"Мел Заклинателя","rud":"Вы можете начертить заклинание из вашей экипировки на поверхности. Затем вы можете потратить Надежду в любое время, чтобы произнести это заклинание, как будто находясь на месте меток. Если метки были стёрты, заклинание не произносится.","img":"w48.webp"},{"id":"w49","src":"wondrous","kind":"item","roll":49,"en":"Jamming Spanner","ende":"Make a successful Finesse Roll to place this tool into a machine to prevent it from operating. The GM can spend a Fear to break the spanner and restart the machine, or you can remove it with a second roll. If you make either roll with Fear, you take damage. The Difficulty and damage depend on the machine.","ru":"Стопорный Ключ","rud":"При успешном броске Искусности вставьте этот инструмент в механизм, чтобы остановить его работу. Мастер может потратить Страх, чтобы сломать ключ и перезапустить механизм, или вы можете извлечь его вторым броском. При провале любого из этих бросков вы получаете урон. Сложность и урон зависят от механизма.","img":"w49.webp"},{"id":"w50","src":"wondrous","kind":"item","roll":50,"en":"Lantern of Shadows","ende":"While using this lantern, you can determine any illusions and see secret doors and passageways within Close range. When you roll with Fear, the lantern extinguishes, and can't be lit again until you take a long rest.","ru":"Фонарь Теней","rud":"Пока вы используете этот фонарь, вы можете распознавать иллюзии и видеть потайные двери и проходы в пределах Средней дистанции. Когда вы получаете бросок со Страхом, фонарь гаснет и не может быть зажжён снова до долгого отдыха.","img":"w50.webp"},{"id":"w51","src":"wondrous","kind":"item","roll":51,"en":"Leviathan Harpoon","ende":"PrimaryWeapon Finesse, Far, d8+3, Two-Handed. Tethered: On a successful attack, the target is Tethered to you. While Tethered, whenever the target moves away from you, you can remain at the same range from it. If you don't, or if you move away from the target, it clears the condition.","ru":"Гарпун Левиафана","rud":"Основное оружие. Искусность, Дальняя, d8+3, Двуручное. Привязанный: при успешной атаке цель становится Привязанной к вам. Пока она Привязана, когда цель перемещается от вас, вы можете оставаться на том же расстоянии от неё. Если вы этого не делаете или сами перемещаетесь от цели, состояние снимается.","img":"w51.webp"},{"id":"w52","src":"wondrous","kind":"consumable","roll":52,"en":"Liar's Bane","ende":"After you chew these leaves, for the scene you have advantage on rolls to notice traps and see through lies and deceptions, but you must mark a Stress to deceive someone else. Craftinto: TrueVision Serum.","ru":"Погибель Лжецов","rud":"После того как вы разжуёте эти листья, на время сцены вы получаете преимущество к броскам для обнаружения ловушек и распознавания лжи и обмана, но должны получить Стресс, чтобы солгать кому-либо. Переработать в: Сыворотку Истинного Зрения.","img":"w52.webp"},{"id":"w53","src":"wondrous","kind":"consumable","roll":53,"en":"Life Force Beacon","ende":"Spend a Hope to activate this orb. For the scene, it radiates life force as if it were a living creature. Any spirits attracted to life force must mark a Stress to attack anything other than the orb within Far range of it.","ru":"Маяк Жизненной Силы","rud":"Потратьте Надежду, чтобы активировать этот шар. На время сцены он излучает жизненную силу, будто живое существо. Любые духи, привлечённые жизненной силой, должны получить Стресс, чтобы атаковать что-либо, кроме шара, в пределах Дальней дистанции от него.","img":"w53.webp"},{"id":"w54","src":"wondrous","kind":"item","roll":54,"en":"Life Wand","ende":"MagicWeapon Knowledge, Far, d6+4, One-Handed. Life-Linked: +2 to Spellcast Rolls against undead creatures; succeed on a Spellcast Roll to temporarily Stun an undead. While Stunned, they can't use reactions and can't take any other actions.","ru":"Жезл Жизни","rud":"Магическое оружие. Знание, Дальняя, d6+4, Одноручное. Связь с жизнью: +2 к броскам заклинания против нежити; при успешном броске заклинания временно Оглушите нежить. Пока она Оглушена, она не может использовать реакции и совершать другие действия.","img":"w54.webp"},{"id":"w55","src":"wondrous","kind":"item","roll":55,"en":"Lightning Scarab","ende":"When you're hit by electrical damage, you can divert it into this brooch, then roll your Duality Dice. If the total is less than the diverted damage, the brooch explodes and you take the sum of all the damage it has absorbed.","ru":"Громовой Скарабей","rud":"Когда вы получаете электрический урон, вы можете перенаправить его в эту брошь, а затем бросить Кости Дуализма. Если сумма меньше накопленного урона, брошь взрывается и вы получаете весь накопленный урон суммарно.","img":"w55.webp"},{"id":"w56","src":"wondrous","kind":"item","roll":56,"en":"Lovebugs","ende":"Place one of these ceramic bugs in any location. When you place the other one on the floor up to a mile away, they will crawl toward one another by the fastest available route.","ru":"Жуки-Влюблённые","rud":"Поместите одного из этих керамических жуков в любом месте. Когда вы положите второго на пол в пределах мили, они поползут навстречу друг другу по кратчайшему доступному пути.","img":"w56.webp"},{"id":"w57","src":"wondrous","kind":"item","roll":57,"en":"Manacle Bolas","ende":"SecondaryWeapon Finesse, Close, phy d4+1, One-Handed. Restraining: When you hit a target you can spend a Hope to Restrain it. A trapped target can break free with a successful Strength Roll (16)","ru":"Кандальные Болас","rud":"Дополнительное оружие. Искусность, Средняя, физ d4+1, Одноручное. Сковывающие: когда вы попадаете по цели, вы можете потратить Надежду, чтобы Схватить её. Схваченная цель может освободиться при успешном броске Силы (16)","img":"w57.webp"},{"id":"w58","src":"wondrous","kind":"consumable","roll":58,"en":"Martyr's Grass","ende":"As a downtime move, you can plant a sprig of this fragrant herb in the barest soil. It gives everyone within Close range a peaceful slumber, clearing all Stress.","ru":"Трава Мученика","rud":"В качестве хода привала вы можете посадить веточку этого душистого растения в скудную почву. Оно погружает всех в пределах Средней дистанции в мирный сон, снимая весь Стресс.","img":"w58.webp"},{"id":"w59","src":"wondrous","kind":"item","roll":59,"en":"Mimicry Mask","ende":"While wearing this mask, once per scene you can mimic a creature within Close range. Until you are next spotlighted, they experience either delayed speech (must mark a Stress to speak), erratic movements (disadvantage on reaction rolls), or clumsy attacks (disadvantage on attack rolls)","ru":"Маска Подражателя","rud":"Пока вы носите эту маску, один раз за сцену вы можете имитировать существо в пределах Средней дистанции. До вашей следующей активации оно испытывает одно из: запоздалую речь (должно получить Стресс, чтобы говорить), беспорядочные движения (помеха к броскам реакции) или неловкие атаки (помеха к броскам атаки)","img":"w59.webp"},{"id":"w60","src":"wondrous","kind":"consumable","roll":60,"en":"Mucin of Slipperiness","ende":"You can apply this slime to your body as a downtime move. Once coated, until your next rest you have advantage on Reaction Rolls to avoid being Restrained.","ru":"Слизь Скользкости","rud":"Вы можете нанести эту слизь на тело в качестве хода привала. После нанесения до следующего отдыха вы получаете преимущество к броскам реакции, чтобы избежать Захвата.","img":"w60.webp"},{"id":"w61","src":"wondrous","kind":"consumable","roll":61,"en":"Needle Key","ende":"When you embed this needle in your finger, until your next long rest your Finesse modifier is reduced by 1, but when you press your finger against a lock you can mark a Stress to morph it into a matching key.","ru":"Игольный Ключ","rud":"Когда вы вонзаете эту иглу в палец, до следующего долгого отдыха ваш модификатор Искусности снижается на 1, но когда вы прижимаете палец к замку, вы можете получить Стресс, чтобы игла превратилась в подходящий ключ.","img":"w61.webp"},{"id":"w62","src":"wondrous","kind":"consumable","roll":62,"en":"Nursewood Sap","ende":"Rub onto a creature to clear 1d4 HP, 1d4 Stress, or one condition.","ru":"Целебная Смола","rud":"Нанесите на существо, чтобы снять 1d4 Раны, 1d4 Стресса или одно состояние.","img":"w62.webp"},{"id":"w63","src":"wondrous","kind":"consumable","roll":63,"en":"Pastries of Warmth","ende":"A basket contains 1d4 pastries. When you consume a pastry, you don't take damage or mark Stress from exposure to cold until your next rest. 71 LOOT DESCRIPTION.","ru":"Согревающие Пирожки","rud":"Корзина содержит 1d4 пирожков. Когда вы съедаете один, вы не получаете урона и Стресса от воздействия холода до следующего отдыха.","img":"w63.webp"},{"id":"w64","src":"wondrous","kind":"item","roll":64,"en":"Pathfinder's Ledger","ende":"If you scribe your path into this book as you travel, you have advantage on rolls to navigate or avoid being disoriented. If you fail such a roll with Fear, you lose one piece of information you previously knew.","ru":"Гроссбух Первопроходца","rud":"Если вы записываете свой путь в эту книгу в дороге, вы получаете преимущество к броскам на ориентирование или избегание дезориентации. При провале такого броска со Страхом вы теряете один ранее известный вам факт.","img":"w64.webp"},{"id":"w65","src":"wondrous","kind":"consumable","roll":65,"en":"Phantom Fern Shoots","ende":"Eaten raw, these shoots remove the effect of most poisons, but leave you Lightheaded for 1 hour. While Lightheaded, roll a d8 as your disadvantage die. Craftinto:.","ru":"Побеги Призрачного Папоротника","rud":"Съеденные в сыром виде, эти побеги устраняют действие большинства ядов, но оставляют вас в лёгком Дурмане на 1 час. Пока вы в Дурмане, бросайте d8 в качестве кости помехи. Переработать в: Чай из Призрачного Папоротника.","img":"w65.webp"},{"id":"w66","src":"wondrous","kind":"consumable","roll":66,"en":"Phantom Fern Tea","ende":"Phantom Fern Tea ᶜ Remove the effect of most poisons.","ru":"Чай из Призрачного Папоротника","rud":"Устраняет действие большинства ядов.","img":"w66.webp"},{"id":"w67","src":"wondrous","kind":"consumable","roll":67,"en":"Planar Wood","ende":"When crafting a magic weapon from this infused wood, make a Finesse Roll (15). On a success, the weapon has a bonus to damage rolls of +1 (success with Fear), +2 (success with Hope), or +3 (critical success)","ru":"Межпланарная Древесина","rud":"При создании магического оружия из этой пропитанной древесины совершите бросок Искусности (15). При успехе оружие получает бонус к броскам урона: +1 (успех со Страхом), +2 (успех с Надеждой) или +3 (критический успех)","img":"w67.webp"},{"id":"w68","src":"wondrous","kind":"consumable","roll":68,"en":"Potion of Revealed Paths","ende":"Drinking this potion while looking at a creature allows you to use the Thought Delver spell on them unlimited times during the scene, using Instinct as the spellcast trait if you don't have one.","ru":"Зелье Открытых Путей","rud":"Выпив это зелье при взгляде на существо, вы можете применять к нему заклинание «Искатель Мыслей» неограниченное количество раз на время сцены, используя Инстинкт как атрибут заклинания, если у вас нет соответствующего.","img":"w68.webp"},{"id":"w69","src":"wondrous","kind":"consumable","roll":69,"en":"Potion of Spiraling Vision","ende":"Once per scene until your next rest, when you make a roll with your Duality Dice, you can mark a Stress to postpone the result and roll again, using the postponed result for your next roll. If you fail to use the postponed result in the scene, you permanently lose a Stress.","ru":"Зелье Спирального Зрения","rud":"Один раз за сцену до следующего отдыха, когда вы совершаете бросок Костей Дуализма, вы можете получить Стресс, чтобы отложить результат и бросить снова, используя отложенный результат для следующего броска. Если вы не используете отложенный результат в сцене, вы навсегда теряете одну ячейку Стресса.","img":"w69.webp"},{"id":"w70","src":"wondrous","kind":"consumable","roll":70,"en":"Prismatic Water","ende":"Drinking this water has unpredictable effects. Roll your Duality Dice. On a roll with Hope, you permanently gain a Hope slot. On a roll with Fear, you lose 2 Hope and cross out a Hope slot. On a critical success, you also gain a +1 bonus to a trait of your choice.","ru":"Призматическая Вода","rud":"Питьё этой воды имеет непредсказуемые эффекты. Бросьте Кости Дуализма. При броске с Надеждой вы навсегда получаете ячейку Надежды. При броске со Страхом вы теряете 2 Надежды и вычёркиваете ячейку Надежды. При критическом успехе вы также получаете +1 к атрибуту на ваш выбор.","img":"w70.webp"},{"id":"w71","src":"wondrous","kind":"item","roll":71,"en":"Puddleduck's Fins","ende":"While wearing these fins on your feet, you must mark a Stress to move further than Very Close range on land, but you can move at normal speed when swimming. A druid wearing these fins can Beastform into an Aquatic Scout without marking a Stress.","ru":"Ласты Лужелуточки","rud":"Пока вы носите эти ласты, вы должны получить Стресс, чтобы переместиться дальше Ближней дистанции на суше, но можете плыть с нормальной скоростью. Друид в этих ластах может принять звериную форму Водного Разведчика без получения Стресса.","img":"w71.webp"},{"id":"w72","src":"wondrous","kind":"item","roll":72,"en":"Pure Crystal","ende":"Once per session, when you use a feature that restores HP to a creature, restore one additional HP.","ru":"Чистый Кристалл","rud":"Один раз за сессию, когда вы используете свойство, восстанавливающее Раны существу, восстановите одну дополнительную Рану.","img":"w72.webp"},{"id":"w73","src":"wondrous","kind":"item","roll":73,"en":"Quill of Memory","ende":"You can write up to a hundred words with this quill as a downtime move. They don't appear on the page but are etched into your mind. No effect can erase them, and you don't need to make a roll to recall them.","ru":"Перо Памяти","rud":"Вы можете написать до ста слов этим пером в качестве хода привала. Они не появляются на странице, но запечатлеваются в вашем разуме. Никакой эффект не может стереть их, и вам не нужно совершать бросок, чтобы вспомнить их.","img":"w73.webp"},{"id":"w74","src":"wondrous","kind":"consumable","roll":74,"en":"Radiant Shard","ende":"When you shatter this shard of planar energy, it releases a burst of light that saturates the area within Far range. Until your next long rest, no spirit can enter this area and any environmental curses are suppressed.","ru":"Лучезарный Осколок","rud":"Когда вы разбиваете этот осколок планарной энергии, он высвобождает вспышку света, насыщающую пространство в пределах Дальней дистанции. До следующего долгого отдыха ни один дух не может войти в эту область, а все проклятия окружения подавляются.","img":"w74.webp"},{"id":"w75","src":"wondrous","kind":"item","roll":75,"en":"Red Nose of Hope","ende":"While wearing this nose you have advantage on Presence Rolls to entertain an audience. Once per long rest, you can also mark a Stress to turn a roll with Fear into a roll with Hope.","ru":"Красный Нос Надежды","rud":"Пока вы носите этот нос, вы получаете преимущество к броскам Влияния для развлечения аудитории. Один раз за долгий отдых вы также можете получить Стресс, чтобы превратить бросок со Страхом в бросок с Надеждой.","img":"w75.webp"},{"id":"w76","src":"wondrous","kind":"item","roll":76,"en":"Rootslicer Gauntlet","ende":"You have advantage on attacks and Reaction Rolls against plant-based creatures and hazards. Each time you use this feature, the GM gains a Fear.","ru":"Перчатка Корнереза","rud":"Вы получаете преимущество к атакам и броскам реакции против растительных существ и опасностей. Каждый раз, когда вы используете это свойство, Мастер получает Страх.","img":"w76.webp"},{"id":"w77","src":"wondrous","kind":"consumable","roll":77,"en":"Scaffold Web","ende":"When a structure within Very Close range of you is collapsing you can make an Agility Reaction Roll (14) to deploy this fast-acting membrane and prevent it. The GM can spend a Fear to break it again.","ru":"Опорная Паутина","rud":"Когда конструкция в пределах Ближней дистанции начинает рушиться, вы можете совершить бросок реакции Проворности (14), чтобы развернуть эту быстродействующую мембрану и предотвратить обрушение. Мастер может потратить Страх, чтобы разрушить её снова.","img":"w77.webp"},{"id":"w78","src":"wondrous","kind":"consumable","roll":78,"en":"Seaworthy Charm","ende":"This symbol will transfer itself onto the body of a boat when pressed against its side. For the scene, the boat can't be capsized and has resistance to all damage.","ru":"Оберег Мореплавателя","rud":"Этот символ переносится на корпус лодки при прикосновении к её борту. На время сцены лодка не может перевернуться и получает сопротивление ко всем видам урона.","img":"w78.webp"},{"id":"w79","src":"wondrous","kind":"item","roll":79,"en":"Seeker's Bow","ende":"PrimaryWeapon Finesse, Far, d6+4, Two-Handed. Echo: You can fire a spectral arrow that deals no damage, but on a hit moves the target to where it was before it was last spotlighted. The next time it is spotlighted it must repeat its actions from the previous time. If it can't do this, it marks a Stress.","ru":"Лук Искателя","rud":"Основное оружие. Искусность, Дальняя, d6+4, Двуручное. Эхо: вы можете выпустить призрачную стрелу, не наносящую урона, но при попадании перемещающую цель туда, где она была до последней активации. При следующей активации она должна повторить свои прошлые действия. Если это невозможно, она получает Стресс.","img":"w79.webp"},{"id":"w80","src":"wondrous","kind":"consumable","roll":80,"en":"Shadowangler Lure","ende":"Activating this lure causes it to glow. Any creature within Far range must make an Instinct Reaction Roll (12). On a failure, they move in to Very Close range.","ru":"Приманка Теневого Удильщика","rud":"Активация этой приманки заставляет её светиться. Любое существо в пределах Дальней дистанции должно совершить бросок реакции Инстинкта (12). При провале оно перемещается в пределы Ближней дистанции.","img":"w80.webp"},{"id":"w81","src":"wondrous","kind":"item","roll":81,"en":"Siren's Rock","ende":"If you place this weathered and barnacle-laden stone in seawater, creatures within Close range must succeed on a Presence Reaction Roll (12) or become temporarily Enraptured. Enraptured creatures can't make attack rolls and must mark a Stress to move anywhere except toward the stone.","ru":"Камень Сирены","rud":"Если вы помещаете этот выщербленный, покрытый ракушками камень в морскую воду, существа в пределах Средней дистанции должны преуспеть в броске реакции Влияния (12) или временно стать Восхищёнными. Восхищённые существа не могут совершать броски атаки и должны получить Стресс, чтобы переместиться куда-либо, кроме направления к камню.","img":"w81.webp"},{"id":"w82","src":"wondrous","kind":"item","roll":82,"en":"Snowblade","ende":"MagicWeapon Agility, Melee, d8+6, One-Handed. Freezing: On a successful attack, the target is temporarily Restrained. If you take damage from fire, the Snowblade loses this feature.","ru":"Снежный Клинок","rud":"Магическое оружие. Проворность, Вплотную, d8+6, Одноручное. Заморозка: при успешной атаке цель временно Схвачена. Если вы получаете урон от огня, Снежный Клинок теряет это свойство.","img":"w82.webp"},{"id":"w83","src":"wondrous","kind":"item","roll":83,"en":"Soul Torch","ende":"This torch burns with a cold, magical fire whenever you hold it in your hand. If it's extinguished by external means, you can see dimly in complete darkness until you roll with Fear. 72 LOOT DESCRIPTION.","ru":"Факел Души","rud":"Этот факел горит холодным магическим огнём, пока вы держите его в руке. Если он гаснет по внешним причинам, вы можете смутно видеть в полной темноте, пока не получите бросок со Страхом.","img":"w83.webp"},{"id":"w84","src":"wondrous","kind":"item","roll":84,"en":"Soulweave Cloak","ende":"While wearing this cloak, once per long rest you can become Incorporeal, able to move through physical objects and resistant to physical damage, until you end the condition or the GM spends a Fear to do so. Other incorporeal creatures have advantage on attacks against you while you are in this form.","ru":"Душетканый Плащ","rud":"Пока вы носите этот плащ, один раз за долгий отдых вы можете стать Бестелесным, способным проходить сквозь физические объекты и устойчивым к физическому урону, пока вы не снимете состояние или Мастер не потратит Страх. Другие Бестелесные существа получают преимущество к атакам против вас в этой форме.","img":"w84.webp"},{"id":"w85","src":"wondrous","kind":"item","roll":85,"en":"Spider's Sting","ende":"MagicWeapon Strength, Melee, d8+3, One-Handed. Webslinger: You can temporarily Restrain a target within Close range by succeeding on a Finesse Roll against them.","ru":"Паучье Жало","rud":"Магическое оружие. Сила, Вплотную, d8+3, Одноручное. Паутинострел: вы можете временно Схватить цель в пределах Средней дистанции при успешном броске Искусности против неё.","img":"w85.webp"},{"id":"w86","src":"wondrous","kind":"item","roll":86,"en":"Spirit Seeker","ende":"Hold out this willow wand and spend a Hope to sense the location of the nearest dead or undead creature larger than a cat within Far range.","ru":"Искатель Духов","rud":"Вытяните этот ивовый жезл и потратьте Надежду, чтобы почувствовать местоположение ближайшего мёртвого или нежити крупнее кошки в пределах Дальней дистанции.","img":"w86.webp"},{"id":"w87","src":"wondrous","kind":"consumable","roll":87,"en":"Sporemind Tonic","ende":"Until your next rest you have advantage on all Instinct rolls, but if you fail such a roll with Fear, you must mark a Stress.","ru":"Тоник Споровой Мысли","rud":"До следующего отдыха вы получаете преимущество ко всем броскам Инстинкта, но при провале такого броска со Страхом вы должны получить Стресс.","img":"w87.webp"},{"id":"w88","src":"wondrous","kind":"item","roll":88,"en":"Staff of the Whispering Archive","ende":"MagicWeapon Knowledge, Far, d8+6, Two-Handed. Watchful: You can cast the Floating Eye spell once per long rest. When you do so, for that scene you have disadvantage on Reaction Rolls against mind reading or clairvoyance.","ru":"Посох Шепчущего Архива","rud":"Магическое оружие. Знание, Дальняя, d8+6, Двуручное. Бдительный: вы можете произнести заклинание «Парящий Глаз» один раз за долгий отдых. При этом на время сцены вы получаете помеху к броскам реакции против чтения мыслей или ясновидения.","img":"w88.webp"},{"id":"w89","src":"wondrous","kind":"item","roll":89,"en":"Stingshield Robes","ende":"While wearing these bug-resistant clothes, until you mark an Armor Slot you are immune from damage by any creature up to the size of a bee, and resistant to damage from all creatures up to the size of a mouse.","ru":"Робы Жалозащиты","rud":"Пока вы носите эту одежду, защищающую от насекомых, до тех пор пока вы не потратите ячейку Брони, вы невосприимчивы к урону от существ размером не более пчелы и устойчивы к урону от всех существ размером не более мыши.","img":"w89.webp"},{"id":"w90","src":"wondrous","kind":"consumable","roll":90,"en":"Storm in a Bottle","ende":"When this bottle is opened or broken, all creatures in Close range must succeed on an Agility Reaction Roll (15) or be struck by lightning for 3d10+3 physical damage. Unsecured objects are scattered and broken.","ru":"Буря в Бутылке","rud":"Когда эта бутылка открывается или разбивается, все существа в пределах Средней дистанции должны преуспеть в броске реакции Проворности (15) или быть поражены молнией, получив 3d10+3 физического урона. Незакреплённые предметы разлетаются и ломаются.","img":"w90.webp"},{"id":"w91","src":"wondrous","kind":"item","roll":91,"en":"Superior Alconite Crystal","ende":"You can use the energy in this crystal to gain a 1d4 bonus to a Spellcast Roll. If you roll a 4, the energy is expended and it can't be reused until you recharge it as a downtime move by immersing it in salt water.","ru":"Превосходный Алконитовый Кристалл","rud":"Вы можете использовать энергию этого кристалла, чтобы получить бонус 1d4 к броску заклинания. Если выпадет 4, энергия исчерпывается и кристалл нельзя использовать повторно до тех пор, пока вы не зарядите его в качестве хода привала, погрузив в солёную воду.","img":"w91.webp"},{"id":"w92","src":"wondrous","kind":"item","roll":92,"en":"Tarrasque Sinew","ende":"When you string a bow with this powerful cord, it gains the following feature. Titan-Slayer: You gain a +1 bonus to your Proficiency when you hit a creature more than twice your size.","ru":"Сухожилие Тарраска","rud":"Когда вы натягиваете лук этой мощной тетивой, он получает следующее свойство. Убийца Титанов: вы получаете +1 к Мастерству, когда попадаете по существу, вдвое превышающему вас по размеру.","img":"w92.webp"},{"id":"w93","src":"wondrous","kind":"item","roll":93,"en":"Ticket Master's Pouch","ende":"The pouch can hold a handful of gold. When you use the gold from inside it to pay for something up to a bag of gold in value, you have advantage on Presence Rolls to haggle for the price.","ru":"Сумочка Кассира","rud":"Кошель может вместить горсть золота. Когда вы используете золото из него для оплаты чего-либо стоимостью до мешка золота, вы получаете преимущество к броскам Влияния для торга.","img":"w93.webp"},{"id":"w94","src":"wondrous","kind":"item","roll":94,"en":"Timeglass","ende":"Once per session, you can look through this spyglass as if looking through it in the same location some time in the past. You can set it to any length of time from 10 minutes to 10 days.","ru":"Времястекло","rud":"Один раз за сессию вы можете смотреть в эту подзорную трубу, как будто смотрите через неё в то же место в какой-то момент прошлого. Вы можете установить любой промежуток от 10 минут до 10 дней.","img":"w94.webp"},{"id":"w95","src":"wondrous","kind":"consumable","roll":95,"en":"Tincture of Fortified Thoughts","ende":"You clear 1d4 Stress and have advantage on Reaction Rolls against effects to change your state of mind. If you fail such a Reaction Roll, you can mark 2 Stress to succeed instead, ending the tincture's effect.","ru":"Настойка Укреплённых Мыслей","rud":"Вы снимаете 1d4 Стресса и получаете преимущество к броскам реакции против эффектов, изменяющих ваше состояние рассудка. При провале такого броска реакции вы можете получить 2 Стресса вместо провала, завершая действие настойки.","img":"w95.webp"},{"id":"w96","src":"wondrous","kind":"consumable","roll":96,"en":"Tome of Ancient Knowledge","ende":"As a downtime project you can read this book to permanently increase your Knowledge modifier by +1. Once you do this, the book's pages turn blank.","ru":"Фолиант Древних Знаний","rud":"В рамках длительного проекта вы можете прочитать эту книгу, чтобы навсегда увеличить модификатор Знания на +1. После этого страницы книги становятся пустыми.","img":"w96.webp"},{"id":"w97","src":"wondrous","kind":"item","roll":97,"en":"Tortoise Horn","ende":"If you use this bony fragment as a pommel for a weapon that doesn't already have a feature, the weapon gains the following feature. Concussive: Before you make an attack roll, you can mark a Stress to gain a +1 bonus to your Proficiency for that attack.","ru":"Рог Черепахи","rud":"Если вы используете этот костяной фрагмент как навершие для оружия без свойства, оружие получает следующее свойство. Сотрясающий: перед броском атаки вы можете получить Стресс, чтобы получить +1 к Мастерству для этой атаки.","img":"w97.webp"},{"id":"w98","src":"wondrous","kind":"consumable","roll":98,"en":"Toxilily Bulb","ende":"This bulb can be broken into 1d4 cloves, each of which can be smeared on a weapon. Until your next rest, you add your Proficiency to the damage rolls for the weapon.","ru":"Луковица Ядолилии","rud":"Эту луковицу можно разделить на 1d4 дольки, каждую из которых можно нанести на оружие. До следующего отдыха вы добавляете Мастерство к броскам урона этим оружием.","img":"w98.webp"},{"id":"w99","src":"wondrous","kind":"consumable","roll":99,"en":"Trinity Flower Petals","ende":"Brew these petals into a tea that can be drunk by up to three creatures, giving them confidence. Until their next long rest, they are immune to fear-related effects.","ru":"Лепестки Цветка Троицы","rud":"Заварите эти лепестки в чай, который могут выпить до трёх существ, придавая им уверенность. До следующего долгого отдыха они невосприимчивы к эффектам, связанным со Страхом.","img":"w99.webp"},{"id":"w100","src":"wondrous","kind":"consumable","roll":100,"en":"Trinity Flower Seed","ende":"Eating this seed grants the wisdom of the Triple Goddess, giving advantage on Insight Rolls until your next rest.","ru":"Семя Цветка Троицы","rud":"Употребление этого семени дарует мудрость Тройной Богини, давая преимущество к броскам Инстинкта до следующего отдыха.","img":"w100.webp"},{"id":"w101","src":"wondrous","kind":"consumable","roll":101,"en":"True Vision Serum","ende":"For the scene, you can't be fooled by lies, illusions, or deceptions, can see invisible creatures, and have advantage on rolls to notice traps. However, you must mark a Stress to attempt to lie.","ru":"Сыворотка Истинного Зрения","rud":"На время сцены вас нельзя обмануть ложью, иллюзиями или обманом, вы можете видеть невидимых существ и получаете преимущество к броскам обнаружения ловушек. Однако вы должны получить Стресс, чтобы попытаться солгать.","img":"w101.webp"},{"id":"w102","src":"wondrous","kind":"item","roll":102,"en":"Twisted Lens","ende":"When you look through this lens, you can see into the extremely far distance. However, everything you see is distorted and evil-looking. You must succeed on a Presence Reaction Roll (14) or mark a Stress.","ru":"Искажённая Линза","rud":"Когда вы смотрите через эту линзу, вы можете видеть на чрезвычайно большие расстояния. Однако всё, что вы видите, искажено и выглядит злобно. Вы должны преуспеть в броске реакции Влияния (14), иначе получите Стресс.","img":"w102.webp"},{"id":"w103","src":"wondrous","kind":"consumable","roll":103,"en":"Umbra Lily Petals","ende":"After eating a petal, for this scene you can spend a Hope to snuff out a nonmagical or magical light within Close range. Craftinto:.","ru":"Лепестки Тенелилии","rud":"После поедания лепестка на время сцены вы можете потратить Надежду, чтобы погасить немагический или магический источник света в пределах Средней дистанции. Переработать в: Сумеречное Зелье.","img":"w103.webp"},{"id":"w104","src":"wondrous","kind":"consumable","roll":104,"en":"Umbral Potion","ende":"73 LOOT DESCRIPTION Umbral Potion ᶜ Until your next long rest you can spend a Hope to snuff out a nonmagical or magical light within Far range.","ru":"Сумеречное Зелье","rud":"До следующего долгого отдыха вы можете потратить Надежду, чтобы погасить немагический или магический источник света в пределах Дальней дистанции.","img":"w104.webp"},{"id":"w105","src":"wondrous","kind":"item","roll":105,"en":"Veilcloak","ende":"While wearing this, you have advantage on Finesse Rolls made while in darkness. You can also spend a Hope once per long rest to make it shine with dim light up to Close range. Creatures outside that range must mark a Stress to see inside.","ru":"Плащ-Завеса","rud":"Пока вы носите этот плащ, вы получаете преимущество к броскам Искусности в темноте. Вы также можете потратить Надежду один раз за долгий отдых, чтобы он засиял тусклым светом в пределах Средней дистанции. Существа за пределами этой зоны должны получить Стресс, чтобы видеть внутри.","img":"w105.webp"},{"id":"w106","src":"wondrous","kind":"item","roll":106,"en":"Veilshroud Hood","ende":"While wearing this cloak you have advantage on Reaction Rolls against illusions and being magically spied on, but disadvantage on rolls to perceive normal sights and sounds. Once you don the cloak, you must wear it until your next rest or it loses its powers.","ru":"Капюшон Туманного Покрова","rud":"Пока вы носите этот плащ, вы получаете преимущество к броскам реакции против иллюзий и магической слежки, но помеху к броскам восприятия обычных образов и звуков. Надев плащ, вы должны носить его до следующего отдыха, иначе он теряет свои свойства.","img":"w106.webp"},{"id":"w107","src":"wondrous","kind":"consumable","roll":107,"en":"Vial of Crystal Waters","ende":"Drink these waters to switch out a domain card in your vault without spending the Recall Cost.","ru":"Флакон Кристальных Вод","rud":"Выпейте эти воды, чтобы заменить карточку домена в вашем запасе без уплаты стоимости вызова.","img":"w107.webp"},{"id":"w108","src":"wondrous","kind":"consumable","roll":108,"en":"Votive Bloom Nectar","ende":"You clear 1d4 Stress, but the next time you mark a Stress you must succeed on an Insight Reaction Roll or fall down in prayer and become temporarily Vulnerable. Craftinto:.","ru":"Нектар Обетного Цветка","rud":"Вы снимаете 1d4 Стресса, но в следующий раз, когда вы получаете Стресс, вы должны преуспеть в броске реакции Инстинкта или пасть на колени в молитве и временно стать Уязвимым. Переработать в: Настойку Укреплённых Мыслей.","img":"w108.webp"},{"id":"w109","src":"wondrous","kind":"item","roll":109,"en":"War God's Sigil","ende":"You can transfer this design onto armor that doesn't have a feature. It gains the following feature: Herald ofWar: On your first attack in a scene, you can add your Presence to the attack roll.","ru":"Сигил Бога Войны","rud":"Вы можете перенести этот узор на броню без свойства. Она получает следующее свойство. Глашатай войны: при первой атаке в сцене вы можете прибавить Влияние к броску атаки.","img":"w109.webp"},{"id":"w110","src":"wondrous","kind":"consumable","roll":110,"en":"Wardstone Charm","ende":"While wearing this pendant, you can automatically succeed on one Reaction Roll against a fear-based effect, or crush it pre-emptively to create a region of calm, giving creatures within Close range advantage on such Reaction Rolls for the scene. In either case the charm disintegrates to dust after use.","ru":"Охранный Оберег","rud":"Пока вы носите этот кулон, вы можете автоматически преуспеть в одном броске реакции против эффекта, основанного на Страхе, или раздавить его заблаговременно, создав зону покоя и давая существам в пределах Средней дистанции преимущество к таким броскам реакции на время сцены. В любом случае оберег рассыпается в пыль после использования.","img":"w110.webp"},{"id":"w111","src":"wondrous","kind":"consumable","roll":111,"en":"Wine of Discourse","ende":"When one or more creatures share a conversation while sharing this bottle of wine, each one gains a +1 bonus to Presence and Knowledge Rolls until the bottle is finished.","ru":"Вино Бесед","rud":"Когда одно или несколько существ ведут беседу, разделяя эту бутылку вина, каждое получает +1 к броскам Влияния и Знания до тех пор, пока бутылка не опустеет.","img":"w111.webp"},{"id":"w112","src":"wondrous","kind":"item","roll":112,"en":"Winter Wolf Cloak","ende":"While wearing this cloak, when you cause an adversary to mark 1 or more Hit Points, you can spend a Hope to increase your Evasion by 1 until you next take damage. You can't stack this effect.","ru":"Плащ Зимнего Волка","rud":"Пока вы носите этот плащ, когда вы вынуждаете противника получить 1 или более Ран, вы можете потратить Надежду, чтобы увеличить ваше Уклонение на 1 до следующего получения урона. Этот эффект нельзя суммировать.","img":"w112.webp"},{"id":"w113","src":"wondrous","kind":"item","roll":113,"en":"Witherroot Charm","ende":"Once per long rest, you can ignore all damage from a psychic attack. You then have disadvantage on Presence Reaction Rolls until you take a downtime move to purge the charm of psychic residue.","ru":"Оберег Вянущего Корня","rud":"Один раз за долгий отдых вы можете игнорировать весь урон от психической атаки. После этого вы получаете помеху к броскам реакции Влияния, пока не используете ход привала для очищения оберега от психических остатков.","img":"w113.webp"},{"id":"w114","src":"wondrous","kind":"consumable","roll":114,"en":"Witherroot Ichor","ende":"Mark 1d4 HP and permanently lose 1 HP slot. The next spell you cast this scene that deals damage marks the same number of additional HP on one of its targets. Craftinto:.","ru":"Ихор Вянущего Корня","rud":"Получите 1d4 Раны и навсегда потеряйте 1 ячейку Ран. Следующее заклинание, произнесённое вами в этой сцене и наносящее урон, заставляет одну из целей получить то же количество дополнительных Ран. Переработать в: Тоник Вянущего Корня.","img":"w114.webp"},{"id":"w115","src":"wondrous","kind":"consumable","roll":115,"en":"Witherroot Tonic","ende":"Witherroot Tonic ᶜ The next spell you cast this scene that deals damage marks an additional 1d4 HP on one of its targets.","ru":"Тоник Вянущего Корня","rud":"Следующее заклинание, произнесённое вами в этой сцене и наносящее урон, заставляет одну из целей получить дополнительно 1d4 Раны.","img":"w115.webp"},{"id":"w116","src":"wondrous","kind":"item","roll":116,"en":"Wolffriend Pendant","ende":"While wearing this item, dogs and wolves will not attack you unless you harm them or their packmates, and you have advantage on rolls to befriend or influence them.","ru":"Подвеска Волчьего Друга","rud":"Пока вы носите этот предмет, собаки и волки не будут нападать на вас, если вы не причините вред им или их стае, а вы получаете преимущество к броскам на установление дружбы с ними или влияние на них.","img":"w116.webp"},{"id":"w117","src":"wondrous","kind":"item","roll":117,"en":"Wraith Trap","ende":"This box can hold up to three undead spirits. You can make a Finesse Roll to trap a noncorporeal undead creature, with a +1 bonus for every HP the target has marked. For each trapped spirit, you have a -1 penalty to reaction rolls against psychic attacks.","ru":"Призракоуловитель","rud":"Эта шкатулка может вмещать до трёх духов нежити. Вы можете совершить бросок Искусности, чтобы поймать нетелесное существо нежити, получая +1 к броску за каждую Рану цели. За каждого пойманного духа вы получаете -1 к броскам реакции против психических атак.","img":"w117.webp"},{"id":"w118","src":"wondrous","kind":"item","roll":118,"en":"Yeti Coat","ende":"While wearing this coat you take half damage from exposure to cold. In freezing temperatures, you can mark 3 Stress to transform into a Yeti as if using a Druid's Beastform feature (use the Powerful Beast form)","ru":"Шкура Йети","rud":"Пока вы носите эту шкуру, вы получаете половину урона от холода. В условиях замораживающих температур вы можете получить 3 Стресса, чтобы превратиться в Йети, как при использовании свойства звериной формы Друида (используйте форму Могучего Зверя)","img":"w118.webp"},{"id":"w119","src":"wondrous","kind":"consumable","roll":119,"en":"Yifang Sands","ende":"When this black powder catches fire or experiences a strong concussive force, it ignites and explodes, dealing 3d10 magic damage to any creature within Close range. Creatures outside Very Close range can halve the damage with a successful Agility Reaction Roll (16)","ru":"Пески Ифанга","rud":"Когда этот чёрный порошок загорается или испытывает сильный удар, он воспламеняется и взрывается, нанося 3d10 магического урона любому существу в пределах Средней дистанции. Существа за пределами Ближней дистанции могут вдвое уменьшить урон при успешном броске реакции Проворности (16)","img":"w119.webp"}],"community":[{"id":"cm1","src":"community","kind":"item","roll":1,"en":"Royal Brooch","ende":"Wearing this brooch openly while within a Highborne domain or settlement grants advantage on Presence Rolls made to persuade, negotiate, or request favors.","ru":"Королевская Брошь","rud":"Пока вы открыто носите эту брошь на территории или в поселении Благородных, вы получаете преимущество к броскам Влияния с целью убедить, договориться или попросить об одолжении.","img":"cm1.webp","community":"Highborne","community_ru":"Великородное"},{"id":"cm2","src":"community","kind":"item","roll":2,"en":"Duelist's Gilded Whetstone","ende":"During any downtime, you may use a move to sharpen a weapon. Until the next downtime, attacks made with that weapon add your Proficiency to the damage roll.","ru":"Позолоченный Точильный Камень Дуэлянта","rud":"В качестве хода привала вы можете наточить оружие этим камнем. До следующего привала атаки этим оружием прибавляют ваше Мастерство к броскам урона.","img":"cm2.webp","community":"Highborne","community_ru":"Великородное"},{"id":"cm3","src":"community","kind":"item","roll":3,"en":"Gilded Monocle","ende":"While wearing this jeweled monocle, you can see objects, markings, or details hidden by illusions or subtle magical effects.","ru":"Позолоченный Монокль","rud":"Пока вы носите этот монокль, вы можете видеть предметы, метки или детали, скрытые иллюзиями или тонкой магией.","img":"cm3.webp","community":"Highborne","community_ru":"Великородное"},{"id":"cm4","src":"community","kind":"item","roll":4,"en":"Trained Messenger Bird","ende":"A trained falcon, hawk, or other elegant bird kept within a shrinking magical cage. When released, it can carry a short written message to the.","ru":"Обученная Посыльная Птица","rud":"Обученный сокол, ястреб или иная изящная птица, содержащаяся в уменьшающейся магической клетке. Выпущенная, она может доставить короткое письменное послание в сообщество Благородных, где была получена, призывая помощь, информацию или связь.","img":"cm4.webp","community":"Highborne","community_ru":"Великородное"},{"id":"cm5","src":"community","kind":"item","roll":5,"en":"Masquerade Mask","ende":"While attending a social gathering, you may spend 1 Hope to gain useful information by dancing, mingling, or conversing discreetly with others at the event.","ru":"Маска Маскарада","rud":"На светском приёме вы можете потратить 1 Надежду, чтобы добыть полезные сведения, танцуя, общаясь или беседуя украдкой с другими гостями.","img":"cm5.webp","community":"Highborne","community_ru":"Великородное"},{"id":"cm6","src":"community","kind":"item","roll":6,"en":"Guild Amulet","ende":"When you would take magical damage, you may reduce the damage by 1d10. After this effect is used, the amulet cannot be activated again until your next rest.","ru":"Гильдейский Амулет","rud":"Когда вы должны получить магический урон, вы можете уменьшить его на 1d10. После использования этого свойства амулет нельзя активировать снова до следующего отдыха.","img":"cm6.webp","community":"Highborne","community_ru":"Великородное"},{"id":"cm7","src":"community","kind":"item","roll":7,"en":"Lover's Earrings","ende":"Once per session, while wearing one of these earrings, you may focus on the person wearing the matching piece to sense their emotional state, revealing whether they are safe, distressed, or at ease, as determined by the table and the fiction.","ru":"Серьги Влюблённых","rud":"Один раз за сессию, нося одну из этих серёг, вы можете сосредоточиться на человеке, носящем парную серьгу, чтобы почувствовать его эмоциональное состояние — в безопасности ли он, в беде или спокоен — на усмотрение стола и по обстоятельствам.","img":"cm7.webp","community":"Highborne","community_ru":"Великородное"},{"id":"cm8","src":"community","kind":"item","roll":8,"en":"Trained Noble Mount","ende":"A trained terrestrial mount suited for battle. While riding this mount in an environment where mounted combat is possible, you may move up to Very Far range without making an Agility Roll. If the mount is winged, such as a griffon, you may also fly during combat.","ru":"Обученный Благородный Скакун","rud":"Обученный наземный скакун, приспособленный для боя. Верхом на нём в условиях, где верховой бой возможен, вы можете переместиться на Очень дальнюю дистанцию без броска Проворности. Если скакун крылатый, например грифон, вы также можете летать во время боя.","img":"cm8.webp","community":"Highborne","community_ru":"Великородное"},{"id":"cm9","src":"community","kind":"item","roll":9,"en":"Mantle of Crimson Velvet","ende":"Once per session, when you address allies who can see and hear you, you may make a Presence Roll to deliver a rousing speech. On a success, all allied characters who hear you gain 3 Hope.","ru":"Мантия Алого Бархата","rud":"Один раз за сессию, обратившись к союзникам, которые видят и слышат вас, вы можете совершить бросок Влияния, чтобы произнести воодушевляющую речь. При успехе все союзные персонажи, слышащие вас, получают 3 Надежды.","img":"cm9.webp","community":"Highborne","community_ru":"Великородное"},{"id":"cm10","src":"community","kind":"item","roll":10,"en":"Horn of Nobility","ende":"Once per session, you may sound this horn and make a Presence Roll. On a success, all enemies within Far range who hear the horn become Vulnerable. Horn of Nobility.","ru":"Рог Благородства","rud":"Один раз за сессию вы можете протрубить в этот рог и совершить бросок Влияния. При успехе все враги в пределах Дальней дистанции, слышащие его, становятся Уязвимыми.","img":"cm10.webp","community":"Highborne","community_ru":"Великородное"},{"id":"cm11","src":"community","kind":"item","roll":1,"en":"Everlasting Candle","ende":"When lit, this candle creates an aura within Close range. Creatures inside gain advantage on rolls made to study texts, symbols, or inscriptions. The candle cannot be lit again until the next downtime.","ru":"Вечная Свеча","rud":"Когда эта свеча горит, она создаёт ауру в пределах Средней дистанции. Существа внутри получают преимущество к броскам изучения текстов, символов или надписей. Свечу нельзя зажечь снова до следующего привала.","img":"cm11.webp","community":"Loreborne","community_ru":"Научное"},{"id":"cm12","src":"community","kind":"item","roll":2,"en":"Portable Astrolabe","ende":"During downtime, you may study this astrolabe as a downtime move to gain 1 Hope and advantage on your next Knowledge Roll related to cosmology or a related subject.","ru":"Переносная Астролябия","rud":"В качестве хода привала вы можете изучить эту астролябию, чтобы получить 1 Надежду и преимущество к следующему броску Знания, связанному с космологией или смежной областью.","img":"cm12.webp","community":"Loreborne","community_ru":"Научное"},{"id":"cm13","src":"community","kind":"item","roll":3,"en":"Sage's Ink","ende":"You may write one question with this ink and make a Knowledge Roll (18). On a success, the GM answers truthfully with a response of similar length.","ru":"Чернила Мудреца","rud":"Вы можете записать один вопрос этими чернилами и совершить бросок Знания (18). При успехе Мастер отвечает правдиво ответом схожей длины.","img":"cm13.webp","community":"Loreborne","community_ru":"Научное"},{"id":"cm14","src":"community","kind":"item","roll":4,"en":"Tome of a Thousand Subjects","ende":"When opened, this tome turns to a useful topic chosen through the fiction. Reading it grants advantage on the next roll related to that subject.","ru":"Фолиант Тысячи Предметов","rud":"Открытый, этот фолиант перелистывается на полезную тему, выбранную по обстоятельствам. Чтение его даёт преимущество к следующему броску, связанному с этой темой.","img":"cm14.webp","community":"Loreborne","community_ru":"Научное"},{"id":"cm15","src":"community","kind":"item","roll":5,"en":"Scholar's Lodestone","ende":"While held, this stone subtly points toward the nearest.","ru":"Магнит Учёного","rud":"Пока вы держите этот камень, он тихо указывает в направлении ближайшего сообщества Учёных.","img":"cm15.webp","community":"Loreborne","community_ru":"Научное"},{"id":"cm16","src":"community","kind":"item","roll":6,"en":"Magitech Butterfly","ende":"Once per long rest, by attuning to this small metal butterfly, you may briefly see through its eyes, at the table's discretion.","ru":"Магитехническая Бабочка","rud":"Один раз за долгий отдых, настроившись на эту маленькую металлическую бабочку, вы можете на короткое время смотреть её глазами — на усмотрение стола.","img":"cm16.webp","community":"Loreborne","community_ru":"Научное"},{"id":"cm17","src":"community","kind":"item","roll":7,"en":"Echo Tablet","ende":"Once per session, this stone tablet can record sounds or spoken information and replay them at any later time.","ru":"Эхо-Табличка","rud":"Один раз за сессию эта каменная табличка может записать звуки или произнесённую информацию и воспроизвести их в любое более позднее время.","img":"cm17.webp","community":"Loreborne","community_ru":"Научное"},{"id":"cm18","src":"community","kind":"item","roll":8,"en":"Chronometric Timepiece","ende":"Once per session, you may activate this watch to maintain the spotlight after a failed roll or a roll that generates Fear.","ru":"Хронометрические Часы","rud":"Один раз за сессию вы можете активировать эти часы, чтобы сохранить за собой активацию после провального броска или броска со Страхом.","img":"cm18.webp","community":"Loreborne","community_ru":"Научное"},{"id":"cm19","src":"community","kind":"item","roll":9,"en":"Archivist's Chess Set","ende":"During downtime, you may use this enchanted chess set to perform the Prepare move without consuming one of your downtime move slots.","ru":"Шахматы Архивариуса","rud":"Во время привала вы можете использовать этот зачарованный шахматный набор, чтобы выполнить ход «Подготовка», не тратя на это слот хода привала.","img":"cm19.webp","community":"Loreborne","community_ru":"Научное"},{"id":"cm20","src":"community","kind":"item","roll":10,"en":"Bufonidus' Crystal Sphere","ende":"By spending 1 Hope, you may roll a d20 as your Hope Die for a Spellcast Roll.","ru":"Хрустальный Шар Буфонидуса","rud":"Потратив 1 Надежду, вы можете бросить d20 как Кость Надежды для броска заклинания.","img":"cm20.webp","community":"Loreborne","community_ru":"Научное"},{"id":"cm21","src":"community","kind":"item","roll":1,"en":"Codex of Orderborne Dicta","ende":"Once per rest, you may read one dictum from this small codex aloud. Allies within Close range who can hear you gain +1 to their next Attack Roll.","ru":"Кодекс Устава Упорядоченных","rud":"Один раз за отдых вы можете зачитать вслух один постулат из этого небольшого кодекса. Союзники в пределах Средней дистанции, слышащие вас, получают +1 к следующему броску атаки.","img":"cm21.webp","community":"Orderborne","community_ru":"Догматичное"},{"id":"cm22","src":"community","kind":"item","roll":2,"en":"Arcane Restraining Manacles","ende":"These enchanted manacles can adjust their size to fit different creatures. A restrained target gains the Restrained condition, with a roll possibly required in chaotic situations, at the table's discretion.","ru":"Магические Сковывающие Кандалы","rud":"Эти зачарованные кандалы подстраиваются под размер разных существ. Скованная цель получает состояние Схваченного; в хаотичных ситуациях может потребоваться бросок — на усмотрение стола.","img":"cm22.webp","community":"Orderborne","community_ru":"Догматичное"},{"id":"cm23","src":"community","kind":"item","roll":3,"en":"Enchanted Weapon Sheath","ende":"Before rolling damage for an attack, you may mark 1 Stress to reroll one damage die and keep the new result.","ru":"Зачарованные Ножны","rud":"Перед броском урона при атаке вы можете получить Стресс, чтобы перебросить одну кость урона и оставить новый результат.","img":"cm23.webp","community":"Orderborne","community_ru":"Догматичное"},{"id":"cm24","src":"community","kind":"item","roll":4,"en":"Menacing Standard","ende":"Once per session, when this banner is raised during battle, all allies within Far range who can see it gain 1 Hope.","ru":"Угрожающее Знамя","rud":"Один раз за сессию, когда это знамя поднято в бою, все союзники в пределах Дальней дистанции, видящие его, получают 1 Надежду.","img":"cm24.webp","community":"Orderborne","community_ru":"Догматичное"},{"id":"cm25","src":"community","kind":"item","roll":5,"en":"Orderborne Tabard","ende":"Once per long rest. while wearing this tabard, you may invoke its symbol. One adversary who can see it becomes Vulnerable, reflecting fear or hesitation inspired by the Orderborne insignia.","ru":"Табард Упорядоченных","rud":"Один раз за долгий отдых, нося этот табард, вы можете воззвать к его символу. Один противник, видящий его, становится Уязвимым, охваченный страхом или замешательством перед знаком Упорядоченных.","img":"cm25.webp","community":"Orderborne","community_ru":"Догматичное"},{"id":"cm26","src":"community","kind":"item","roll":6,"en":"Meteoric-Tipped Arrows and Bolts","ende":"Up to three times per rest, when you hit a target with this ammunition, the target must mark 1 Stress.","ru":"Стрелы и Болты с Метеоритными Наконечниками","rud":"До трёх раз за отдых: когда вы попадаете по цели этими боеприпасами, она должна получить Стресс.","img":"cm26.webp","community":"Orderborne","community_ru":"Догматичное"},{"id":"cm27","src":"community","kind":"item","roll":7,"en":"Horned Helm","ende":"You may charge a target within Far range. After making an Agility Roll to move, you may immediately make an attack that automatically hits and deals 1d12 damage.","ru":"Рогатый Шлем","rud":"Вы можете броситься на цель в пределах Дальней дистанции. Совершив бросок Проворности для перемещения, вы можете немедленно нанести удар, который автоматически попадает и наносит 1d12 урона.","img":"cm27.webp","community":"Orderborne","community_ru":"Догматичное"},{"id":"cm28","src":"community","kind":"item","roll":8,"en":"Portable Bridge","ende":"This engineered bridge can be deployed to span gaps up to Far range. Extending or retracting it requires time and relative safety, at the table's discretion.","ru":"Переносной Мост","rud":"Этот инженерный мост разворачивается, чтобы перекрыть пропасти протяжённостью до Дальней дистанции. Его развёртывание или складывание требует времени и относительной безопасности — на усмотрение стола.","img":"cm28.webp","community":"Orderborne","community_ru":"Догматичное"},{"id":"cm29","src":"community","kind":"item","roll":9,"en":"Dimensional Prison Sphere","ende":"You may imprison a humanoid-sized creature inside this sphere. The target must be incapacitated or willing.","ru":"Сфера Пространственной Тюрьмы","rud":"Вы можете заключить существо размером с человека внутрь этой сферы. Цель должна быть недееспособна или добровольно согласна.","img":"cm29.webp","community":"Orderborne","community_ru":"Догматичное"},{"id":"cm30","src":"community","kind":"item","roll":10,"en":"War Drum of the Fallen Host","ende":"By making a Presence Roll (15) while playing this drum, you summon a spectral soldier for the duration of the battle. The spirit grants advantage to all ally's next attack or forces all enemies to mark 1 Stress","ru":"Военный Барабан Павшего Войска","rud":"Совершив бросок Влияния (15) во время игры на этом барабане, вы вызываете призрачного солдата на время боя. Дух даёт преимущество к следующему броску атаки всем союзникам или вынуждает всех врагов получить Стресс.","img":"cm30.webp","community":"Orderborne","community_ru":"Догматичное"},{"id":"cm31","src":"community","kind":"item","roll":1,"en":"Sap Liquor","ende":"Once per long rest, you may drink this replenishing liquor to recover 1d4 Stress and gain 1 Hope. The bottle magically refills after each long rest.","ru":"Древесная Настойка","rud":"Один раз за долгий отдых вы можете выпить эту восстанавливающую настойку, чтобы снять 1d4 Стресса и получить 1 Надежду. Бутылка магически наполняется после каждого долгого отдыха.","img":"cm31.webp","community":"Ridgeborne","community_ru":"Горное"},{"id":"cm32","src":"community","kind":"item","roll":2,"en":"Climbing Pitons","ende":"Once per session, when the GM spends a Fear to introduce a complication related to terrain, falling, or exhaustion during a climb or mountain traversal, you may negate that effect.","ru":"Скальные Крючья","rud":"Один раз за сессию, когда Мастер тратит Страх, чтобы ввести осложнение, связанное с рельефом, падением или усталостью во время подъёма или горного перехода, вы можете отменить этот эффект.","img":"cm32.webp","community":"Ridgeborne","community_ru":"Горное"},{"id":"cm33","src":"community","kind":"item","roll":3,"en":"Goatstep Boots","ende":"By marking 1 Stress, you may leap up to Close range, overcoming obstacles or reaching positions normally impossible with a standard jump.","ru":"Козьи Сапоги","rud":"Получив Стресс, вы можете прыгнуть на Среднюю дистанцию, преодолевая препятствия или достигая позиций, обычно недостижимых обычным прыжком.","img":"cm33.webp","community":"Ridgeborne","community_ru":"Горное"},{"id":"cm34","src":"community","kind":"item","roll":4,"en":"Harpoon Crossbow","ende":"This spring-loaded crossbow fires a grappling hook attached to a rope, allowing you to secure lines and anchors on otherwise unreachable surfaces, including vertical faces.","ru":"Арбалет-Гарпун","rud":"Этот арбалет с пружинным механизмом выстреливает крюком-кошкой на верёвке, позволяя крепить линии и якоря к иначе недоступным поверхностям, включая вертикальные скалы.","img":"cm34.webp","community":"Ridgeborne","community_ru":"Горное"},{"id":"cm35","src":"community","kind":"item","roll":5,"en":"Wayfarer's Pack","ende":"While carrying this pack during a journey, mountain traversal, or similar overland travel, the first time per session you would mark Stress, you ignore it.","ru":"Котомка Странника","rud":"Во время путешествия, горного перехода или схожего перемещения: первый раз за сессию, когда вы должны получить Стресс, вы игнорируете его.","img":"cm35.webp","community":"Ridgeborne","community_ru":"Горное"},{"id":"cm36","src":"community","kind":"item","roll":6,"en":"Ring of Wild Beasts","ende":"When you communicate with a mountain beast using this ring, you may mark 1 Stress to gain clear information about a nearby threat, path, or environmental danger, as determined by the table and the current fiction.","ru":"Кольцо Диких Зверей","rud":"Общаясь с горным зверем через это кольцо, вы можете получить Стресс, чтобы получить чёткую информацию о ближайшей угрозе, пути или опасности местности — на усмотрение стола и по обстоятельствам.","img":"cm36.webp","community":"Ridgeborne","community_ru":"Горное"},{"id":"cm37","src":"community","kind":"item","roll":7,"en":"Magitech Exoskeleton","ende":"While wearing this exoskeleton, you may mark 1 Stress to perform a feat of strength that would normally be impossible.","ru":"Магитехнический Экзоскелет","rud":"Нося этот экзоскелет, вы можете получить Стресс, чтобы совершить подвиг силы, обычно невозможный.","img":"cm37.webp","community":"Ridgeborne","community_ru":"Горное"},{"id":"cm38","src":"community","kind":"item","roll":8,"en":"Camouflage Mantle","ende":"While wearing this mantle in Ridgeborne terrain, you may blend into the environment. You can activate this mantle to become Hidden until you move. While Hidden in this way, you remain unseen even if an adversary moves to where they would normally see you.","ru":"Маскировочный Плащ","rud":"Нося этот плащ на территории Горцов, вы можете слиться с окружением. Активируйте плащ, чтобы стать Скрытым до тех пор, пока не переместитесь. Оставаясь Скрытым таким образом, вы невидимы, даже если противник переходит на позицию, откуда обычно мог бы вас заметить.","img":"cm38.webp","community":"Ridgeborne","community_ru":"Горное"},{"id":"cm39","src":"community","kind":"item","roll":9,"en":"Totem of the Ridge Beast","ende":"Once perlong rest, you may activate this totem to charge a target you can see. That target, and all adversaries within Very Close range, become Vulnerable. The totem then returns to its inert form.","ru":"Тотем Горного Зверя","rud":"Один раз за долгий отдых вы можете активировать этот тотем, бросившись на видимую цель. Эта цель и все противники в пределах Ближней дистанции становятся Уязвимыми. Тотем возвращается в инертное состояние.","img":"cm39.webp","community":"Ridgeborne","community_ru":"Горное"},{"id":"cm40","src":"community","kind":"item","roll":10,"en":"Felling Axe-Saw","ende":"This massive hybrid tool cuts through wood, roots, and dense natural materials at extreme speed, allowing you to reshape natural terrain in a fraction of the expected time, at the table's discretion","ru":"Топор-Пила Лесоруба","rud":"Этот массивный гибридный инструмент рубит дерево, корни и плотные природные материалы с огромной скоростью, позволяя изменять естественный рельеф за долю обычного времени — на усмотрение стола.","img":"cm40.webp","community":"Ridgeborne","community_ru":"Горное"},{"id":"cm41","src":"community","kind":"item","roll":1,"en":"Folding Boat","ende":"A compact boat that can be folded and carried, then deployed when needed. It can transport up to four Medium creatures, guided by common sense and the current fiction.","ru":"Складная Лодка","rud":"Компактная лодка, которую можно сложить и носить с собой, а при необходимости развернуть. Вмещает до четырёх существ Среднего размера; управление определяется здравым смыслом и обстоятельствами.","img":"cm41.webp","community":"Seaborne","community_ru":"Морское"},{"id":"cm42","src":"community","kind":"item","roll":2,"en":"Navigator's Tools","ende":"During downtime, you may use these tools as a downtime move to gain advantage on navigation rolls at sea until your next rest.","ru":"Инструменты Навигатора","rud":"В качестве хода привала вы можете использовать эти инструменты, чтобы получить преимущество к броскам навигации на море до следующего отдыха.","img":"cm42.webp","community":"Seaborne","community_ru":"Морское"},{"id":"cm43","src":"community","kind":"item","roll":3,"en":"Fishing Rod","ende":"During downtime, when you use the Prepare move with this rod, you gain the usual 1 Hope and catch 1d4 fish. Each fish can later be cooked and eaten to reduce 1 Stress.","ru":"Рыболовная Удочка","rud":"В качестве хода привала «Подготовка» с этой удочкой вы получаете обычную 1 Надежду и вылавливаете 1d4 рыб. Каждую рыбу можно приготовить и съесть, чтобы снять 1 Стресс.","img":"cm43.webp","community":"Seaborne","community_ru":"Морское"},{"id":"cm44","src":"community","kind":"item","roll":4,"en":"Sparrow's Compass","ende":"This compass always points toward what its bearer desires most. Once per session, you gain advantage on an action roll made to reach what the compass indicates.","ru":"Компас Воробья","rud":"Этот компас всегда указывает в направлении того, чего его владелец желает больше всего. Один раз за сессию вы получаете преимущество к броску действия, направленному на то, чтобы добраться до цели компаса.","img":"cm44.webp","community":"Seaborne","community_ru":"Морское"},{"id":"cm45","src":"community","kind":"item","roll":5,"en":"Bottle of Wind","ende":"Once per session, you may uncork this bottle to release powerful winds, pushing boats, knocking creatures prone, or producing other creative effects, at the table's discretion.","ru":"Бутылка Ветра","rud":"Один раз за сессию вы можете откупорить эту бутылку, чтобы высвободить мощный порыв ветра, отталкивающий лодки, валящий существ с ног или производящий иные творческие эффекты — на усмотрение стола.","img":"cm45.webp","community":"Seaborne","community_ru":"Морское"},{"id":"cm46","src":"community","kind":"item","roll":6,"en":"Far-Seer's Spyglass","ende":"Once per long rest, you may use this spyglass to notice details that would normally be too distant to perceive, at the table's discretion.","ru":"Подзорная Труба Дальнозоркого","rud":"Один раз за долгий отдых вы можете использовать эту подзорную трубу, чтобы различить детали, обычно слишком далёкие для восприятия — на усмотрение стола.","img":"cm46.webp","community":"Seaborne","community_ru":"Морское"},{"id":"cm47","src":"community","kind":"item","roll":7,"en":"Turtle Shell Harness","ende":"Once per long rest, when you would take physical damage, you may mark 1 Stress to reduce the damage threshold by one step.","ru":"Черепаший Панцирный Нагрудник","rud":"Один раз за долгий отдых, когда вы должны получить физический урон, вы можете получить Стресс, чтобы снизить порог урона на одну ступень.","img":"cm47.webp","community":"Seaborne","community_ru":"Морское"},{"id":"cm48","src":"community","kind":"item","roll":8,"en":"Lantern of the Depths","ende":"This lantern produces steady light that functions normally underwater, illuminating its surroundings as if above the surface, even in murky water.","ru":"Фонарь Глубин","rud":"Этот фонарь создаёт ровный свет, работающий под водой как на поверхности, освещая окрестности даже в мутной воде.","img":"cm48.webp","community":"Seaborne","community_ru":"Морское"},{"id":"cm49","src":"community","kind":"item","roll":9,"en":"Pirate's Treasure Map","ende":"This enchanted map constantly redraws itself, marking the location of the nearest significant hoard of gold or valuables worth pursuing. The treasure is always real, but never unguarded, and often comes with complications chosen by the GM and the current fiction.","ru":"Пиратская Карта Сокровищ","rud":"Эта зачарованная карта постоянно перерисовывается, отмечая местоположение ближайшего значимого запаса золота или ценностей. Сокровище всегда настоящее, но никогда не бывает без охраны и нередко сопряжено с осложнениями, выбранными Мастером по обстоятельствам.","img":"cm49.webp","community":"Seaborne","community_ru":"Морское"},{"id":"cm50","src":"community","kind":"item","roll":10,"en":"Kraken's Call Flute","ende":"This ancient flute can be played once per campaign to summon a marine leviathan. The creature does not obey the bearer, but its arrival unleashes overwhelming chaos capable of reshaping even the most desperate situation","ru":"Флейта Зова Кракена","rud":"Эту древнюю флейту можно использовать один раз за кампанию, чтобы призвать морского левиафана. Существо не подчиняется владельцу, но его появление высвобождает сокрушительный хаос, способный изменить исход даже самой безнадёжной ситуации.","img":"cm50.webp","community":"Seaborne","community_ru":"Морское"},{"id":"cm51","src":"community","kind":"item","roll":1,"en":"Loaded Cards and Dice","ende":"Grant advantage on Finesse rolls when attempting to cheat at games of chance.","ru":"Крапленые Карты и Кости","rud":"Дают преимущество к броскам Искусности при попытке жульничать в играх с удачей.","img":"cm51.webp","community":"Slyborne","community_ru":"Криминальное"},{"id":"cm52","src":"community","kind":"item","roll":2,"en":"Returning Coin","ende":"This coin always finds its way back into its owner's pocket, no matter how it is spent or lost.","ru":"Возвратная Монета","rud":"Эта монета всегда возвращается в карман владельца, как бы её ни потратили или ни потеряли.","img":"cm52.webp","community":"Slyborne","community_ru":"Криминальное"},{"id":"cm53","src":"community","kind":"item","roll":3,"en":"Living Puppets","ende":"Once per session, these animated puppets can slip through tight spaces to pull levers, press buttons, or steal small objects.","ru":"Живые Марионетки","rud":"Один раз за сессию эти ожившие куклы могут проникать в узкие пространства, чтобы дёргать рычаги, нажимать кнопки или похищать небольшие предметы.","img":"cm53.webp","community":"Slyborne","community_ru":"Криминальное"},{"id":"cm54","src":"community","kind":"item","roll":4,"en":"Glass Eye Pendant","ende":"Once per long rest, when you are attacked, roll 1d4 and add the result to your Evasion for that attack.","ru":"Подвеска Стеклянного Глаза","rud":"Один раз за долгий отдых, когда на вас нападают, бросьте 1d4 и прибавьте результат к вашему Уклонению против этой атаки.","img":"cm54.webp","community":"Slyborne","community_ru":"Криминальное"},{"id":"cm55","src":"community","kind":"item","roll":5,"en":"Treacherous Knuckle-Duster","ende":"You may mark 1 Stress before an attack roll. If the attack succeeds, the target marks 1 Stress.","ru":"Предательский Кастет","rud":"Вы можете получить Стресс перед броском атаки. Если атака успешна, цель получает Стресс.","img":"cm55.webp","community":"Slyborne","community_ru":"Криминальное"},{"id":"cm56","src":"community","kind":"item","roll":6,"en":"Thief's Chime Bracelet","ende":"Once per session, make a Finesse Roll (18) to play a hypnotic melody. On a success, all unaware creatures within Close range fall into a deep sleep until disturbed or after a short rest.","ru":"Браслет Воровского Перезвона","rud":"Один раз за сессию совершите бросок Искусности (18), чтобы сыграть гипнотическую мелодию. При успехе все не подозревающие об этом существа в пределах Средней дистанции погружаются в глубокий сон до тех пор, пока их не потревожат или до конца короткого отдыха.","img":"cm56.webp","community":"Slyborne","community_ru":"Криминальное"},{"id":"cm57","src":"community","kind":"item","roll":7,"en":"Shadow Amulet","ende":"Once per session, create a bubble of darkness within Close range. Enemies inside suffer disadvantage, while allies gain advantage on rolls to hide or escape.","ru":"Теневой Амулет","rud":"Один раз за сессию создайте пузырь тьмы в пределах Средней дистанции. Враги внутри получают помеху, тогда как союзники получают преимущество к броскам на укрытие или побег.","img":"cm57.webp","community":"Slyborne","community_ru":"Криминальное"},{"id":"cm58","src":"community","kind":"item","roll":8,"en":"Alleyway Ocarina","ende":"Once per session, in an urban or Slyborne environment, play a short tune to call hidden allies and cutthroats from the shadows. The next successful attack made by you or an ally adds +1d10 damage.","ru":"Переулочная Окарина","rud":"Один раз за сессию, в городской обстановке или на территории Хитроумных, сыграйте короткую мелодию, чтобы вызвать из теней укрывшихся союзников и головорезов. Следующая успешная атака вас или союзника добавляет +1d10 урона.","img":"cm58.webp","community":"Slyborne","community_ru":"Криминальное"},{"id":"cm59","src":"community","kind":"item","roll":9,"en":"Mantle of the Backstreets","ende":"While wearing this mantle in an urban or Slyborne environment, you are magically overlooked as part of the surroundings. This effect ends immediately if you take a hostile or overtly suspicious action.","ru":"Плащ Переулков","rud":"Нося этот плащ в городской обстановке или на территории Хитроумных, вы магически воспринимаетесь как часть окружения. Эффект немедленно заканчивается, если вы совершаете враждебное или явно подозрительное действие.","img":"cm59.webp","community":"Slyborne","community_ru":"Криминальное"},{"id":"cm60","src":"community","kind":"item","roll":10,"en":"False Gold Tooth","ende":"Bite down on this false golden tooth to enter a deathlike state. You appear dead and cannot be awakened, regaining consciousness after the period of a long rest","ru":"Фальшивый Золотой Зуб","rud":"Прикусите этот зуб, чтобы впасть в смертеподобное состояние. Вы выглядите мёртвым и не можете быть разбужены, возвращая сознание по истечении времени, равного долгому отдыху.","img":"cm60.webp","community":"Slyborne","community_ru":"Криминальное"},{"id":"cm61","src":"community","kind":"item","roll":1,"en":"Shadowmark Chalk","ende":"You can write messages or symbols using this magical chalk. Marks are visible only in darkness or heavy shadow.","ru":"Теневой Мел","rud":"Вы можете писать послания или рисовать символы этим магическим мелом. Метки видны только в темноте или густой тени.","img":"cm61.webp","community":"Underborne","community_ru":"Подземное"},{"id":"cm62","src":"community","kind":"item","roll":2,"en":"Blind Dowser's Rods","ende":"You have advantage on rolls made to locate underground water sources, seepage, or hidden reservoirs.","ru":"Прутья Слепого Лозоходца","rud":"Вы получаете преимущество к броскам для обнаружения подземных водоносных слоёв, просачиваний или скрытых водоёмов.","img":"cm62.webp","community":"Underborne","community_ru":"Подземное"},{"id":"cm63","src":"community","kind":"item","roll":3,"en":"Fungal Forager's Pouch","ende":"Once per long rest, this pouch produces a portion of edible subterranean fungi. Consuming the fungi restores 1 HP.","ru":"Сумка Грибника","rud":"Один раз за долгий отдых эта сумка производит порцию съедобных подземных грибов. Поедание грибов снимает 1 Рану.","img":"cm63.webp","community":"Underborne","community_ru":"Подземное"},{"id":"cm64","src":"community","kind":"item","roll":4,"en":"Mask of the Deep","ende":"While wearing this mask, you have advantage on Reaction Rolls to resist effects involving inhalation, breath, fumes, spores, or gas, including enemy attacks delivered through such means.","ru":"Маска Глубин","rud":"Нося эту маску, вы получаете преимущество к броскам реакции для сопротивления эффектам, связанным с вдыханием, парами, спорами или газом, включая атаки противников, доставляемые подобными способами.","img":"cm64.webp","community":"Underborne","community_ru":"Подземное"},{"id":"cm65","src":"community","kind":"item","roll":5,"en":"Fungal Torch","ende":"This bioluminescent fungus functions as a normal torch. While lit underground, you have advantage on rolls to orient yourself and navigate the subterranean environment.","ru":"Грибной Факел","rud":"Этот биолюминесцентный гриб работает как обычный факел. Горя под землёй, он даёт преимущество к броскам ориентирования и навигации в подземной среде.","img":"cm65.webp","community":"Underborne","community_ru":"Подземное"},{"id":"cm66","src":"community","kind":"item","roll":6,"en":"Spider Silk Spool","ende":"You may make a Finesse Roll to throw the silk at a creature within Close range. On a success, the target becomes Restrained until it breaks free or the fiction changes.","ru":"Моток Паучьего Шёлка","rud":"Вы можете совершить бросок Искусности, чтобы бросить шёлк в существо в пределах Средней дистанции. При успехе цель становится Схваченной, пока не вырвется на свободу или пока обстоятельства не изменятся.","img":"cm66.webp","community":"Underborne","community_ru":"Подземное"},{"id":"cm67","src":"community","kind":"item","roll":7,"en":"Reaction Boots","ende":"Once per session, when an ally fails a roll or succeeds with Fear, you may immediately take the spotlight instead of the GM.","ru":"Сапоги Реакции","rud":"Один раз за сессию, когда союзник проваливает бросок или преуспевает со Страхом, вы можете немедленно взять активацию вместо Мастера.","img":"cm67.webp","community":"Underborne","community_ru":"Подземное"},{"id":"cm68","src":"community","kind":"item","roll":8,"en":"Cave Spider Fang","ende":"You can use this venomous fang in place of a weapon when making an attack. On a hit, the target takes no damage but becomes Vulnerable. This effect has no impact on undead or creatures immune to poison.","ru":"Клык Пещерного Паука","rud":"Вы можете использовать этот ядовитый клык вместо оружия при атаке. При попадании цель не получает урона, но становится Уязвимой. Этот эффект не действует на нежить или существ с иммунитетом к яду.","img":"cm68.webp","community":"Underborne","community_ru":"Подземное"},{"id":"cm69","src":"community","kind":"item","roll":9,"en":"Bioluminescent Gloves","ende":"While you are in darkness or partial darkness, add 1d6 to your damage rolls.","ru":"Биолюминесцентные Перчатки","rud":"Пока вы находитесь в темноте или полутьме, прибавляйте 1d6 к броскам урона.","img":"cm69.webp","community":"Underborne","community_ru":"Подземное"},{"id":"cm70","src":"community","kind":"item","roll":10,"en":"Scarab Amulet","ende":"Once per session, you may activate this amulet to transform into a spectral scarab. While transformed, you cannot attack or use items. You can fly and pass through non-magical walls, doors, stone, or earth that are no thicker than the width of a typical structure or connected cavern wall. The transformation lasts until you choose to end it or until the duration of a short rest. Scarab Amulet.","ru":"Амулет Скарабея","rud":"Один раз за сессию вы можете активировать этот амулет, чтобы превратиться в призрачного скарабея. В этой форме вы не можете атаковать или использовать предметы, но можете летать и проходить сквозь немагические стены, двери, камень или землю толщиной не более стандартной конструкции или прилегающей пещерной стены. Превращение длится, пока вы не завершите его или до конца короткого отдыха.","img":"cm70.webp","community":"Underborne","community_ru":"Подземное"},{"id":"cm71","src":"community","kind":"item","roll":1,"en":"Everflame Kindling","ende":"These wooden sticks ignite easily and never fully burn away. They provide a steady flame even in harsh or unlikely environments.","ru":"Вечный Трут","rud":"Эти деревянные палочки легко воспламеняются и никогда не догорают полностью. Они дают ровное пламя даже в суровых или маловероятных условиях.","img":"cm71.webp","community":"Wanderborne","community_ru":"Кочевое"},{"id":"cm72","src":"community","kind":"item","roll":2,"en":"Beastkeeper's Feed Sack","ende":"Once per long rest, this sack produces a ration sufficient to feed one Medium beast.","ru":"Кормовой Мешок Зверовода","rud":"Один раз за долгий отдых этот мешок производит порцию корма, достаточную для одного существа Среднего размера.","img":"cm72.webp","community":"Wanderborne","community_ru":"Кочевое"},{"id":"cm73","src":"community","kind":"item","roll":3,"en":"Guidelight Jar","ende":"This sealed jar holds shifting fireflies. When danger approaches, their glow changes color at the owner's discretion.","ru":"Банка Направляющего Света","rud":"Эта запечатанная банка содержит мерцающих светлячков. Когда опасность приближается, их свечение меняет цвет — по усмотрению владельца.","img":"cm73.webp","community":"Wanderborne","community_ru":"Кочевое"},{"id":"cm74","src":"community","kind":"item","roll":4,"en":"Whispering Skillet","ende":"During a Prepare downtime move, this enchanted pan can turn unlikely ingredients into a nourishing meal. Those who eat it clear a Stress and gain advantage on the next roll.","ru":"Шепчущая Сковорода","rud":"В качестве хода привала «Подготовка» эта зачарованная сковорода может превратить неожиданные ингредиенты в сытную трапезу. Съевшие её снимают Стресс и получают преимущество к следующему броску.","img":"cm74.webp","community":"Wanderborne","community_ru":"Кочевое"},{"id":"cm75","src":"community","kind":"item","roll":5,"en":"Waytamer Saddle","ende":"This enchanted saddle reshapes itself to fit almost any mount. You gain advantage on rolls to calm or control a creature fitted with it.","ru":"Седло Укротителя","rud":"Это зачарованное седло принимает форму почти под любую ездовую скотину. Вы получаете преимущество к броскам успокоения или управления существом, на которое оно надето.","img":"cm75.webp","community":"Wanderborne","community_ru":"Кочевое"},{"id":"cm76","src":"community","kind":"item","roll":6,"en":"Caravan Owl Amulet","ende":"Once per session, when you would mark Stress, roll a d6. On a 4+, ignore that Stress.","ru":"Совиный Амулет Каравана","rud":"Один раз за сессию, когда вы должны получить Стресс, бросьте d6. При результате 4+ вы игнорируете этот Стресс.","img":"cm76.webp","community":"Wanderborne","community_ru":"Кочевое"},{"id":"cm77","src":"community","kind":"item","roll":7,"en":"Pathfinder's Boots","ende":"Once per long rest, when navigating uncertain terrain, you may roll a d20 as your Hope Die instead of a d12.","ru":"Сапоги Первопроходца","rud":"Один раз за долгий отдых, пробираясь через незнакомую местность, вы можете бросить d20 как Кость Надежды вместо d12.","img":"cm77.webp","community":"Wanderborne","community_ru":"Кочевое"},{"id":"cm78","src":"community","kind":"item","roll":8,"en":"Foldaway Trail Sled","ende":"When unfolded, this sled carries up to three Medium creatures and glides swiftly over snow, grass, or sand.","ru":"Складные Санки","rud":"Развёрнутые, эти санки вмещают до трёх существ Среднего размера и быстро скользят по снегу, траве или песку.","img":"cm78.webp","community":"Wanderborne","community_ru":"Кочевое"},{"id":"cm79","src":"community","kind":"item","roll":9,"en":"Faunroot Seed","ende":"When planted in natural ground, this legendary seed grows into a massive tree over the course of a long rest.","ru":"Семя Фаункорня","rud":"Посаженное в природную почву, это легендарное семя вырастает в огромное дерево за время долгого отдыха.","img":"cm79.webp","community":"Wanderborne","community_ru":"Кочевое"},{"id":"cm80","src":"community","kind":"item","roll":10,"en":"Foldable SkyBalloon","ende":"A portable marvel requiring about one hour to assemble. It can carry up to five Medium creatures and allows controlled flight to reach distant or otherwise inaccessible places","ru":"Складной Воздушный Шар","rud":"Переносное чудо, требующее около часа для сборки. Вмещает до пяти существ Среднего размера и позволяет управляемый полёт к отдалённым или иначе недоступным местам.","img":"cm80.webp","community":"Wanderborne","community_ru":"Кочевое"},{"id":"cm81","src":"community","kind":"item","roll":1,"en":"Lucky Horn Charm","ende":"Once per session, you may reroll any one die and choose which result to use.","ru":"Оберег Удачного Рога","rud":"Один раз за сессию вы можете перебросить любую кость и выбрать, какой результат использовать.","img":"cm81.webp","community":"Wildborne","community_ru":"Лесное"},{"id":"cm82","src":"community","kind":"item","roll":2,"en":"Gentle Snare","ende":"This magical trap can be set to restrain a creature without causing harm. The target becomes Restrained by invisible bindings until freed.","ru":"Нежный Силок","rud":"Эту магическую ловушку можно установить, чтобы схватить существо, не причиняя ему вреда. Цель становится Схваченной невидимыми путами, пока её не освободят.","img":"cm82.webp","community":"Wildborne","community_ru":"Лесное"},{"id":"cm83","src":"community","kind":"item","roll":3,"en":"Leaf of the Giant Tree","ende":"A massive leaf sturdy as leather and broad as a greatsword. It may serve as a glider, sail, small raft, or improvised tool at the player and GM's discretion.","ru":"Лист Исполинского Дерева","rud":"Огромный лист, прочный как кожа и широкий как двуручный меч. Он может служить планером, парусом, небольшим плотом или импровизированным инструментом — по усмотрению игрока и Мастера.","img":"cm83.webp","community":"Wildborne","community_ru":"Лесное"},{"id":"cm84","src":"community","kind":"item","roll":4,"en":"Forestwarden's Axe","ende":"This seemingly ordinary axe carries the blessing of renewal. Any tree, plant, fungus, or living vegetation cut with it regrows fully over the course of a long rest.","ru":"Топор Лесного Стража","rud":"Этот внешне обычный топор несёт в себе благословение обновления. Любое дерево, растение, гриб или живая растительность, срубленная им, вновь полностью вырастает за время долгого отдыха.","img":"cm84.webp","community":"Wildborne","community_ru":"Лесное"},{"id":"cm85","src":"community","kind":"item","roll":5,"en":"Ring of the Small Explorer","ende":"Once per session, you may shrink to roughly 15 cm in height. While small, you gain advantage where reduced size is beneficial and disadvantage where it would hinder you.","ru":"Кольцо Маленького Исследователя","rud":"Один раз за сессию вы можете уменьшиться примерно до 15 см ростом. В уменьшенном виде вы получаете преимущество там, где малый размер полезен, и помеху там, где он создаёт неудобства.","img":"cm85.webp","community":"Wildborne","community_ru":"Лесное"},{"id":"cm86","src":"community","kind":"item","roll":6,"en":"Moonseed Lantern","ende":"This translucent fruit holds liquid moonlight within. Once per session, you may shake it to release a gentle glow. Wild beasts within Close range become calm and non-hostile unless directly threatened.","ru":"Лунносеменной Фонарь","rud":"Этот прозрачный плод содержит жидкий лунный свет. Один раз за сессию вы можете встряхнуть его, высвободив мягкое сияние. Дикие звери в пределах Средней дистанции успокаиваются и перестают быть враждебными, если не окажутся под прямой угрозой.","img":"cm86.webp","community":"Wildborne","community_ru":"Лесное"},{"id":"cm87","src":"community","kind":"item","roll":7,"en":"Crown of Living Vines","ende":"Once per long rest, the living vines awaken. You may gain advantage on one attack roll or add 1d6 to your Evasion against an incoming attack.","ru":"Венец Живых Лоз","rud":"Один раз за долгий отдых живые лозы пробуждаются. Вы можете получить преимущество к одному броску атаки или прибавить 1d6 к вашему Уклонению против входящей атаки.","img":"cm87.webp","community":"Wildborne","community_ru":"Лесное"},{"id":"cm88","src":"community","kind":"item","roll":8,"en":"Mantle of the First Predator","ende":"The first time you wear this mantle, choose a category of creatures you are sworn to hunt. While wearing it, you may mark 1 Stress to gain advantage on rolls against a creature of that category.","ru":"Плащ Первобытного Хищника","rud":"При первом надевании этого плаща выберите категорию существ, которых вы поклялись охотиться. Нося его, вы можете получить Стресс, чтобы получить преимущество к броскам против существ этой категории.","img":"cm88.webp","community":"Wildborne","community_ru":"Лесное"},{"id":"cm89","src":"community","kind":"item","roll":9,"en":"Heart of the Forest God","ende":"Once per campaign, you may plant this divine heart in natural ground. The surrounding land becomes lush and fertile. Enemies within Far range must mark 1 Stress and become Restrained as roots surge from the earth.","ru":"Сердце Лесного Бога","rud":"Один раз за кампанию вы можете посадить это священное сердце в природную почву. Окружающая земля становится буйной и плодородной. Враги в пределах Дальней дистанции должны получить Стресс и становятся Схваченными, когда из земли вздымаются корни.","img":"cm89.webp","community":"Wildborne","community_ru":"Лесное"},{"id":"cm90","src":"community","kind":"item","roll":10,"en":"Little Forest Spirit","ende":"A playful forest spirit follows you as a silent guardian. When damage would force you to mark your last HP, you may spend 1 Hope to sacrifice the spirit instead. You do not mark that HP and do not make a Death Move. The spirit fades and is gone forever","ru":"Маленький Лесной Дух","rud":"Игривый лесной дух следует за вами как безмолвный страж. Когда урон вынудит вас получить последнюю Рану, вы можете потратить 1 Надежду, чтобы пожертвовать духом. Вы не получаете эту Рану и не совершаете ход смерти. Дух исчезает навсегда.","img":"cm90.webp","community":"Wildborne","community_ru":"Лесное"}]},"alt":{"item":{"common":{"hope":["hi2","ci1","ci2","ci4","hi7","hi6","ci5","ci7","ci10","hi8","hi9","hi11"],"fear":["hi1","hi3","ci3","hi4","ci6","ci8","ci9","hi10","hi12","hi5","ci11","ci12"]},"uncommon":{"hope":["ci13","hi13","hi14","ci15","ci17","hi16","hi19","ci18","ci19","ci20","hi21","hi24"],"fear":["ci14","hi15","ci16","hi17","hi18","hi20","ci21","ci22","hi22","ci23","hi23","ci24"]},"rare":{"hope":["ci27","hi26","hi27","ci36","ci29","hi29","hi30","hi32","hi33","ci32","ci34","ci33"],"fear":["ci25","ci26","hi25","ci28","hi28","ci30","ci31","hi31","ci35","hi34","hi35","hi36"]},"very_rare":{"hope":["ci37","ci38","ci39","ci40","hi39","ci41","ci42","ci43","ci44","ci45","ci46","ci47"],"fear":["hi37","hi38","hi40","hi41","hi42","hi43","hi44","hi45","hi46","hi47","hi48","ci48"]},"legendary":{"hope":["hi51","ci50","ci51","hi49","hi50","hi52","hi53","hi54","ci52","ci60","hi59","hi60"],"fear":["ci49","ci53","ci54","ci55","ci56","ci57","ci58","ci59","hi55","hi56","hi57","hi58"]}},"consumable":{"common":{"hope":["cc1","cc2","cc3","cc4","cc5","cc6","hc1","hc4","cc7","cc8","hc7","cc10"],"fear":["hc2","hc3","hc5","hc6","cc9","hc8","hc9","hc10","hc11","cc11","hc12","cc12"]},"uncommon":{"hope":["hc13","cc13","hc14","cc17","hc16","cc18","cc19","cc20","hc20","cc21","cc23","cc22"],"fear":["cc14","cc15","hc15","cc16","hc17","hc18","hc19","hc21","hc22","hc23","hc24","cc24"]},"rare":{"hope":["cc25","cc26","cc27","cc28","cc29","cc30","hc25","hc26","hc27","hc30","cc34","hc32"],"fear":["hc28","cc31","hc29","cc32","cc33","cc35","cc36","hc33","hc34","hc31","hc35","hc36"]},"very_rare":{"hope":["cc37","hc39","cc39","cc41","hc40","cc43","cc44","cc46","hc43","hc46","hc48","cc48"],"fear":["hc37","cc38","hc38","cc40","hc41","hc42","cc42","cc45","hc44","hc45","hc47","cc47"]},"legendary":{"hope":["cc49","cc50","hc49","hc50","cc51","hc51","cc52","cc53","cc54","cc56","hc60","cc60"],"fear":["hc52","hc53","hc54","hc55","cc55","cc57","hc56","hc57","hc58","cc58","hc59","cc59"]}}}};
